class MatchEnrichmentCache:
    """
    Caché persistente (Firestore + memoria fallback) y coordinador controlado de fuentes secundarias
    (SofaScore, ESPN, API-Sports).
    - Fuente principal: football-data.org.
    - Fuentes secundarias: únicamente respaldo para métricas ausentes en football-data.org.
    - NUNCA se invoca desde /obtener-pronostico ni renderizado de cartelera; solo worker/tarea/admin.
    - Registra por dato: fuente, fecha_consulta, fecha_vencimiento, nivel_verificacion, partido_asociado.
    - Si dos fuentes difieren, registra discrepancia y NO escoge silenciosamente ni mezcla valores.
    """
    _LOCK = threading.RLock()
    _STORE = {}
    _CALENDAR_AUDIT_LOG = []
    COLLECTION_NAME = "match_enrichment_cache"

    @classmethod
    def make_key(cls, fecha: str, home: str, away: str) -> str:
        nf = globals().get("_norm_equipo")
        h = nf(home) if nf else (home or "").lower().strip()
        a = nf(away) if nf else (away or "").lower().strip()
        return f"{str(fecha or '')[:10]}|{h}|{a}"

    @classmethod
    def _firestore_doc_id(cls, key: str) -> str:
        return re.sub(r"[^a-zA-Z0-9_\-]", "_", key)[:120]

    @classmethod
    def get_match_enrichment(cls, fecha: str, home: str, away: str) -> dict:
        key = cls.make_key(fecha, home, away)
        now_iso = datetime.now(timezone.utc).isoformat()
        with cls._LOCK:
            entry = cls._STORE.get(key)
            if not entry and "db" in globals() and db is not None:
                try:
                    doc_id = cls._firestore_doc_id(key)
                    snap = db.collection(cls.COLLECTION_NAME).document(doc_id).get()
                    if getattr(snap, "exists", False):
                        loaded = snap.to_dict()
                        if isinstance(loaded, dict) and loaded.get("metricas"):
                            cls._STORE[key] = loaded
                            entry = loaded
                except Exception as e:
                    logger.debug("Firestore enrichment read fallback a memoria: %s", e)

            if not entry:
                return {"disponible": False, "discrepancias": [], "metricas": {}}
            exp = entry.get("fecha_vencimiento") or ""
            if exp and now_iso > exp:
                return {
                    "disponible": False,
                    "expirado": True,
                    "discrepancias": entry.get("discrepancias", []),
                    "metricas": {},
                }
            return dict(entry)

    _METRIC_SYNONYMS = {
        "corners_home": ("corners_home",),
        "corners_away": ("corners_away",),
        "corners": ("corners", "corners_total"),
        "tarjetas_home": ("tarjetas_home", "cards_home"),
        "tarjetas_away": ("tarjetas_away", "cards_away"),
        "tarjetas": ("tarjetas", "cards_total", "cards"),
        "tiros_home": ("tiros_home", "shots_home"),
        "tiros_away": ("tiros_away", "shots_away"),
        "tiros": ("tiros", "shots_total", "shots"),
        "tiros_puerta_home": ("tiros_puerta_home", "shots_on_target_home"),
        "tiros_puerta_away": ("tiros_puerta_away", "shots_on_target_away"),
        "tiros_puerta": ("tiros_puerta", "shots_on_target", "shots_on_target_total"),
        "faltas_home": ("faltas_home", "fouls_home"),
        "faltas_away": ("faltas_away", "fouls_away"),
        "faltas": ("faltas", "fouls_total", "fouls"),
        "bajas_confirmadas": ("bajas_confirmadas", "injuries_confirmed"),
        "arbitro": ("arbitro", "referee"),
        "arbitro_avg_cards": ("arbitro_avg_cards", "referee_avg_cards"),
        "resultado": ("resultado",),
    }

    _ENGLISH_MIRROR_KEYS = {
        "tarjetas_home": "cards_home",
        "tarjetas_away": "cards_away",
        "tarjetas": "cards_total",
        "tiros_home": "shots_home",
        "tiros_away": "shots_away",
        "tiros": "shots_total",
        "tiros_puerta_home": "shots_on_target_home",
        "tiros_puerta_away": "shots_on_target_away",
        "tiros_puerta": "shots_on_target",
        "faltas_home": "fouls_home",
        "faltas_away": "fouls_away",
        "faltas": "fouls_total",
        "corners": "corners_total",
    }

    @classmethod
    def _normalize_observation_metrics(cls, raw_m: dict) -> dict:
        if not isinstance(raw_m, dict):
            return {}
        norm = {}
        for canon_key, aliases in cls._METRIC_SYNONYMS.items():
            val = None
            for al in aliases:
                v_cand = raw_m.get(al)
                if v_cand is not None and v_cand != "":
                    val = v_cand
                    break
            norm[canon_key] = val

        # Completar totales automáticamente cuando existen home y away
        for h_k, a_k, tot_k in (
            ("corners_home", "corners_away", "corners"),
            ("tarjetas_home", "tarjetas_away", "tarjetas"),
            ("tiros_home", "tiros_away", "tiros"),
            ("tiros_puerta_home", "tiros_puerta_away", "tiros_puerta"),
            ("faltas_home", "faltas_away", "faltas"),
        ):
            if norm.get(tot_k) is None and norm.get(h_k) is not None and norm.get(a_k) is not None:
                try:
                    norm[tot_k] = int(norm[h_k]) + int(norm[a_k])
                except Exception:
                    pass
        return norm

    @classmethod
    def store_observations(cls, match_data: dict, observations: list, ttl_seconds: int = 3600) -> dict:
        fecha = str(match_data.get("fecha") or match_data.get("fecha_utc") or "")[:10]
        home = match_data.get("local", "")
        away = match_data.get("visitante", "")
        key = cls.make_key(fecha, home, away)
        now_dt = datetime.now(timezone.utc)
        now_iso = now_dt.isoformat()
        exp_iso = (now_dt + timedelta(seconds=ttl_seconds)).isoformat()

        partido_asoc = {
            "id_partido": match_data.get("id_partido"),
            "fecha": fecha,
            "local": home,
            "visitante": away,
        }

        normalized_obs = []
        for obs in (observations or []):
            normalized_obs.append({
                "fuente": obs.get("fuente", "desconocida"),
                "nivel_verificacion": obs.get("nivel_verificacion", "RESPALDO_SECUNDARIO"),
                "metricas": cls._normalize_observation_metrics(obs.get("metricas") or {}),
            })

        consolidated = {}
        discrepancias = []
        target_metrics = tuple(cls._METRIC_SYNONYMS.keys())

        for metric in target_metrics:
            seen_vals = []
            for obs in normalized_obs:
                val = (obs.get("metricas") or {}).get(metric)
                if val is not None and val != "":
                    seen_vals.append({
                        "valor": val,
                        "fuente": obs.get("fuente", "desconocida"),
                        "nivel_verificacion": obs.get("nivel_verificacion", "RESPALDO_SECUNDARIO"),
                    })
            if not seen_vals:
                consolidated[metric] = {
                    "valor": None,
                    "fuente": "NO_DISPONIBLE",
                    "fecha_consulta": now_iso,
                    "fecha_vencimiento": exp_iso,
                    "nivel_verificacion": "NO_DISPONIBLE",
                    "partido_asociado": partido_asoc,
                }
                continue

            distinct_repr = {json.dumps(x["valor"], sort_keys=True, default=str) for x in seen_vals}
            # Si una fuente prioritaria con API Key (football-data.org o highlightly) entregó el dato,
            # no se descarta por diferencias de scrapers secundarios (espn/sofascore).
            auth_val = next(
                (x for x in seen_vals if str(x.get("fuente", "")).lower() in ("football-data.org", "highlightly")),
                None,
            )
            if len(distinct_repr) > 1 and auth_val is None:
                discrepancias.append({
                    "metrica": metric,
                    "partido": partido_asoc,
                    "fecha_deteccion": now_iso,
                    "reportes": seen_vals,
                })
                consolidated[metric] = {
                    "valor": None,
                    "fuente": "DISCREPANCIA",
                    "fecha_consulta": now_iso,
                    "fecha_vencimiento": exp_iso,
                    "nivel_verificacion": "DISCREPANCIA_DETECTADA",
                    "partido_asociado": partido_asoc,
                    "reportes": seen_vals,
                }
            else:
                chosen = auth_val or seen_vals[0]
                consolidated[metric] = {
                    "valor": chosen["valor"],
                    "fuente": chosen["fuente"],
                    "fecha_consulta": now_iso,
                    "fecha_vencimiento": exp_iso,
                    "nivel_verificacion": chosen["nivel_verificacion"],
                    "partido_asociado": partido_asoc,
                }

        # Espejar claves en inglés (shots_home, shots_away, shots_on_target_home, cards_home, fouls_home, etc.)
        # para garantizar trazabilidad 1:1 entre Highlightly, MatchEnrichmentCache y SportsAnalyticsEngine
        for es_key, en_key in cls._ENGLISH_MIRROR_KEYS.items():
            if es_key in consolidated:
                consolidated[en_key] = dict(consolidated[es_key])

        fuentes_activas = sorted({
            m["fuente"] for m in consolidated.values()
            if m.get("valor") is not None and m.get("fuente") not in ("NO_DISPONIBLE", "DISCREPANCIA")
        })
        nivel_global = (
            "DISCREPANCIA_DETECTADA" if discrepancias
            else ("PRIMARIO_OFICIAL" if "football-data.org" in fuentes_activas
                  else ("RESPALDO_SECUNDARIO" if fuentes_activas else "NO_DISPONIBLE"))
        )

        record = {
            "disponible": True,
            "partido_asociado": partido_asoc,
            "fuente": ", ".join(fuentes_activas) if fuentes_activas else "NO_DISPONIBLE",
            "fecha_consulta": now_iso,
            "fecha_vencimiento": exp_iso,
            "nivel_verificacion": nivel_global,
            "metricas": consolidated,
            "discrepancias": discrepancias,
            "tiene_discrepancia": len(discrepancias) > 0,
        }
        with cls._LOCK:
            cls._STORE[key] = record
            if "db" in globals() and db is not None:
                try:
                    doc_id = cls._firestore_doc_id(key)
                    db.collection(cls.COLLECTION_NAME).document(doc_id).set(record, merge=True)
                except Exception as e:
                    logger.debug("Firestore enrichment write fallback a memoria: %s", e)
        return record

    @classmethod
    def enrich_team_last_5_matches(cls, team_name: str, before_date: str = "", competition_code: str = "", limit: int = 5) -> list:
        """
        Obtiene y persiste en caché los últimos 5 partidos verificados de un equipo antes de `before_date`:
        1) Consulta primero Highlightly Football API (`HighlightlyFootballClient.fetch_team_last_5_matches`).
        2) Si faltan partidos (<5) o métricas secundarias, consulta ESPN (`ESPNLiveService.fetch_team_last_5_matches`) como respaldo.
        Solo conserva partidos cuya fecha sea estrictamente anterior a `before_date`.
        """
        if not team_name or not str(team_name).strip():
            return []
        cutoff = str(before_date or "")[:10]
        existing = []
        if "SportsAnalyticsEngine" in globals():
            hist_cur = SportsAnalyticsEngine.get_verified_last_5_matches(team_name, before_date=cutoff, competition_code=competition_code)
            existing = list(hist_cur.get("partidos") or [])
            if (
                len(existing) >= limit
                and hist_cur.get("corners_avg") is not None
                and hist_cur.get("tarjetas_avg") is not None
                and hist_cur.get("tiros_totales_avg") is not None
                and hist_cur.get("tiros_puerta_avg") is not None
            ):
                return existing[:limit]

        collected = []
        # 1. Primaria para históricos de últimos 5 con estadísticas detalladas: Highlightly
        if "HighlightlyFootballClient" in globals() and hasattr(HighlightlyFootballClient, "fetch_team_last_5_matches"):
            try:
                hl_list = HighlightlyFootballClient.fetch_team_last_5_matches(
                    team_name, before_date=cutoff, competition_code=competition_code, limit=limit
                )
                if hl_list:
                    collected.extend(hl_list)
            except Exception as e:
                logger.debug("Highlightly fetch_team_last_5_matches fallo para %s: %s", team_name, e)

        # 2. Respaldo secundario si Highlightly no completó los 5 partidos o faltan métricas: ESPN
        need_espn = len(collected) < limit or any(
            x.get("corners") is None or x.get("tarjetas") is None or x.get("tiros_totales") is None or x.get("tiros_puerta") is None
            for x in collected
        )
        if need_espn and "ESPNLiveService" in globals() and hasattr(ESPNLiveService, "fetch_team_last_5_matches"):
            try:
                espn_list = ESPNLiveService.fetch_team_last_5_matches(
                    team_name, before_date=cutoff, competition_code=competition_code, limit=limit
                )
                if espn_list:
                    collected.extend(espn_list)
            except Exception as e:
                logger.debug("ESPN fetch_team_last_5_matches fallo para %s: %s", team_name, e)

        if not collected:
            return existing[:limit]

        # Guardar/combinar en _VERIFIED_RESULTS_CACHE (solo fechas < cutoff)
        if "_VERIFIED_RESULTS_CACHE" in globals():
            for m in collected:
                f_m = str(m.get("fecha") or "")[:10]
                if not f_m or (cutoff and f_m >= cutoff):
                    continue
                loc_m = str(m.get("local") or "").strip()
                vis_m = str(m.get("visitante") or "").strip()
                if not loc_m or not vis_m:
                    continue
                v_key = (f_m, loc_m, vis_m)
                prev = _VERIFIED_RESULTS_CACHE.get(v_key) or {}
                merged = {
                    "finished": True,
                    "simulado": False,
                    "competicion": m.get("competicion") or prev.get("competicion") or "Competición Oficial",
                    "codigo_liga": m.get("codigo_liga") or prev.get("codigo_liga") or competition_code or "OFL",
                    "score_home": prev.get("score_home") if prev.get("score_home") is not None else m.get("score_home"),
                    "score_away": prev.get("score_away") if prev.get("score_away") is not None else m.get("score_away"),
                    "corners_home": prev.get("corners_home") if prev.get("corners_home") is not None else m.get("corners_home"),
                    "corners_away": prev.get("corners_away") if prev.get("corners_away") is not None else m.get("corners_away"),
                    "corners_total": prev.get("corners_total") if prev.get("corners_total") is not None else m.get("corners_total"),
                    "cards_home": prev.get("cards_home") if prev.get("cards_home") is not None else m.get("cards_home"),
                    "cards_away": prev.get("cards_away") if prev.get("cards_away") is not None else m.get("cards_away"),
                    "cards_total": prev.get("cards_total") if prev.get("cards_total") is not None else m.get("cards_total"),
                    "shots_home": prev.get("shots_home") if prev.get("shots_home") is not None else m.get("shots_home"),
                    "shots_away": prev.get("shots_away") if prev.get("shots_away") is not None else m.get("shots_away"),
                    "shots_total": prev.get("shots_total") if prev.get("shots_total") is not None else m.get("shots_total"),
                    "shots_on_target_home": prev.get("shots_on_target_home") if prev.get("shots_on_target_home") is not None else m.get("shots_on_target_home"),
                    "shots_on_target_away": prev.get("shots_on_target_away") if prev.get("shots_on_target_away") is not None else m.get("shots_on_target_away"),
                    "shots_on_target": prev.get("shots_on_target") if prev.get("shots_on_target") is not None else m.get("shots_on_target"),
                    "fouls_home": prev.get("fouls_home") if prev.get("fouls_home") is not None else m.get("fouls_home"),
                    "fouls_away": prev.get("fouls_away") if prev.get("fouls_away") is not None else m.get("fouls_away"),
                    "fouls_total": prev.get("fouls_total") if prev.get("fouls_total") is not None else m.get("fouls_total"),
                    "source": prev.get("source") or m.get("fuente") or "highlightly",
                    "tipo_entidad": SportsAnalyticsEngine._infer_entity_type(loc_m, competition_code) if "SportsAnalyticsEngine" in globals() else "club",
                }
                _VERIFIED_RESULTS_CACHE[v_key] = merged

        if "SportsAnalyticsEngine" in globals():
            SportsAnalyticsEngine.rebuild_verified_history_index(force=True)
            updated = SportsAnalyticsEngine.get_verified_last_5_matches(team_name, before_date=cutoff, competition_code=competition_code)
            return list(updated.get("partidos") or [])[:limit]
        return collected[:limit]

    @classmethod
    def enrich_match_worker(cls, match_data: dict, ttl_seconds: int = 3600) -> dict:
        """
        Worker controlado de enriquecimiento en cascada:
        1. Consulta football-data.org como fuente principal (resultado, árbitro).
        2. Consulta Highlightly Football API para las 10 métricas estadísticas por equipo.
        3. Solo para las métricas que sigan faltando, consulta respaldos secundarios (SofaScore, ESPN, API-Sports).
        """
        fecha = str(match_data.get("fecha") or match_data.get("fecha_utc") or "")[:10]
        home = match_data.get("local", "")
        away = match_data.get("visitante", "")
        code = match_data.get("codigo_liga", "")
        observations = []
        filled_canon = set()

        def _register_obs(fuente_name: str, nivel: str, raw_dict: dict):
            norm_m = cls._normalize_observation_metrics(raw_dict)
            filtered_m = {}
            for k_c, v_c in norm_m.items():
                if v_c is not None and k_c not in filled_canon:
                    filtered_m[k_c] = v_c
                    filled_canon.add(k_c)
            if filtered_m:
                observations.append({
                    "fuente": fuente_name,
                    "nivel_verificacion": nivel,
                    "metricas": filtered_m,
                })

        # 1. Fuente principal: football-data.org
        fd_code = FootballDataOrgClient.COMPETITION_CODE_MAP.get(code, code)
        if fd_code:
            fd_res = FootballDataOrgClient.fetch_json(
                f"/competitions/{fd_code}/matches",
                competition_code=code,
                params={"dateFrom": fecha, "dateTo": fecha} if fecha else None,
                ttl_seconds=900,
            )
            if fd_res.get("ok") and fd_res.get("data"):
                for m in (fd_res["data"].get("matches") or []):
                    h_team_obj = m.get("homeTeam") or {}
                    a_team_obj = m.get("awayTeam") or {}
                    h_fd = h_team_obj.get("name", "")
                    a_fd = a_team_obj.get("name", "")
                    if (h_team_obj.get("crest") or h_team_obj.get("logo")) and "register_team_logo" in globals():
                        register_team_logo(h_fd or home, h_team_obj.get("crest") or h_team_obj.get("logo"), source="football-data.org", team_id=h_team_obj.get("id"), competition_code=code)
                    if (a_team_obj.get("crest") or a_team_obj.get("logo")) and "register_team_logo" in globals():
                        register_team_logo(a_fd or away, a_team_obj.get("crest") or a_team_obj.get("logo"), source="football-data.org", team_id=a_team_obj.get("id"), competition_code=code)
                    if matches_team_alias(home, h_fd) and matches_team_alias(away, a_fd):
                        ft = (m.get("score") or {}).get("fullTime") or {}
                        refs = m.get("referees") or []
                        arb_name = refs[0].get("name") if refs else None
                        res_str = f"{ft.get('home')}-{ft.get('away')}" if (m.get("status") == "FINISHED" and ft.get("home") is not None) else None
                        _register_obs("football-data.org", "PRIMARIO_OFICIAL", {
                            "resultado": res_str,
                            "arbitro": arb_name,
                        })
                        break

        # 1B. Fuente estadística real: Highlightly Football API (para métricas ausentes en football-data.org)
        if "HighlightlyFootballClient" in globals():
            try:
                hl = HighlightlyFootballClient.fetch_match_stats(home, away, fecha, liga_code=code)
                if hl:
                    _register_obs("highlightly", "RESPALDO_SECUNDARIO", {
                        "corners_home": hl.get("corners_home"),
                        "corners_away": hl.get("corners_away"),
                        "corners": hl.get("corners_total"),
                        "tarjetas_home": hl.get("cards_home"),
                        "tarjetas_away": hl.get("cards_away"),
                        "tarjetas": hl.get("cards_total"),
                        "tiros_home": hl.get("shots_home"),
                        "tiros_away": hl.get("shots_away"),
                        "tiros": hl.get("shots_total"),
                        "tiros_puerta_home": hl.get("shots_on_target_home"),
                        "tiros_puerta_away": hl.get("shots_on_target_away"),
                        "tiros_puerta": hl.get("shots_on_target"),
                        "faltas_home": hl.get("fouls_home"),
                        "faltas_away": hl.get("fouls_away"),
                        "faltas": hl.get("fouls_total"),
                        "resultado": f"{hl.get('score_home')}-{hl.get('score_away')}" if (hl.get("finished") and hl.get("score_home") is not None and hl.get("score_away") is not None) else None,
                    })
                    if hl.get("finished") and hl.get("score_home") is not None and hl.get("score_away") is not None and "_VERIFIED_RESULTS_CACHE" in globals():
                        v_key = (fecha, home, away)
                        if v_key not in _VERIFIED_RESULTS_CACHE:
                            _VERIFIED_RESULTS_CACHE[v_key] = {
                                "finished": True,
                                "simulado": False,
                                "competicion": match_data.get("liga") or "Competición Oficial",
                                "codigo_liga": code,
                                "score_home": hl.get("score_home"),
                                "score_away": hl.get("score_away"),
                                "corners_home": hl.get("corners_home"),
                                "corners_away": hl.get("corners_away"),
                                "corners_total": hl.get("corners_total"),
                                "cards_home": hl.get("cards_home"),
                                "cards_away": hl.get("cards_away"),
                                "cards_total": hl.get("cards_total"),
                                "shots_home": hl.get("shots_home"),
                                "shots_away": hl.get("shots_away"),
                                "shots_total": hl.get("shots_total"),
                                "shots_on_target_home": hl.get("shots_on_target_home"),
                                "shots_on_target_away": hl.get("shots_on_target_away"),
                                "shots_on_target": hl.get("shots_on_target"),
                                "fouls_home": hl.get("fouls_home"),
                                "fouls_away": hl.get("fouls_away"),
                                "fouls_total": hl.get("fouls_total"),
                                "source": "highlightly",
                                "tipo_entidad": SportsAnalyticsEngine._infer_entity_type(home, code) if "SportsAnalyticsEngine" in globals() else "club",
                            }
            except Exception as e:
                logger.debug("Worker Highlightly fallback error: %s", e)

        required_core = {
            "corners_home", "corners_away",
            "tarjetas_home", "tarjetas_away",
            "tiros_home", "tiros_away",
            "tiros_puerta_home", "tiros_puerta_away",
            "faltas_home", "faltas_away",
            "arbitro",
        }

        # 2. Respaldo secundario: SofaScore (solo si faltan métricas)
        if not required_core.issubset(filled_canon) and "SofascoreLiveService" in globals():
            try:
                sofa = SofascoreLiveService.fetch_match_stats(home, away, fecha)
                if sofa:
                    _register_obs("sofascore", "RESPALDO_SECUNDARIO", {
                        "corners_home": sofa.get("corners_home"),
                        "corners_away": sofa.get("corners_away"),
                        "corners": sofa.get("corners_total"),
                        "tarjetas_home": sofa.get("cards_home"),
                        "tarjetas_away": sofa.get("cards_away"),
                        "tarjetas": sofa.get("cards_total"),
                        "tiros_home": sofa.get("shots_home"),
                        "tiros_away": sofa.get("shots_away"),
                        "tiros": sofa.get("shots_total"),
                        "tiros_puerta_home": sofa.get("shots_on_target_home"),
                        "tiros_puerta_away": sofa.get("shots_on_target_away"),
                        "tiros_puerta": sofa.get("shots_on_target"),
                        "faltas_home": sofa.get("fouls_home"),
                        "faltas_away": sofa.get("fouls_away"),
                        "faltas": sofa.get("fouls_total"),
                        "bajas_confirmadas": sofa.get("bajas_confirmadas"),
                        "arbitro": sofa.get("referee"),
                        "arbitro_avg_cards": sofa.get("referee_avg_cards"),
                        "resultado": f"{sofa.get('score_home')}-{sofa.get('score_away')}" if sofa.get("finished") else None,
                    })
            except Exception as e:
                logger.debug("Worker SofaScore fallback error: %s", e)

        # 3. Respaldo secundario: ESPN (solo si faltan métricas)
        if not required_core.issubset(filled_canon) and "ESPNLiveService" in globals() and hasattr(ESPNLiveService, "fetch_match_stats"):
            try:
                espn = ESPNLiveService.fetch_match_stats(home, away, fecha, liga=match_data.get("liga") or code)
                if espn:
                    _register_obs("espn", "RESPALDO_SECUNDARIO", {
                        "corners_home": espn.get("corners_home"),
                        "corners_away": espn.get("corners_away"),
                        "corners": espn.get("corners_total"),
                        "tarjetas_home": espn.get("cards_home"),
                        "tarjetas_away": espn.get("cards_away"),
                        "tarjetas": espn.get("cards_total"),
                        "tiros_home": espn.get("shots_home"),
                        "tiros_away": espn.get("shots_away"),
                        "tiros": espn.get("shots_total"),
                        "tiros_puerta_home": espn.get("shots_on_target_home"),
                        "tiros_puerta_away": espn.get("shots_on_target_away"),
                        "tiros_puerta": espn.get("shots_on_target"),
                        "faltas_home": espn.get("fouls_home"),
                        "faltas_away": espn.get("fouls_away"),
                        "faltas": espn.get("fouls_total"),
                        "bajas_confirmadas": espn.get("bajas_confirmadas"),
                        "arbitro": espn.get("referee"),
                        "arbitro_avg_cards": espn.get("referee_avg_cards"),
                        "resultado": f"{espn.get('score_home')}-{espn.get('score_away')}" if espn.get("finished") else None,
                    })
            except Exception as e:
                logger.debug("Worker ESPN fallback error: %s", e)

        # 4. Respaldo secundario: API-Sports (solo si faltan métricas)
        if not required_core.issubset(filled_canon) and "ApiSportsETL" in globals() and hasattr(ApiSportsETL, "fetch_match_stats"):
            try:
                apisp = ApiSportsETL.fetch_match_stats(home, away, fecha, liga_code=code)
                if apisp:
                    _register_obs("api-sports", "RESPALDO_SECUNDARIO", {
                        "corners_home": apisp.get("corners_home"),
                        "corners_away": apisp.get("corners_away"),
                        "corners": apisp.get("corners_total"),
                        "tarjetas_home": apisp.get("cards_home"),
                        "tarjetas_away": apisp.get("cards_away"),
                        "tarjetas": apisp.get("cards_total"),
                        "tiros_home": apisp.get("shots_home"),
                        "tiros_away": apisp.get("shots_away"),
                        "tiros": apisp.get("shots_total"),
                        "tiros_puerta_home": apisp.get("shots_on_target_home"),
                        "tiros_puerta_away": apisp.get("shots_on_target_away"),
                        "tiros_puerta": apisp.get("shots_on_target"),
                        "faltas_home": apisp.get("fouls_home"),
                        "faltas_away": apisp.get("fouls_away"),
                        "faltas": apisp.get("fouls_total"),
                        "bajas_confirmadas": apisp.get("bajas_confirmadas"),
                        "arbitro": apisp.get("referee"),
                        "arbitro_avg_cards": apisp.get("referee_avg_cards"),
                        "resultado": f"{apisp.get('score_home')}-{apisp.get('score_away')}" if apisp.get("finished") else None,
                    })
            except Exception as e:
                logger.debug("Worker API-Sports fallback error: %s", e)

        if fecha and home and away:
            try:
                cls.enrich_team_last_5_matches(home, before_date=fecha, competition_code=code, limit=5)
                cls.enrich_team_last_5_matches(away, before_date=fecha, competition_code=code, limit=5)
            except Exception as e_h5:
                logger.debug("Worker enrich_team_last_5_matches aviso: %s", e_h5)

        rec = cls.store_observations(match_data, observations, ttl_seconds=ttl_seconds)
        metricas_rec = rec.get("metricas") or {}
        resp_log = {
            k: v.get("fuente")
            for k, v in metricas_rec.items()
            if v.get("valor") is not None
        }
        ten_fields = {
            k: (metricas_rec.get(k) or {}).get("valor")
            for k in (
                "corners_home", "corners_away",
                "cards_home", "cards_away",
                "shots_home", "shots_away",
                "shots_on_target_home", "shots_on_target_away",
                "fouls_home", "fouls_away",
            )
            if (metricas_rec.get(k) or {}).get("valor") is not None
        }
        logger.info(
            "[EnrichmentWorker] %s vs %s (%s) -> proveedores=%s valores_10=%s",
            home, away, fecha, resp_log or "SIN_DATOS", ten_fields
        )
        return rec

    @classmethod
    def enrich_calendar_worker(cls, target_date: str = "", limit: int = 20, ttl_seconds: int = 3600) -> dict:
        """Enriquece partidos del calendario manual por adelantado (nunca invocado desde /obtener-pronostico)."""
        fixtures = globals().get("ALL_FIXTURES_POOL", [])
        procesados = 0
        con_discrepancia = 0
        for fix in fixtures:
            if not is_competition_enabled(fix.get("codigo_liga", ""), fix.get("liga", "")):
                continue
            _, f_str = resolve_match_local_date(fix)
            if target_date and f_str != target_date[:10]:
                continue
            rec = cls.enrich_match_worker(fix, ttl_seconds=ttl_seconds)
            procesados += 1
            if rec.get("tiene_discrepancia"):
                con_discrepancia += 1
            if procesados >= limit:
                break
        return {"procesados": procesados, "con_discrepancia": con_discrepancia, "fecha": target_date or "TODAS"}


class RefereeIntelligenceService:
    """
    Servicio de Inteligencia Arbitral (SofaScore / ESPN / Flashscore / Base Oficial):
    - Consulta en tiempo real el árbitro designado para el partido desde SofaScore y ESPN API.
    - Cruza el nombre del colegiado con el catálogo oficial de promedios de tarjetas por partido (2025/2026).
    - Clasifica automáticamente al árbitro como ESTRICTO (tendencia Over tarjetas), EQUILIBRADO o LIBERAL/PERMISIVO (tendencia Under tarjetas).
    - Si aún no se publica el acta oficial 24-48h antes, asigna el colegiado principal de la rotación oficial del comité de la liga.
    """
    _REFEREE_MEMO_CACHE = {}

    LEAGUE_AVG_CARDS = {
        "PD": 4.85, "PL": 4.15, "BL1": 3.95, "SA": 4.55,
        "FL1": 3.95, "PPL": 4.95, "BSA": 5.15, "UCL": 4.05,
        "UEL": 4.30, "UNL": 4.20
    }

