    @classmethod
    def _infer_entity_type(cls, team_name: str, competition_code: str = "") -> str:
        if (competition_code or "").upper() in ("UNL", "WC", "EURO", "COPA_AMERICA"):
            return "seleccion"
        selecciones_conocidas = {
            "espana", "españa", "francia", "alemania", "italia", "inglaterra", "portugal",
            "paises bajos", "holanda", "belgica", "croacia", "suiza", "dinamarca", "austria",
            "polonia", "escocia", "grecia", "turquia", "ucrania", "hungria", "serbia",
            "noruega", "suecia", "gales", "chequia", "republica checa", "eslovaquia",
            "rumania", "eslovenia", "argentina", "brasil", "colombia", "uruguay", "peru", "chile"
        }
        norm = (team_name or "").lower().strip()
        return "seleccion" if norm in selecciones_conocidas else "club"

    _HISTORY_INDEX = {}
    _HISTORY_INDEX_COMP = {}
    _HISTORY_INDEX_SIG = None
    _LAST_5_CACHE = {}
    _TEAM_STATS_CACHE = {}
    _TEAM_STATS_CACHE_SIG = None
    _PERF_COUNTERS = {"cache_queries": 0, "history_scans": 0}

    @classmethod
    def _current_history_signature(cls):
        v_cache = globals().get("_VERIFIED_RESULTS_CACHE") or {}
        v_hist = globals().get("VERIFIED_TEAM_HISTORY") or {}
        r_est = globals().get("RATINGS_ESTADO") or {}
        first_k = next(iter(v_cache), None)
        return (len(v_cache), len(v_hist), first_k, r_est.get("actualizado"))

    @classmethod
    def rebuild_verified_history_index(cls, force: bool = False):
        """Precalcula el índice global de históricos normalizados por equipo, competición y fecha."""
        sig = cls._current_history_signature()
        if not force and cls._HISTORY_INDEX_SIG == sig:
            return
        norm_fn = globals().get("_norm_equipo")
        idx_main = {}
        idx_comp = {}
        dedup_tracker = {}

        def _append_entry(eq_key: str, ent_type: str, entry: dict):
            f_m = str(entry.get("fecha") or "")[:10]
            if not f_m:
                return
            rival_n = entry.get("_rival_norm") or (norm_fn(entry.get("rival", "")) if norm_fn else str(entry.get("rival", "")).lower().strip())
            cond = entry.get("condicion", "")
            d_key = (eq_key, ent_type, f_m, rival_n, cond)
            if d_key in dedup_tracker:
                return
            dedup_tracker[d_key] = True
            idx_main.setdefault((eq_key, ent_type), []).append(entry)
            c_code = str(entry.get("codigo_liga") or "").upper()
            if c_code:
                idx_comp.setdefault((eq_key, c_code, ent_type), []).append(entry)

        if "VERIFIED_TEAM_HISTORY" in globals():
            with _RATINGS_LOCK:
                for eq_k, hist_list in VERIFIED_TEAM_HISTORY.items():
                    for item in hist_list:
                        if not item.get("es_oficial", True) or item.get("simulado", False):
                            continue
                        if "amistoso" in str(item.get("competicion", "")).lower():
                            continue
                        d_item = dict(item)
                        d_item["_rival_norm"] = norm_fn(d_item.get("rival", "")) if norm_fn else str(d_item.get("rival", "")).lower().strip()
                        _append_entry(eq_k, "club", d_item)

        if "_VERIFIED_RESULTS_CACHE" in globals():
            for (f_c, h_c, a_c), res_c in _VERIFIED_RESULTS_CACHE.items():
                if not res_c.get("finished") or res_c.get("simulado"):
                    continue
                if "amistoso" in str(res_c.get("competicion", "")).lower():
                    continue
                c_ent = res_c.get("tipo_entidad") or cls._infer_entity_type(h_c, res_c.get("codigo_liga", ""))
                h_n = norm_fn(h_c) if norm_fn else h_c.lower().strip()
                a_n = norm_fn(a_c) if norm_fn else a_c.lower().strip()
                sh = int(res_c.get("score_home") or 0)
                sa = int(res_c.get("score_away") or 0)
                f_str = str(f_c)[:10]
                comp_name = res_c.get("competicion") or "Competición Oficial"
                comp_code = res_c.get("codigo_liga", "")
                fuente = res_c.get("source") or "Acta Oficial Verificada"

                ps_sh = ps_sot = None
                if res_c.get("shots_home") is None and isinstance(res_c.get("player_stats"), dict):
                    tot_sh_p = sum(int(v.get("total_shots", 0)) for v in res_c["player_stats"].values())
                    tot_sot_p = sum(int(v.get("shots_on_target", 0)) for v in res_c["player_stats"].values())
                    if tot_sh_p > 0:
                        ps_sh = tot_sh_p
                        ps_sot = tot_sot_p

                for is_home in (True, False):
                    eq_n = h_n if is_home else a_n
                    riv_name = a_c if is_home else h_c
                    riv_n = a_n if is_home else h_n
                    gf, gc = (sh, sa) if is_home else (sa, sh)
                    res_ved = "V" if gf > gc else ("E" if gf == gc else "D")
                    c_team = res_c.get("corners_home") if is_home else res_c.get("corners_away")
                    if c_team is None and res_c.get("corners_total") is not None:
                        c_team = round(float(res_c.get("corners_total")) / 2.0, 2)
                    t_team = res_c.get("cards_home") if is_home else res_c.get("cards_away")
                    if t_team is None and res_c.get("cards_total") is not None:
                        t_team = round(float(res_c.get("cards_total")) / 2.0, 2)
                    sh_team = res_c.get("shots_home") if is_home else res_c.get("shots_away")
                    if sh_team is None:
                        sh_team = ps_sh
                    sot_team = res_c.get("shots_on_target_home") if is_home else res_c.get("shots_on_target_away")
                    if sot_team is None:
                        sot_team = ps_sot
                    fl_team = res_c.get("fouls_home") if is_home else res_c.get("fouls_away")

                    _append_entry(eq_n, c_ent, {
                        "fecha": f_str,
                        "competicion": comp_name,
                        "codigo_liga": comp_code,
                        "rival": riv_name,
                        "_rival_norm": riv_n,
                        "condicion": "L" if is_home else "V",
                        "gf": gf, "gc": gc,
                        "marcador": f"{sh} - {sa}",
                        "resultado": res_ved,
                        "corners": c_team,
                        "tarjetas": t_team,
                        "tiros_totales": sh_team,
                        "tiros_puerta": sot_team,
                        "faltas": fl_team,
                        "tipo_entidad": c_ent,
                        "es_oficial": True,
                        "simulado": False,
                        "fuente": fuente,
                    })

        for k_idx in idx_main:
            idx_main[k_idx].sort(key=lambda x: x.get("fecha", ""), reverse=True)
        for k_c in idx_comp:
            idx_comp[k_c].sort(key=lambda x: x.get("fecha", ""), reverse=True)

        cls._HISTORY_INDEX = idx_main
        cls._HISTORY_INDEX_COMP = idx_comp
        cls._HISTORY_INDEX_SIG = sig
        cls._LAST_5_CACHE.clear()
        cls._TEAM_STATS_CACHE.clear()
        cls._TEAM_STATS_CACHE_SIG = sig

    @classmethod
    def get_verified_last_5_matches(cls, team_name: str, before_date: str = "", competition_code: str = "", entity_type: str = "") -> dict:
        """
        Consulta O(1) sobre el índice global precalculado de históricos normalizados y caché con clave team|competition|before_date.
        Nunca recorre _VERIFIED_RESULTS_CACHE completo ni re-normaliza nombres en cada solicitud HTTP.
        """
        cls.rebuild_verified_history_index()
        ent_type = entity_type or cls._infer_entity_type(team_name, competition_code)
        norm_fn = globals().get("_norm_equipo")
        eq_norm = norm_fn(team_name) if norm_fn else (team_name or "").lower().strip()
        cutoff = str(before_date or "")[:10]
        comp_str = str(competition_code or "").upper()
        cache_key = f"{eq_norm}|{comp_str}|{cutoff}|{ent_type}"

        cached = cls._LAST_5_CACHE.get(cache_key)
        if cached is not None:
            cls._PERF_COUNTERS["cache_queries"] += 1
            return dict(cached)

        candidates = cls._HISTORY_INDEX.get((eq_norm, ent_type), [])
        if cutoff:
            last_5 = []
            for m in candidates:
                if m["fecha"] < cutoff:
                    last_5.append(m)
                    if len(last_5) >= 5:
                        break
        else:
            last_5 = candidates[:5]
        n = len(last_5)
        wins = sum(1 for x in last_5 if x.get("resultado") == "V")
        draws = sum(1 for x in last_5 if x.get("resultado") == "E")
        losses = sum(1 for x in last_5 if x.get("resultado") == "D")
        gf_tot = sum(int(x.get("gf", 0)) for x in last_5)
        gc_tot = sum(int(x.get("gc", 0)) for x in last_5)
        streak_str = "-".join(x.get("resultado", "E") for x in last_5) if n > 0 else ""

        c_vals = [float(x["corners"]) for x in last_5 if x.get("corners") is not None]
        t_vals = [float(x["tarjetas"]) for x in last_5 if x.get("tarjetas") is not None]
        sh_vals = [float(x["tiros_totales"]) for x in last_5 if x.get("tiros_totales") is not None]
        sot_vals = [float(x["tiros_puerta"]) for x in last_5 if x.get("tiros_puerta") is not None]
        fl_vals = [float(x["faltas"]) for x in last_5 if x.get("faltas") is not None]

        res_obj = {
            "partidos": last_5,
            "muestra_n": n,
            "streak": streak_str,
            "resumen_ved": f"{wins}V-{draws}E-{losses}D" if n > 0 else "0V-0E-0D",
            "wins": wins, "draws": draws, "losses": losses,
            "pts": wins * 3 + draws,
            "gf_total": gf_tot, "gc_total": gc_tot,
            "corners_avg": round(sum(c_vals) / len(c_vals), 2) if c_vals else None,
            "corners_muestra": len(c_vals),
            "tarjetas_avg": round(sum(t_vals) / len(t_vals), 2) if t_vals else None,
            "tarjetas_muestra": len(t_vals),
            "tiros_totales_avg": round(sum(sh_vals) / len(sh_vals), 2) if sh_vals else None,
            "tiros_totales_muestra": len(sh_vals),
            "tiros_puerta_avg": round(sum(sot_vals) / len(sot_vals), 2) if sot_vals else None,
            "tiros_puerta_muestra": len(sot_vals),
            "faltas_avg": round(sum(fl_vals) / len(fl_vals), 2) if fl_vals else None,
            "faltas_muestra": len(fl_vals),
            "confianza_insuficiente": (n < 5),
            "tipo_entidad": ent_type,
            "fuente": last_5[0].get("fuente", "Sin fuente") if n > 0 else "Sin partidos verificados"
        }
        cls._LAST_5_CACHE[cache_key] = res_obj
        return dict(res_obj)

    @classmethod
    def _expand_streak_to_5(cls, raw_streak: str, normalized_name: str, elo_val: int = 1800) -> str:
        """Conserva únicamente los resultados reales presentes sin rellenar partidos ficticios."""
        partes = [p.strip().upper() for p in (raw_streak or "").replace("W", "V").replace("L", "D").split("-") if p.strip() in ("V", "E", "D", "W", "L")]
        norm_p = ["V" if p == "W" else ("D" if p == "L" else p) for p in partes[:5]]
        return "-".join(norm_p)

    @classmethod
    def _normalizar_stats_5_partidos(cls, d: dict, normalized_name: str) -> dict:
        """Nunca inventa partidos ni suma goles ficticios; preserva la muestra real."""
        raw_s = d.get("streak", "")
        partes_orig = [p.strip().upper() for p in raw_s.replace("W", "V").replace("L", "D").split("-") if p.strip()]
        d["streak"] = cls._expand_streak_to_5(raw_s, normalized_name, d.get("elo", 1800))
        d["muestra_n"] = len(partes_orig[:5])
        d["confianza_insuficiente"] = (d["muestra_n"] < 5)
        return d

    @classmethod
    def get_team_stats(cls, team_name: str, competition_code: str = "", before_date: str = "") -> dict:
        """
        Fuente única de producción para métricas de equipo con caché team|competition|before_date:
        - Consume únicamente datos oficiales preindexados (`RATINGS_REALES` + índice global precalculado).
        - Si no existen datos oficiales suficientes, devuelve `nivel_verificacion = "DATOS_INSUFICIENTES"`.
        """
        cls.rebuild_verified_history_index()
        norm_fn = globals().get("_norm_equipo")
        eq_norm = norm_fn(team_name) if norm_fn else (team_name or "").lower().strip()
        ts_key = f"{eq_norm}|{str(competition_code or '').upper()}|{str(before_date or '')[:10]}"
        cached_ts = cls._TEAM_STATS_CACHE.get(ts_key)
        if cached_ts is not None:
            cls._PERF_COUNTERS["cache_queries"] += 1
            return dict(cached_ts)

        real_rating = _ratings_para(team_name) if "_ratings_para" in globals() else None
        hist_5 = cls.get_verified_last_5_matches(team_name, before_date=before_date, competition_code=competition_code)
        n_real = int(hist_5.get("muestra_n", 0))

        if real_rating and n_real > 0:
            res_ts = {
                "elo": real_rating.get("elo"),
                "base_att": real_rating.get("gf_promedio"),
                "base_def": real_rating.get("gc_promedio"),
                "streak": hist_5["streak"],
                "muestra_n": n_real,
                "pts_last3": hist_5["pts"],
                "gf_last3": hist_5["gf_total"],
                "ga_last3": hist_5["gc_total"],
                "corners": real_rating.get("corners_promedio") if real_rating.get("corners_promedio") is not None else hist_5.get("corners_avg"),
                "corners_muestra": real_rating.get("corners_muestra", 0) or hist_5.get("corners_muestra", 0),
                "tarjetas": real_rating.get("tarjetas_promedio") if real_rating.get("tarjetas_promedio") is not None else hist_5.get("tarjetas_avg"),
                "tarjetas_muestra": real_rating.get("tarjetas_muestra", 0) or hist_5.get("tarjetas_muestra", 0),
                "tiros_puerta": hist_5.get("tiros_puerta_avg"),
                "tiros_totales": hist_5.get("tiros_totales_avg"),
                "faltas": hist_5.get("faltas_avg"),
                "ultimos_partidos": hist_5["partidos"],
                "confianza_insuficiente": hist_5["confianza_insuficiente"],
                "fuente": real_rating.get("fuente", "football-data.org"),
                "actualizado_en": real_rating.get("actualizado_en"),
                "nivel_verificacion": "VERIFICADO_OFICIAL" if n_real >= 5 else "MUESTRA_PARCIAL",
                "datos_suficientes": (n_real >= 5),
                "observacion": f"Datos oficiales ({n_real} últimos partidos; {real_rating.get('partidos', n_real)} en temporada)."
            }
        elif n_real > 0:
            res_ts = {
                "elo": None,
                "base_att": round(hist_5["gf_total"] / n_real, 2),
                "base_def": round(hist_5["gc_total"] / n_real, 2),
                "streak": hist_5["streak"],
                "muestra_n": n_real,
                "pts_last3": hist_5["pts"],
                "gf_last3": hist_5["gf_total"],
                "ga_last3": hist_5["gc_total"],
                "corners": hist_5.get("corners_avg"),
                "corners_muestra": hist_5.get("corners_muestra", 0),
                "tarjetas": hist_5.get("tarjetas_avg"),
                "tarjetas_muestra": hist_5.get("tarjetas_muestra", 0),
                "tiros_puerta": hist_5.get("tiros_puerta_avg"),
                "tiros_totales": hist_5.get("tiros_totales_avg"),
                "faltas": hist_5.get("faltas_avg"),
                "ultimos_partidos": hist_5["partidos"],
                "confianza_insuficiente": (n_real < 5),
                "fuente": hist_5.get("fuente", "football-data.org"),
                "actualizado_en": RATINGS_ESTADO.get("actualizado") if "RATINGS_ESTADO" in globals() else None,
                "nivel_verificacion": "VERIFICADO_OFICIAL" if n_real >= 5 else "MUESTRA_PARCIAL",
                "datos_suficientes": (n_real >= 5),
                "observacion": f"Muestra verificada: {n_real}/5 partidos oficiales."
            }
        else:
            res_ts = {
                "elo": None,
                "base_att": None,
                "base_def": None,
                "streak": "",
                "muestra_n": 0,
                "pts_last3": 0,
                "gf_last3": 0,
                "ga_last3": 0,
                "corners": None,
                "corners_muestra": 0,
                "tarjetas": None,
                "tarjetas_muestra": 0,
                "tiros_puerta": None,
                "tiros_totales": None,
                "ultimos_partidos": [],
                "confianza_insuficiente": True,
                "fuente": "NO_DISPONIBLE",
                "actualizado_en": None,
                "nivel_verificacion": "DATOS_INSUFICIENTES",
                "datos_suficientes": False,
                "observacion": "DATOS_INSUFICIENTES: sin partidos oficiales verificados en football-data.org."
            }
        cls._TEAM_STATS_CACHE[ts_key] = res_ts
        return dict(res_ts)
    @staticmethod
    def calculate_poisson(k: int, lamb: float) -> float:
        if lamb <= 0:
            return 1.0 if k == 0 else 0.0
        return (math.pow(lamb, k) * math.exp(-lamb)) / math.factorial(k)

    @classmethod
    def _calcular_puntos_racha5(cls, streak_str: str) -> tuple:
        partes = [p.strip().upper() for p in (streak_str or "").split("-") if p.strip()][:5]
        wins = sum(1 for p in partes if p in ("V", "W"))
        draws = sum(1 for p in partes if p == "E")
        losses = sum(1 for p in partes if p in ("D", "L"))
        pts = wins * 3 + draws
        return pts, wins, draws, losses

    @classmethod
    def derive_team_ratings(cls, home_team: str, away_team: str, competition_code: str, before_date: str = "") -> tuple[float, float, int]:
        h_stat = cls.get_team_stats(home_team, competition_code, before_date=before_date)
        a_stat = cls.get_team_stats(away_team, competition_code, before_date=before_date)

        pts_h, wins_h, draws_h, losses_h = cls._calcular_puntos_racha5(h_stat.get("streak", ""))
        pts_a, wins_a, draws_a, losses_a = cls._calcular_puntos_racha5(a_stat.get("streak", ""))

        n_h = max(1, int(h_stat.get("muestra_n") or len([x for x in (h_stat.get("streak") or "").split("-") if x.strip()]) or 5))
        n_a = max(1, int(a_stat.get("muestra_n") or len([x for x in (a_stat.get("streak") or "").split("-") if x.strip()]) or 5))
        gf5_h = float(h_stat.get("gf_last3") or 0)
        ga5_h = float(h_stat.get("ga_last3") or 0)
        gf5_a = float(a_stat.get("gf_last3") or 0)
        ga5_a = float(a_stat.get("ga_last3") or 0)

        rate_gf_h = max(0.45, min(2.85, gf5_h / n_h)) if h_stat.get("muestra_n", n_h) > 0 else 1.35
        rate_ga_h = max(0.45, min(2.70, ga5_h / n_h)) if h_stat.get("muestra_n", n_h) > 0 else 1.25
        rate_gf_a = max(0.45, min(2.85, gf5_a / n_a)) if a_stat.get("muestra_n", n_a) > 0 else 1.20
        rate_ga_a = max(0.45, min(2.70, ga5_a / n_a)) if a_stat.get("muestra_n", n_a) > 0 else 1.25

        b_att_h = float(h_stat.get("base_att") if h_stat.get("base_att") is not None else rate_gf_h)
        b_def_h = float(h_stat.get("base_def") if h_stat.get("base_def") is not None else rate_ga_h)
        b_att_a = float(a_stat.get("base_att") if a_stat.get("base_att") is not None else rate_gf_a)
        b_def_a = float(a_stat.get("base_def") if a_stat.get("base_def") is not None else rate_ga_a)

        goles_anotados_local = (b_att_h * 0.45) + (rate_gf_h * 0.55)
        goles_concedidos_local = (b_def_h * 0.45) + (rate_ga_h * 0.55)
        goles_anotados_visita = (b_att_a * 0.45) + (rate_gf_a * 0.55)
        goles_concedidos_visita = (b_def_a * 0.45) + (rate_ga_a * 0.55)

        # Promedios Oficiales de Goles Local y Visitante de cada Liga
        league_goal_baselines = {
            "BSA": (1.34, 1.04),
            "SA":  (1.42, 1.14),
            "FL1": (1.44, 1.14),
            "PPL": (1.42, 1.12),
            "PD":  (1.46, 1.16),
            "UNL": (1.38, 1.10),
            "UEL": (1.48, 1.20),
            "PL":  (1.54, 1.24),
            "BL1": (1.60, 1.26),
            "UCL": (1.54, 1.22),
        }
        prom_goles_local_liga, prom_goles_visita_liga = league_goal_baselines.get(competition_code, (1.46, 1.18))

        # =========================================================================
        # FÓRMULA 1: MODELO CRUZADO OFENSIVO × DEBILIDAD DEFENSIVA DEL RIVAL (LAMBDA)
        # λ_Local = (Goles_Anotados_Local / Prom_Goles_Local_Liga) * (Goles_Concedidos_Visitante / Prom_Goles_Visita_Liga) * Prom_Goles_Local_Liga
        # λ_Visitante = (Goles_Anotados_Visitante / Prom_Goles_Visita_Liga) * (Goles_Concedidos_Local / Prom_Goles_Local_Liga) * Prom_Goles_Visita_Liga
        # Nota: Los goles concedidos por el visitante equivalen a los goles anotados por el local en la liga (prom_goles_local_liga)
        # =========================================================================
        fuerza_ataque_local = goles_anotados_local / max(0.5, prom_goles_local_liga)
        debilidad_defensa_visita = goles_concedidos_visita / max(0.5, prom_goles_local_liga)

        fuerza_ataque_visita = goles_anotados_visita / max(0.5, prom_goles_visita_liga)
        debilidad_defensa_local = goles_concedidos_local / max(0.5, prom_goles_visita_liga)

        lh_cruzado = fuerza_ataque_local * debilidad_defensa_visita * prom_goles_local_liga
        la_cruzado = fuerza_ataque_visita * debilidad_defensa_local * prom_goles_visita_liga

        # Suavizado calibrado para que partidos de defensas abiertas proyecten 2.80 a 3.25 goles totales (estándar de mercado)
        lh_calc = (lh_cruzado * 0.62) + (prom_goles_local_liga * 0.38)
        la_calc = (la_cruzado * 0.62) + (prom_goles_visita_liga * 0.38)

        # Impulso cuando la defensa rival es muy sensible (concede >= 1.55 goles/partido)
        if goles_concedidos_visita >= 1.55:
            lh_calc += (goles_concedidos_visita - 1.48) * 0.16
        if goles_concedidos_local >= 1.55:
            la_calc += (goles_concedidos_local - 1.48) * 0.16

        # Ajuste por Momentum de Racha y diferencial Elo
        pts_diff = pts_h - pts_a
        gd5_h = gf5_h - ga5_h
        gd5_a = gf5_a - ga5_a
        gd_diff = max(-10.0, min(10.0, gd5_h - gd5_a))
        elo_diff = float(h_stat.get("elo") or 1800) - float(a_stat.get("elo") or 1800)

        momentum_swing = (pts_diff * 0.022) + (gd_diff * 0.012) + ((elo_diff / 650.0) * 0.12)
        lh_calc += momentum_swing * 0.50
        la_calc -= momentum_swing * 0.50

        # Solo comprimir si AMBAS defensas son verdaderamente férreas (conceden <= 1.05 goles/p) y ataques bajos
        if goles_concedidos_local <= 1.05 and goles_concedidos_visita <= 1.05 and goles_anotados_local <= 1.25 and goles_anotados_visita <= 1.20:
            lh_calc *= 0.90
            la_calc *= 0.90

        lh = max(0.55, min(2.55, round(lh_calc, 2)))
        la = max(0.50, min(2.35, round(la_calc, 2)))

        fouls = int(round(18 + (float(h_stat.get('tarjetas') or 2.0) + float(a_stat.get('tarjetas') or 2.0)) * 2.1))
        return lh, la, fouls

    @classmethod
    def evaluate_match_probabilities(cls, lambda_home: float, lambda_away: float) -> dict:
        max_goals = 8
        prob_matrix = np.zeros((max_goals, max_goals))

        # Ajuste Dixon-Coles para correlación realista de empates bajos (0-0, 1-1)
        rho = -0.06
        for h in range(max_goals):
            for a in range(max_goals):
                base_p = cls.calculate_poisson(h, lambda_home) * cls.calculate_poisson(a, lambda_away)
                if h == 0 and a == 0:
                    tau = 1.0 - (lambda_home * lambda_away * rho)
                elif h == 0 and a == 1:
                    tau = 1.0 + (lambda_home * rho)
                elif h == 1 and a == 0:
                    tau = 1.0 + (lambda_away * rho)
                elif h == 1 and a == 1:
                    tau = 1.0 - rho
                else:
                    tau = 1.0
                prob_matrix[h, a] = max(0.0, base_p * tau)

        prob_matrix /= np.sum(prob_matrix)

        prob_h = float(np.sum(np.tril(prob_matrix, -1)))
        prob_d = float(np.sum(np.diag(prob_matrix)))
        prob_a = float(np.sum(np.triu(prob_matrix, 1)))

        prob_under_2_5 = 0.0
        prob_under_1_5 = 0.0
        prob_btts = 0.0

        for h in range(max_goals):
            for a in range(max_goals):
                p = prob_matrix[h, a]
                if (h + a) <= 2:
                    prob_under_2_5 += p
                if (h + a) <= 1:
                    prob_under_1_5 += p
                if h >= 1 and a >= 1:
                    prob_btts += p

        return {
            "1X2": {
                "1": round(prob_h * 100, 2),
                "X": round(prob_d * 100, 2),
                "2": round(prob_a * 100, 2)
            },
            "over_under_2_5": {
                "over": round((1.0 - prob_under_2_5) * 100, 2),
                "under": round(prob_under_2_5 * 100, 2)
            },
            "over_under_1_5": {
                "over": round((1.0 - prob_under_1_5) * 100, 2),
                "under": round(prob_under_1_5 * 100, 2)
            },
            "btts": {
                "yes": round(prob_btts * 100, 2),
                "no": round((1.0 - prob_btts) * 100, 2)
            },
            "fair_odds": {
                "1": round(1.0 / prob_h, 2) if prob_h > 0.01 else 99.0,
                "X": round(1.0 / prob_d, 2) if prob_d > 0.01 else 99.0,
                "2": round(1.0 / prob_a, 2) if prob_a > 0.01 else 99.0
            }
        }

    @classmethod
    def run_monte_carlo_simulation(cls, lambda_home: float, lambda_away: float, iterations: int = 10000) -> dict:
        iterations = min(max(iterations, 1000), 20000)
        lh = max(0.35, float(lambda_home))
        la = max(0.35, float(lambda_away))

        # Semilla determinista basada en los parámetros xG para consistencia reproducible
        seed_val = int(round(lh * 10000 + la * 100)) % (2**31 - 1)
        rng = np.random.default_rng(seed_val)

        home_goals = rng.poisson(lh, iterations)
        away_goals = rng.poisson(la, iterations)

        h_wins = int(np.sum(home_goals > away_goals))
        draws = int(np.sum(home_goals == away_goals))
        a_wins = int(np.sum(home_goals < away_goals))

        over_15 = int(np.sum((home_goals + away_goals) > 1.5))
        over_25 = int(np.sum((home_goals + away_goals) > 2.5))
        btts_sim = int(np.sum((home_goals > 0) & (away_goals > 0)))

        scores = {}
        for hg, ag in zip(home_goals, away_goals):
            key = f"{hg}-{ag}"
            scores[key] = scores.get(key, 0) + 1

        sorted_scores = sorted(scores.items(), key=lambda x: x[1], reverse=True)

        return {
            "iteraciones": iterations,
            "xg_local": round(lh, 2),
            "xg_visitante": round(la, 2),
            "simulacion_1x2": {
                "victoria_local_pct": round(h_wins / iterations * 100, 1),
                "empate_pct": round(draws / iterations * 100, 1),
                "victoria_visitante_pct": round(a_wins / iterations * 100, 1)
            },
            "over_1_5_pct": round(over_15 / iterations * 100, 1),
            "over_2_5_pct": round(over_25 / iterations * 100, 1),
            "btts_pct": round(btts_sim / iterations * 100, 1),
            "marcadores_mas_frecuentes": [
                {"marcador": s[0], "frecuencia_pct": round(s[1] / iterations * 100, 1)}
                for s in sorted_scores[:4]
            ]
        }

    @staticmethod
    def evaluate_kelly_stake(prob_percent: float, market_odds: float, bankroll: float = 1000.0) -> dict:
        if market_odds <= 1.0 or prob_percent <= 0:
            return {"ev_percent": 0.0, "value_detected": False, "stake_percent": 0.0, "monto_sugerido_soles": 0.0}

        p = prob_percent / 100.0
        implied_p = 1.0 / market_odds
        edge = p - implied_p
        ev = (p * market_odds) - 1.0

        b = market_odds - 1.0
        q = 1.0 - p
        full_kelly = (b * p - q) / b if b > 0 else 0.0
        fractional_kelly = max(0.0, full_kelly * 0.25)

        has_value = ev > 0 and edge >= 0.02
        stake_pct = min(2.5, round(fractional_kelly * 100, 2)) if has_value else 0.0

        return {
            "ev_percent": round(ev * 100, 2),
            "edge_percent": round(edge * 100, 2),
            "value_detected": has_value,
            "stake_percent": stake_pct,
            "monto_sugerido_soles": round(bankroll * (stake_pct / 100.0), 2)
        }

    @classmethod
    def _seleccionar_mejor_prop_partido(cls, home: str, away: str) -> dict:
        """Selecciona exclusivamente al referente TITULAR #1 (Opción A) y menciona al 2do titular (Opción B)
        como respaldo en caso de rotación o baja de última hora."""
        if "get_players_for_team" not in globals():
            return None
        pls_h = get_players_for_team(home) or []
        pls_a = get_players_for_team(away) or []
        # Filtrar rigurosamente solo delanteros/atacantes titulares habituales, descartando suplentes
        h_starters = [p for p in pls_h if 'suplente' not in str(p.get('rol_plantilla', '')).lower() and float(re.sub(r'[^0-9.]', '', str(p.get('prob_titular', '90'))) or 90) >= 80]
        if not h_starters: h_starters = pls_h
        a_starters = [p for p in pls_a if 'suplente' not in str(p.get('rol_plantilla', '')).lower() and float(re.sub(r'[^0-9.]', '', str(p.get('prob_titular', '90'))) or 90) >= 80]
        if not a_starters: a_starters = pls_a

        starters = []
        if h_starters:
            starters.append((h_starters[0], h_starters[1] if len(h_starters) > 1 else None, home))
        if a_starters:
            starters.append((a_starters[0], a_starters[1] if len(a_starters) > 1 else None, away))
        if not starters:
            return None

        # Priorizar al titular #1 del equipo con mayor proyección ofensiva
        best_tuple = max(starters, key=lambda item: float(item[0].get("tiros_puerta_prom", 1.8)) * 1.5 + float(item[0].get("tiros_totales_prom", 3.2)))
        best_p, backup_p, eq_label = best_tuple
        tp = float(best_p.get("tiros_puerta_prom", 1.9))
        tt = float(best_p.get("tiros_totales_prom", 3.4))
        nombre = best_p.get("nombre", "")
        eq = best_p.get("equipo", eq_label)
        mkt_base = best_p.get("mercado_principal") or "Más de 1.5 Tiros Totales"
        prob_str = best_p.get("probabilidad_principal") or "84.5%"
        prob = float(re.sub(r'[^0-9.]', '', str(prob_str)) or 84.5)

        mkt = f"{nombre} ({eq}): {mkt_base} 🎯"
        backup_txt = f" (Opción B titular en plantilla: {backup_p['nombre']} - {backup_p.get('mercado_principal', 'Más de 0.5 Tiros a Puerta')})" if backup_p else ""
        just = f"Titular principal de {eq}: {nombre} promedia {tp} tiros a puerta y {tt} disparos totales por partido.{backup_txt}"
        return {"mercado": mkt, "prob": prob, "justificacion": just, "jugador": nombre, "equipo": eq}

    @classmethod
    def _calcular_cuota_rotativa_calibrada(cls, prob_pct: float, num_selecciones: int, match_hash: int, tipo_mercado: str) -> float:
        """
        Fase 3: Calcula la cuota justa implícita del modelo (100 / prob_pct) sin usar tablas
        rotativas por hash ni simular cuotas reales de casas de apuestas.
        """
        p = max(5.0, min(95.0, float(prob_pct or 50.0)))
        return round(100.0 / p, 2)

    @classmethod
    def generate_institutional_analysis(cls, match_data: dict) -> dict:
        if not isinstance(match_data, dict):
            match_data = {}
        raw_home = match_data.get("local")
        raw_away = match_data.get("visitante")
        home = str(raw_home).strip() if raw_home is not None else ""
        away = str(raw_away).strip() if raw_away is not None else ""
        if not home or not away:
            logger.warning("fixture descartado: equipos incompletos")
            home = home or "Local"
            away = away or "Visitante"
        code = str(match_data.get("codigo_liga") or "").strip()
        fecha_partido = resolve_match_local_date(match_data)[1] or "2026-10-19"

        h_stat = cls.get_team_stats(home, code, before_date=fecha_partido)
        a_stat = cls.get_team_stats(away, code, before_date=fecha_partido)

        lh, la, fouls = cls.derive_team_ratings(home, away, code, before_date=fecha_partido)
        probs = cls.evaluate_match_probabilities(lh, la)
        p1x2 = probs["1X2"]
        pGoles = probs["over_under_2_5"]
        pGoles15 = probs["over_under_1_5"]
        pBtts = probs["btts"]

        p1X = round(p1x2["1"] + p1x2["X"], 1)
        pX2 = round(p1x2["X"] + p1x2["2"], 1)

        pts_h, wins_h, draws_h, losses_h = cls._calcular_puntos_racha5(h_stat.get("streak", ""))
        pts_a, wins_a, draws_a, losses_a = cls._calcular_puntos_racha5(a_stat.get("streak", ""))

        suma_xg = round(lh + la, 2)
        diferencia_xg = round(abs(lh - la), 2)
        es_defensa_rota = (lh >= 1.50 and la >= 1.35) or (suma_xg >= 3.05) or h_stat.get('ga_last3', 0) >= 7 or a_stat.get('ga_last3', 0) >= 7
        es_duelo_rocoso = (lh <= 1.15 and la <= 0.98) or (suma_xg <= 2.15)

        # =========================================================================
        # MOTOR CUANTITATIVO BIDIRECCIONAL (MÁS DE / OVER  Y  MENOS DE / UNDER)
        # Evalúa simétricamente pisos (Over) y techos (Under) en Goles, Córners,
        # Tarjetas, Ambos Anotan y Doble Oportunidad + Goles.
        # =========================================================================
        # =========================================================================
        # FÓRMULA 2: MODELO CRUZADO PARA CÓRNERS (GENERADOS × CONCEDIDOS POR EL RIVAL)
        # λ_Córners_Local = (Córners_Generados_Local / Prom_Córners_Local_Liga) * (Córners_Concedidos_Visitante / Prom_Córners_Visita_Liga) * Prom_Córners_Local_Liga
        # λ_Córners_Visita = (Córners_Generados_Visita / Prom_Córners_Visita_Liga) * (Córners_Concedidos_Local / Prom_Córners_Local_Liga) * Prom_Córners_Visita_Liga
        # =========================================================================
        league_corners_split = {
            "PD":  (5.25, 4.35),
            "PL":  (5.60, 4.60),
            "BL1": (5.35, 4.45),
            "SA":  (5.15, 4.25),
            "FL1": (5.10, 4.20),
            "PPL": (5.30, 4.40),
            "BSA": (5.55, 4.55),
            "UCL": (5.35, 4.45),
            "UEL": (5.25, 4.35),
            "UNL": (5.00, 4.10),
        }
        prom_corn_loc_liga, prom_corn_vis_liga = league_corners_split.get(code, (5.25, 4.35))
        league_corners_baseline = round(prom_corn_loc_liga + prom_corn_vis_liga, 1)

        enrichment_cache = MatchEnrichmentCache.get_match_enrichment(fecha_partido, home, away)
        enr_valid = bool(enrichment_cache.get("disponible") and not enrichment_cache.get("expirado"))
        enr_metricas = (enrichment_cache.get("metricas") or {}) if enr_valid else {}
        enr_discrepancias = enrichment_cache.get("discrepancias") or []

        _enr_aliases = {
            "tarjetas_home": "cards_home",
            "tarjetas_away": "cards_away",
            "tiros_home": "shots_home",
            "tiros_away": "shots_away",
            "tiros_puerta_home": "shots_on_target_home",
            "tiros_puerta_away": "shots_on_target_away",
            "faltas_home": "fouls_home",
            "faltas_away": "fouls_away",
        }
        def _enr_metric(m_key: str):
            for k_try in (m_key, _enr_aliases.get(m_key)):
                if not k_try:
                    continue
                m_obj = enr_metricas.get(k_try) or {}
                if (
                    m_obj.get("nivel_verificacion") in ("PRIMARIO_OFICIAL", "RESPALDO_SECUNDARIO")
                    and m_obj.get("valor") is not None
                    and m_obj.get("valor") != ""
                ):
                    return m_obj.get("valor"), m_obj.get("fuente", "RESPALDO_SECUNDARIO"), m_obj.get("nivel_verificacion")
            return None, "NO_DISPONIBLE", "NO_DISPONIBLE"

        enr_ch, enr_ch_src, _ = _enr_metric("corners_home")
        enr_ca, enr_ca_src, _ = _enr_metric("corners_away")
        eff_corners_h = h_stat.get("corners") if h_stat.get("corners") is not None else enr_ch
        eff_corners_a = a_stat.get("corners") if a_stat.get("corners") is not None else enr_ca
        corners_fuente = (h_stat.get("fuente") if h_stat.get("corners") is not None else enr_ch_src)
        corners_disponibles = (eff_corners_h is not None and eff_corners_a is not None)

        enr_sh_h, enr_sh_src, _ = _enr_metric("tiros_home")
        enr_sh_a, _, _ = _enr_metric("tiros_away")
        enr_sot_h, enr_sot_src, _ = _enr_metric("tiros_puerta_home")
        enr_sot_a, _, _ = _enr_metric("tiros_puerta_away")
        enr_fl_h, enr_fl_src, _ = _enr_metric("faltas_home")
        enr_fl_a, _, _ = _enr_metric("faltas_away")
        eff_shots_h = h_stat.get("tiros_totales") if h_stat.get("tiros_totales") is not None else enr_sh_h
        eff_shots_a = a_stat.get("tiros_totales") if a_stat.get("tiros_totales") is not None else enr_sh_a
        eff_sot_h = h_stat.get("tiros_puerta") if h_stat.get("tiros_puerta") is not None else enr_sot_h
        eff_sot_a = a_stat.get("tiros_puerta") if a_stat.get("tiros_puerta") is not None else enr_sot_a
        eff_fouls_h = h_stat.get("faltas") if h_stat.get("faltas") is not None else enr_fl_h
        eff_fouls_a = a_stat.get("faltas") if a_stat.get("faltas") is not None else enr_fl_a
        shots_disponibles = (eff_shots_h is not None and eff_shots_a is not None)
        sot_disponibles = (eff_sot_h is not None and eff_sot_a is not None)
        faltas_disponibles = (eff_fouls_h is not None and eff_fouls_a is not None)
        tiros_disponibles = (shots_disponibles and sot_disponibles)

        # Ruta H2H exclusivamente desde caché verificado (sin API-Sports, SofaScore, ESPN ni hashes)
        h2h_directo = {
            "victorias_local": 0,
            "empates": 0,
            "victorias_visitante": 0,
            "total_partidos": 0,
            "resumen": "Sin historial H2H verificado",
            "partidos": [],
            "fuente": "NO_DISPONIBLE",
        }

        match_hash = 0
        estilo_partido = 0

        if tiros_disponibles:
            tiros_comb = float(eff_shots_h) + float(eff_shots_a)
            tiros_arco_comb = float(eff_sot_h) + float(eff_sot_a)
            tasa_precision_interior = round(tiros_arco_comb / max(14.0, tiros_comb), 3)
        else:
            tiros_comb = None
            tiros_arco_comb = None
            tasa_precision_interior = 0.0

        if corners_disponibles:
            raw_corners_h = float(eff_corners_h)
            raw_corners_a = float(eff_corners_a)
            raw_corners_sum = raw_corners_h + raw_corners_a

            def_weak_h = (float(h_stat.get("base_def") or 1.30) * 0.5) + ((float(h_stat.get("ga_last3") or 5) / 5.0) * 0.5)
            def_weak_a = (float(a_stat.get("base_def") or 1.30) * 0.5) + ((float(a_stat.get("ga_last3") or 5) / 5.0) * 0.5)

            corners_concedidos_h = float(h_stat.get("corners_concedidos", round(prom_corn_vis_liga * max(0.75, min(1.35, def_weak_h / 1.30)), 2)))
            corners_concedidos_a = float(a_stat.get("corners_concedidos", round(prom_corn_loc_liga * max(0.75, min(1.35, def_weak_a / 1.30)), 2)))

            lambda_corners_h = (raw_corners_h / prom_corn_loc_liga) * (corners_concedidos_a / prom_corn_loc_liga) * prom_corn_loc_liga
            lambda_corners_a = (raw_corners_a / prom_corn_vis_liga) * (corners_concedidos_h / prom_corn_vis_liga) * prom_corn_vis_liga

            lambda_corners_h = round(max(2.8, min(7.8, lambda_corners_h * 0.75 + raw_corners_h * 0.25)), 2)
            lambda_corners_a = round(max(2.2, min(6.8, lambda_corners_a * 0.75 + raw_corners_a * 0.25)), 2)
            corners_base = round(lambda_corners_h + lambda_corners_a, 1)

            es_ataque_interior_vertical = (
                raw_corners_sum <= 8.4
                or corners_base <= 8.5
                or (suma_xg >= 2.65 and corners_base <= 9.0 and tasa_precision_interior >= 0.41)
            )
            es_asedio_bandas = (
                corners_base >= 9.8
                and (raw_corners_h >= 5.2 or corners_concedidos_a >= 5.2)
                and not es_ataque_interior_vertical
            )

            if es_ataque_interior_vertical:
                corners_estimados = round(max(7.2, min(8.9, corners_base - 0.3)), 1)
            elif es_asedio_bandas:
                corners_estimados = round(min(11.8, corners_base + 0.3), 1)
            else:
                corners_estimados = round(max(7.6, min(11.4, corners_base)), 1)

            p_corn_u85 = sum(cls.calculate_poisson(k, corners_estimados) for k in range(9))
            p_corn_u95 = sum(cls.calculate_poisson(k, corners_estimados) for k in range(10))
            p_corn_u105 = sum(cls.calculate_poisson(k, corners_estimados) for k in range(11))

            prob_corners_75 = round(min(100.0, max(0.0, (1.0 - sum(cls.calculate_poisson(k, corners_estimados) for k in range(8))) * 100.0)), 1)
            prob_corners_85 = round(min(100.0, max(0.0, (1.0 - p_corn_u85) * 100.0)), 1)
            prob_corners_95 = round(min(100.0, max(0.0, (1.0 - p_corn_u95) * 100.0)), 1)
            prob_corners_under_95 = round(min(100.0, max(0.0, p_corn_u95 * 100.0)), 1)
            prob_corners_under_105 = round(min(100.0, max(0.0, p_corn_u105 * 100.0)), 1)
        else:
            raw_corners_h = None
            raw_corners_a = None
            corners_concedidos_h = None
            corners_concedidos_a = None
            lambda_corners_h = None
            lambda_corners_a = None
            corners_base = None
            es_ataque_interior_vertical = False
            es_asedio_bandas = False
            corners_estimados = None
            prob_corners_75 = None
            prob_corners_85 = None
            prob_corners_95 = None
            prob_corners_under_95 = None
            prob_corners_under_105 = None

        # =========================================================================
        # FÓRMULA 3: MODELO CRUZADO PARA TARJETAS + FACTOR ÁRBITRO OFICIAL
        # =========================================================================
        ref_info = RefereeIntelligenceService.get_referee_for_match(home, away, code, fecha_partido, allow_live_lookup=False, match_data=match_data)
        enr_arb, enr_arb_src, _ = _enr_metric("arbitro")
        enr_arb_avg, _, _ = _enr_metric("arbitro_avg_cards")
        if enr_arb and not ref_info.get("arbitro_confirmado"):
            ref_info = dict(ref_info)
            ref_info["arbitro_confirmado"] = True
            ref_info["nombre"] = enr_arb
            ref_info["fuente"] = enr_arb_src
            if enr_arb_avg is not None:
                ref_info["avg_cards"] = float(enr_arb_avg)
                ref_info["factor_rigor"] = round(float(enr_arb_avg) / max(1.0, float(ref_info.get("league_avg_cards") or 4.45)), 3)

        arbitro_confirmado = bool(ref_info.get("arbitro_confirmado") and ref_info.get("nombre") and ref_info.get("avg_cards") is not None)
        enr_cards_h, enr_cards_src, _ = _enr_metric("tarjetas_home")
        enr_cards_a, _, _ = _enr_metric("tarjetas_away")
        eff_cards_h = h_stat.get("tarjetas") if h_stat.get("tarjetas") is not None else enr_cards_h
        eff_cards_a = a_stat.get("tarjetas") if a_stat.get("tarjetas") is not None else enr_cards_a
        cards_fuente = (h_stat.get("fuente") if h_stat.get("tarjetas") is not None else enr_cards_src)
        tarjetas_disponibles = (eff_cards_h is not None and eff_cards_a is not None)
        # Si hay árbitro confirmado pondera por su rigor; si solo hay tarjetas verificadas por equipo usa factor neutro 1.0
        tarjetas_activas = bool(tarjetas_disponibles)

        if tarjetas_activas:
            promedio_tarjetas_liga = float(ref_info.get("league_avg_cards") or 4.45)
            promedio_arbitro = float(ref_info.get("avg_cards")) if arbitro_confirmado else promedio_tarjetas_liga
            factor_arbitro = (promedio_arbitro / max(1.0, promedio_tarjetas_liga)) if arbitro_confirmado else 1.0

            tarjetas_recibidas_h = float(eff_cards_h)
            tarjetas_recibidas_a = float(eff_cards_a)
            tarjetas_provocadas_h = float(h_stat.get('tarjetas_provocadas', round(max(1.3, min(2.7, tarjetas_recibidas_a * 0.52 + (lh / 1.45) * 0.78)), 2)))
            tarjetas_provocadas_a = float(a_stat.get('tarjetas_provocadas', round(max(1.2, min(2.6, tarjetas_recibidas_h * 0.52 + (la / 1.35) * 0.78)), 2)))

            lambda_cards_h = ((tarjetas_recibidas_h + tarjetas_provocadas_a) / 2.0) * factor_arbitro
            lambda_cards_a = ((tarjetas_recibidas_a + tarjetas_provocadas_h) / 2.0) * factor_arbitro

            raw_cards_h = round(max(1.1, min(3.0, lambda_cards_h)), 2)
            raw_cards_a = round(max(1.1, min(3.0, lambda_cards_a)), 2)
            tarjetas_esperadas = round(max(2.4, min(5.6, raw_cards_h + raw_cards_a)), 2)

            p_cards_u35 = sum(cls.calculate_poisson(k, tarjetas_esperadas) for k in range(4))
            p_cards_u45 = sum(cls.calculate_poisson(k, tarjetas_esperadas) for k in range(5))
            p_cards_u55 = sum(cls.calculate_poisson(k, tarjetas_esperadas) for k in range(6))

            prob_cards_over_35 = round(min(100.0, max(0.0, (1.0 - p_cards_u35) * 100.0)), 1)
            prob_cards_over_45 = round(min(100.0, max(0.0, (1.0 - p_cards_u45) * 100.0)), 1)
            prob_cards_under_45 = round(min(100.0, max(0.0, p_cards_u45 * 100.0)), 1)
            prob_cards_under_55 = round(min(100.0, max(0.0, p_cards_u55 * 100.0)), 1)
        else:
            tarjetas_provocadas_h = None
            tarjetas_provocadas_a = None
            raw_cards_h = None
            raw_cards_a = None
            tarjetas_esperadas = None
            p_cards_u35 = None
            p_cards_u45 = None
            p_cards_u55 = None
            prob_cards_over_35 = None
            prob_cards_over_45 = None
            prob_cards_under_45 = None
            prob_cards_under_55 = None

        # Probabilidades exactas de GOLES (Más de / Menos de) por matriz Poisson + Dixon-Coles
        p_under_35 = 0.0
        for g_h in range(4):
            for g_a in range(4 - g_h):
                p_under_35 += cls.calculate_poisson(g_h, lh) * cls.calculate_poisson(g_a, la)
        prob_under_35_pct = round(min(100.0, max(0.0, p_under_35 * 100.0)), 1)
        prob_over_35_pct = round(min(100.0, max(0.0, 100.0 - prob_under_35_pct)), 1)
        prob_under_25_pct = round(min(100.0, max(0.0, float(pGoles.get("under", 0.0)))), 1)
        prob_under_15_pct = round(min(100.0, max(0.0, float(pGoles15.get("under", 0.0)))), 1)
        probs["over_under_3_5"] = {"over": prob_over_35_pct, "under": prob_under_35_pct}

        p_max_win = max(p1x2["1"], p1x2["2"])
        fav_team = home if p1x2["1"] >= p1x2["2"] else away
        opp_team = away if fav_team == home else home
        fav_is_away = (fav_team == away)
        fav_xg = la if fav_is_away else lh
        opp_xg = lh if fav_is_away else la
        do_code_fav = "X2" if fav_is_away else "1X"
        p_do_fav = pX2 if fav_is_away else p1X
        racha_fav = a_stat.get("streak", "") if fav_is_away else h_stat.get("streak", "")
        racha_opp = h_stat.get("streak", "") if fav_is_away else a_stat.get("streak", "")
        pts_fav = pts_a if fav_is_away else pts_h
        pts_opp = pts_h if fav_is_away else pts_a
        losses_opp = losses_h if fav_is_away else losses_a

        # =========================================================================
        # MOTOR DE SELECCIÓN PRINCIPAL BIDIRECCIONAL (MÁS DE Y MENOS DE)
        # La selección ganadora de este bloque se asigna simultáneamente a:
        # 1) pronostico_principal.seleccion (Top 3 y Tarjeta Principal)
        # 2) organizacion_stakazos.nivel_1_base.mercado (Auditoría del Partido)
        # 3) consenso_dual_ia.seleccion_final_consenso (Veredicto Unificado de las 3 IA)
        # =========================================================================
        num_selecciones = 1
        tipo_mercado_code = "GOALS"
        tipster_model_name = "Motor PredicXion IA • Piso Estadístico"
        stat_projection_label = f"Proyección: {suma_xg} goles esperados"
        safety_margin_label = f"Se esperan {suma_xg} goles (supera por +{round(max(0.4, suma_xg - 1.5), 2)} la línea de 1.5)"

        # Caso 1: JUEGO INTERIOR VERTICAL CON POCOS CÓRNERS (Ej. Sassuolo vs Lazio: muchos goles por dentro, <= 8.2 córners esp.)
        if corners_disponibles and corners_estimados <= 8.2 and es_ataque_interior_vertical:
            linea_c_under = "9.5" if corners_estimados <= 7.8 else "10.5"
            conf_val = int(round(prob_corners_under_95 if linea_c_under == "9.5" else prob_corners_under_105))
            mercado_sugerido = f"Menos de {linea_c_under} córners"
            prob_principal = f"{conf_val}%"
            justificacion_quant = (
                f"Ambos equipos atacan por carril interior con alta conversión de tiro y bajo desborde lateral "
                f"(solo {corners_estimados:.1f} córners proyectados: {h_stat.get('corners', 3.8)} {home} + {a_stat.get('corners', 3.8)} {away}). "
                f"El techo de Menos de {linea_c_under} córners ofrece amplia ventaja matemática."
            )
            num_selecciones = 1
            tipo_mercado_code = "CORNERS"
            tipster_model_name = "Motor PredicXion IA • Control de Córners (Under)"
            stat_projection_label = f"Promedio: {corners_estimados:.1f} córners"
            safety_margin_label = f"Promedian {corners_estimados:.1f} córners ({round(float(linea_c_under) - corners_estimados, 1)} debajo del tope {linea_c_under})"

        # Caso 2: SEÑAL BIDIRECCIONAL EN TARJETAS (Menos de 4.5 / 5.5 en duelos limpios o Más de 3.5 / 4.5 en alta fricción)
        elif tarjetas_activas and tarjetas_esperadas <= 3.60:
            linea_t_under = "4.5" if tarjetas_esperadas <= 3.15 else "5.5"
            base_c_prob = prob_cards_under_45 if linea_t_under == "4.5" else prob_cards_under_55
            conf_val = int(round(base_c_prob))
            mercado_sugerido = f"Menos de {linea_t_under} tarjetas"
            prob_principal = f"{conf_val}%"
            justificacion_quant = (
                f"λ Tarjetas proyectado en {tarjetas_esperadas:.2f} ({raw_cards_h:.1f} {home} + {raw_cards_a:.1f} {away}) "
                f"con el árbitro {ref_info.get('nombre')} ({ref_info.get('avg_cards')} tarj./p • {ref_info.get('perfil')}), muy por debajo del límite de {linea_t_under}."
            )
            num_selecciones = 1
            tipo_mercado_code = "CARDS"
            tipster_model_name = "Motor PredicXion IA • Techo Arbitral (Under)"
            stat_projection_label = f"Promedio: {tarjetas_esperadas:.1f} tarjetas"
            safety_margin_label = f"Promedian {tarjetas_esperadas:.1f} tarjetas ({round(float(linea_t_under) - tarjetas_esperadas, 1)} debajo del límite {linea_t_under})"

        elif tarjetas_activas and ((tarjetas_esperadas >= 5.05 and suma_xg < 2.95) or (tarjetas_esperadas >= 4.65 and diferencia_xg <= 0.40)):
            linea_t = "4.5" if tarjetas_esperadas >= 5.30 else "3.5"
            conf_val = int(round(prob_cards_over_45 if linea_t == "4.5" else prob_cards_over_35))
            mercado_sugerido = f"Más de {linea_t} tarjetas"
            prob_principal = f"{conf_val}%"
            justificacion_quant = (
                f"λ Tarjetas cruzado de {tarjetas_esperadas:.2f} ({raw_cards_h:.1f} {home} + {raw_cards_a:.1f} {away}) ponderado con el árbitro "
                f"{ref_info.get('nombre')} ({ref_info.get('avg_cards')} tarj./p • {ref_info.get('perfil')}), superando la línea de {linea_t}."
            )
            num_selecciones = 1
            tipo_mercado_code = "CARDS"
            tipster_model_name = "Motor PredicXion IA • Índice de Fricción (Over)"
            stat_projection_label = f"Promedio: {tarjetas_esperadas:.1f} tarjetas"
            safety_margin_label = f"Promedian {tarjetas_esperadas:.1f} tarjetas (supera por +{round(tarjetas_esperadas - float(linea_t), 1)} la línea {linea_t})"

        # Caso 3: GANADOR CON GOLES (2 selecciones máx.) en supremacía clara verificada o favorito sólido
        elif (p_max_win >= 58.0 and diferencia_xg >= 0.50 and fav_xg >= 1.70 and pGoles15["over"] >= 72.0) or (p_max_win >= 63.0 and fav_xg >= 1.80) or (p_max_win >= 67.0):
            conf_val = int(round(min(p_max_win, pGoles15["over"])))
            mercado_sugerido = f"{fav_team} gana y Más de 1.5 goles"
            prob_principal = f"{conf_val}%"
            justificacion_quant = f"{fav_team} presenta superioridad ofensiva clara ({fav_xg} xG vs {opp_xg} xG; racha {racha_fav}). Combinar ganador y +1.5 goles ofrece alta efectividad."
            num_selecciones = 2
            tipo_mercado_code = "WINNER"
            tipster_model_name = "Motor PredicXion IA • Supremacía xG + Goles"
            stat_projection_label = f"Goles esp.: {lh} vs {la} xG"
            safety_margin_label = f"Ventaja de +{diferencia_xg} goles esperados y total de {suma_xg} goles"

        # Caso 4: CÓRNERS BIDIRECCIONAL (Más de 8.5/9.5 en asedio de bandas vs Menos de 9.5/10.5 en control interior)
        elif corners_disponibles and es_asedio_bandas and corners_estimados >= 10.8:
            linea_c = "9.5" if corners_estimados >= 12.2 else "8.5"
            conf_val = int(round(prob_corners_95 if linea_c == "9.5" else prob_corners_85))
            mercado_sugerido = f"Más de {linea_c} córners"
            prob_principal = f"{conf_val}%"
            justificacion_quant = (
                f"Ambos clubes registran alto desborde por bandas ({h_stat.get('corners', 5.4)} {home} y {a_stat.get('corners', 5.4)} {away}), "
                f"proyectando {corners_estimados:.1f} córners combinados sobre el piso de {linea_c}."
            )
            num_selecciones = 1
            tipo_mercado_code = "CORNERS"
            tipster_model_name = "Motor PredicXion IA • Volumen de Bandas (Over)"
            stat_projection_label = f"Promedio: {corners_estimados:.1f} córners"
            safety_margin_label = f"Promedian {corners_estimados:.1f} córners (supera por +{round(corners_estimados - float(linea_c), 1)} la línea {linea_c})"

        elif corners_disponibles and corners_estimados <= 8.85 and es_ataque_interior_vertical:
            linea_c_u = "9.5" if corners_estimados <= 8.15 else "10.5"
            conf_val = int(round(prob_corners_under_95 if linea_c_u == "9.5" else prob_corners_under_105))
            mercado_sugerido = f"Menos de {linea_c_u} córners"
            prob_principal = f"{conf_val}%"
            justificacion_quant = (
                f"El promedio combinado de córners ({corners_estimados:.1f}) se mantiene por debajo de {linea_c_u}. "
                f"Ambos equipos priorizan pases interiores y finalización rápida sobre centros al área."
            )
            num_selecciones = 1
            tipo_mercado_code = "CORNERS"
            tipster_model_name = "Motor PredicXion IA • Techo de Córners (Under)"
            stat_projection_label = f"Promedio: {corners_estimados:.1f} córners"
            safety_margin_label = f"Promedian {corners_estimados:.1f} córners ({round(float(linea_c_u) - corners_estimados, 1)} debajo del tope {linea_c_u})"

        # Caso 5: DOBLE OPORTUNIDAD + GOLES (Más de 1.5 goles o Menos de 3.5 goles según ritmo xG)
        elif p_do_fav >= 74.0 and pGoles15["over"] >= 75.5 and suma_xg >= 2.52 and diferencia_xg >= 0.28:
            conf_val = int(round(min(p_do_fav, pGoles15["over"])))
            mercado_sugerido = f"{fav_team} gana o empata y Más de 1.5 goles"
            prob_principal = f"{conf_val}%"
            justificacion_quant = f"{fav_team} domina la estabilidad del cruce ({fav_xg} vs {opp_xg} xG) con un piso firme de {suma_xg} goles esperados. Cubre victoria o empate con goles."
            num_selecciones = 2
            tipo_mercado_code = "WINNER"
            tipster_model_name = "Motor PredicXion IA • Doble Oportunidad + Over 1.5"
            stat_projection_label = f"Estabilidad {do_code_fav}: {p_do_fav}%"
            safety_margin_label = f"Cubre victoria o empate ({p_do_fav}%) con {suma_xg} goles esp."

        elif p_do_fav >= 75.0 and prob_under_35_pct >= 74.0 and suma_xg <= 2.25 and diferencia_xg >= 0.22:
            conf_val = int(round(min(p_do_fav, prob_under_35_pct)))
            mercado_sugerido = f"{fav_team} gana o empata y Menos de 3.5 goles"
            prob_principal = f"{conf_val}%"
            justificacion_quant = f"{fav_team} impone control táctico ({fav_xg} vs {opp_xg} xG) en un duelo de ritmo contenido ({suma_xg} goles esperados). Cubre {do_code_fav} bajo el techo de 3.5 goles."
            num_selecciones = 2
            tipo_mercado_code = "WINNER"
            tipster_model_name = "Motor PredicXion IA • Doble Oportunidad + Under 3.5"
            stat_projection_label = f"Control {do_code_fav}: {p_do_fav}% · Under 3.5: {prob_under_35_pct}%"
            safety_margin_label = f"Cubre {do_code_fav} y margen de {round(3.5 - suma_xg, 2)} goles bajo 3.5"

        # Caso 6: GOLES BIDIRECCIONAL (Más de 2.5 / Ambos Anotan / Menos de 2.5 o 3.5 / Más de 1.5)
        elif lh >= 1.30 and la >= 1.20 and suma_xg >= 2.80 and pGoles["over"] >= 55.0:
            conf_val = int(round(pGoles["over"]))
            mercado_sugerido = "Más de 2.5 goles"
            prob_principal = f"{conf_val}%"
            justificacion_quant = f"El techo ofensivo proyecta {suma_xg} goles esperados ({lh} vs {la} xG). Ritmo abierto de ambos ataques que respalda superar los 2.5 goles."
            num_selecciones = 1
            tipo_mercado_code = "GOALS"
            tipster_model_name = "Motor PredicXion IA • Alto Volumen de Goles (Over)"
            stat_projection_label = f"Proyección: {suma_xg} goles esp."
            safety_margin_label = f"Se esperan {suma_xg} goles (supera por +{round(suma_xg - 2.5, 2)} la línea de 2.5)"

        elif lh >= 1.44 and la >= 1.38 and diferencia_xg <= 0.36 and pBtts["yes"] >= 63.0:
            conf_val = int(round(pBtts["yes"]))
            mercado_sugerido = "Ambos equipos anotan: Sí"
            prob_principal = f"{conf_val}%"
            justificacion_quant = f"Ambos ataques registran alta conversión ({lh} xG {home} vs {la} xG {away}). El modelo proyecta gol en ambas áreas con margen sobre el promedio."
            num_selecciones = 1
            tipo_mercado_code = "BTTS"
            tipster_model_name = "Motor PredicXion IA • Gol en Ambas Áreas"
            stat_projection_label = f"Ambos anotan: {conf_val}% ({suma_xg} xG)"
            safety_margin_label = f"Ambos clubes superan 1.38 goles esperados ({lh} y {la} xG)"

        elif (es_duelo_rocoso and suma_xg <= 2.10 and fav_xg <= 1.35 and opp_xg <= 1.10 and p_max_win < 56.0) or (suma_xg <= 1.90 and p_max_win < 54.0):
            linea_g_under = "2.5" if suma_xg <= 1.75 else "3.5"
            conf_val = int(round(prob_under_25_pct if linea_g_under == "2.5" else prob_under_35_pct))
            mercado_sugerido = f"Menos de {linea_g_under} goles"
            prob_principal = f"{conf_val}%"
            justificacion_quant = f"La proyección combinada es contenida ({suma_xg} xG totales: {lh} vs {la}). Dos bloques tácticos compactos que mantienen el marcador por debajo de {linea_g_under} goles."
            num_selecciones = 1
            tipo_mercado_code = "GOALS"
            tipster_model_name = "Motor PredicXion IA • Techo Defensivo (Under)"
            stat_projection_label = f"Proyección: {suma_xg} goles esp."
            safety_margin_label = f"Se esperan {suma_xg} goles ({round(float(linea_g_under) - suma_xg, 2)} debajo del tope de {linea_g_under})"

        # Caso 7: MÁS DE 1.5 GOLES (Piso Estadístico de Alta Efectividad)
        elif (suma_xg >= 2.15 and pGoles15["over"] >= 70.0) or (fav_xg >= 1.60 and pGoles15["over"] >= 68.0):
            conf_val = int(round(pGoles15["over"]))
            mercado_sugerido = "Más de 1.5 goles"
            prob_principal = f"{conf_val}%"
            justificacion_quant = f"El piso ofensivo proyecta {suma_xg} goles esperados ({lh} vs {la} xG). Más de 1.5 goles asegura alta efectividad sin exponer el pick al 2.5."
            num_selecciones = 1
            tipo_mercado_code = "GOALS"
            tipster_model_name = "Motor PredicXion IA • Piso de Goles (Over)"
            stat_projection_label = f"Proyección: {suma_xg} goles esp."
            safety_margin_label = f"Se esperan {suma_xg} goles (supera por +{round(suma_xg - 1.5, 2)} la línea de 1.5)"

        # Caso 8: DOBLE OPORTUNIDAD DIRECTA
        else:
            fav_do = home if p1X >= pX2 else away
            do_code = '1X' if p1X >= pX2 else 'X2'
            conf_val = int(round(max(p1X, pX2)))
            mercado_sugerido = f"{fav_do} gana o empata"
            prob_principal = f"{conf_val}%"
            justificacion_quant = f"{fav_do} luce más sólido en el cruce estadístico ({lh} vs {la} xG). La doble oportunidad ({do_code}) protege el resultado ante un posible empate."
            num_selecciones = 1
            tipo_mercado_code = "WINNER"
            tipster_model_name = "Motor PredicXion IA • Cobertura de Empate"
            stat_projection_label = f"Señal {do_code}: {conf_val}%"
            safety_margin_label = f"Cubre victoria de {fav_do} o empate ({conf_val}% prob.)"

        cuota_calibrada = cls._calcular_cuota_rotativa_calibrada(conf_val, num_selecciones, match_hash, tipo_mercado_code)
        signal_hash = "ODD-" + hashlib.sha256(f"oddster_lock_{fecha_partido}_{home}_{away}_{mercado_sugerido}".encode("utf-8")).hexdigest()[:8].upper()

        # =========================================================================
        # ESTRUCTURA DE STAKAZOS 100% ALINEADA CON EL PRONÓSTICO PRINCIPAL Y LAS 3 IA
        # =========================================================================
