CALENDAR_MASTER_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "calendario_completo_temporada_2026_2027.json")
EMBEDDED_CALENDAR_2026_2027_B64 = ""

def _sync_master_calendar_file():
    """Carga calendario_completo_temporada_2026_2027.json como fuente canónica en disco.
    Si el archivo no existe en disco, lo genera automáticamente desde EMBEDDED_CALENDAR_2026_2027_B64
    (ambas fuentes se mantienen idénticas y verificadas por prueba unitaria)."""
    try:
        if os.path.exists(CALENDAR_MASTER_PATH):
            with open(CALENDAR_MASTER_PATH, "r", encoding="utf-8") as f:
                disk_list = json.load(f)
            if isinstance(disk_list, list) and len(disk_list) > 0:
                return disk_list
        raw_bytes = zlib.decompress(base64.b64decode(EMBEDDED_CALENDAR_2026_2027_B64.encode("ascii")))
        master_list = json.loads(raw_bytes.decode("utf-8"))
        with open(CALENDAR_MASTER_PATH, "w", encoding="utf-8") as f:
            json.dump(master_list, f, ensure_ascii=False, indent=2)
        return master_list
    except Exception as exc:
        logger.warning("No se pudo cargar/sincronizar calendario maestro en disco: %s", exc)
        return None

_EMBEDDED_MASTER_CALENDAR_CACHE = _sync_master_calendar_file()

def get_active_calendar_window():
    """
    Calcula dinámicamente la ventana activa bimestral de 2 meses.
    Respeta overrides explícitos en CALENDAR_WINDOW_START / CALENDAR_WINDOW_END si fueron configurados.
    """
    global _CURRENT_ACTIVE_WINDOW
    env_start = (os.getenv("CALENDAR_WINDOW_START") or "").strip()
    env_end = (os.getenv("CALENDAR_WINDOW_END") or "").strip()
    if re.match(r"^\d{4}-\d{2}-\d{2}$", env_start) and re.match(r"^\d{4}-\d{2}-\d{2}$", env_end):
        _CURRENT_ACTIVE_WINDOW = {
            "start_date": env_start,
            "end_date": env_end,
            "fase_nombre": f"Ventana Activa: {env_start} al {env_end}"
        }
        return env_start, env_end

    op_date = get_current_operational_date()
    if op_date <= "2026-10-31":
        _CURRENT_ACTIVE_WINDOW = {
            "start_date": "2026-10-12",
            "end_date": "2026-11-30",
            "fase_nombre": "Ventana Activa: 12 Octubre al 30 Noviembre 2026"
        }
    elif op_date <= "2026-12-31":
        _CURRENT_ACTIVE_WINDOW = {
            "start_date": "2026-11-01",
            "end_date": "2026-12-31",
            "fase_nombre": "Ventana Bimestral Activa: 01 Noviembre al 31 Diciembre 2026"
        }
    elif op_date <= "2027-02-28":
        _CURRENT_ACTIVE_WINDOW = {
            "start_date": "2027-01-01",
            "end_date": "2027-02-28",
            "fase_nombre": "Ventana Bimestral Activa: 01 Enero al 28 Febrero 2027"
        }
    elif op_date <= "2027-04-30":
        _CURRENT_ACTIVE_WINDOW = {
            "start_date": "2027-03-01",
            "end_date": "2027-04-30",
            "fase_nombre": "Ventana Bimestral Activa: 01 Marzo al 30 Abril 2027"
        }
    else:
        _CURRENT_ACTIVE_WINDOW = {
            "start_date": "2027-05-01",
            "end_date": "2027-05-31",
            "fase_nombre": "Ventana Final: 01 Mayo al 31 Mayo 2027"
        }

    return _CURRENT_ACTIVE_WINDOW["start_date"], _CURRENT_ACTIVE_WINDOW["end_date"]

_SYNCED_EXTERNAL_FD_FIXTURES = []

def _raw_tuples_to_fixtures(raw_tuples=None) -> list:
    tuples_src = raw_tuples if raw_tuples is not None else (globals().get("OFFICIAL_ACTIVE_MATCHES_RAW") or [])
    out = []
    for mid, loc, vis, dt, jor, liga, cod in tuples_src:
        f_prog, f_loc = resolve_match_local_date({"fecha_utc": dt})
        out.append({
            "id_partido": mid,
            "local": loc,
            "visitante": vis,
            "fecha_utc": dt,
            "fecha": f_loc or dt[:10],
            "fecha_programada": f_prog or dt,
            "fecha_local_partido": f_loc or dt[:10],
            "hora": dt[11:16] if len(dt) >= 16 else "14:00",
            "jornada": jor,
            "liga": normalizar_nombre_liga(liga),
            "codigo_liga": cod,
            "estado": "SCHEDULED",
            "temporada": "2026/2027",
            "origen_fuente": "calendario_manual_tuplas",
        })
    return out

CALENDAR_SOURCE_PRIORITY = [
    "football-data.org",
    "calendario_manual_tuplas",
    "calendario_maestro_embebido",
]

def _dates_within_days(d1: str, d2: str, max_days: int = 14) -> bool:
    try:
        dt1 = datetime.strptime(str(d1)[:10], "%Y-%m-%d")
        dt2 = datetime.strptime(str(d2)[:10], "%Y-%m-%d")
        return abs((dt1 - dt2).days) <= max_days
    except Exception:
        return False

def build_multimonth_calendar(extra_fd_fixtures: list = None):
    """
    Construye el calendario oficial del periodo activo aplicando prioridad de fuente oficial verificada:
      1. football-data.org (_SYNCED_EXTERNAL_FD_FIXTURES / extra_fd_fixtures) -> autoridad de fecha/estado
      2. Calendario manual en memoria (OFFICIAL_ACTIVE_MATCHES_RAW)
      3. Calendario maestro embebido (EMBEDDED_CALENDAR_2026_2027_B64 / disco)
    Reglas:
      - Highlightly, ESPN y API-Sports nunca reemplazan ni inyectan fixtures en ALL_FIXTURES_POOL.
      - Si football-data.org confirma otra fecha oficial para el mismo duelo (dentro de ±14 días),
        se rechaza el registro obsoleto del calendario embebido para evitar partidos históricos desplazados.
      - Deduplica únicamente por fecha_local_lima|local_normalizado|visitante_normalizado.
    """
    start_date, end_date = get_active_calendar_window()

    master_source = _EMBEDDED_MASTER_CALENDAR_CACHE
    if not master_source:
        try:
            raw_bytes = zlib.decompress(base64.b64decode(EMBEDDED_CALENDAR_2026_2027_B64.encode("ascii")))
            master_source = json.loads(raw_bytes.decode("utf-8"))
        except Exception:
            master_source = []

    raw_manual_source = _raw_tuples_to_fixtures()
    fd_synced_source = list(extra_fd_fixtures if extra_fd_fixtures is not None else (_SYNCED_EXTERNAL_FD_FIXTURES or []))

    # 1. Indexar primero los partidos verificados de football-data.org (máxima prioridad)
    verified_fd_by_pair = {}
    ordered_candidates = []
    for f in fd_synced_source:
        src_prov = str(f.get("origen_fuente") or f.get("proveedor") or "football-data.org").lower()
        if any(bad in src_prov for bad in ("highlightly", "espn", "api-sports", "apisports")):
            continue
        d_copy = dict(f)
        d_copy["origen_fuente"] = "football-data.org"
        loc = str(d_copy.get("local") or "").strip()
        vis = str(d_copy.get("visitante") or "").strip()
        if not loc or not vis:
            continue
        f_prog, f_loc, f_lima_iso = resolve_match_datetime_lima(d_copy)
        if not f_loc:
            continue
        d_copy["fecha"] = f_loc
        d_copy["fecha_local_partido"] = f_loc
        d_copy["fecha_programada"] = f_prog or d_copy.get("fecha_utc") or f_loc
        d_copy["fecha_hora_america_lima"] = f_lima_iso
        pair_k = f"{canonical_team_name(loc)}|{canonical_team_name(vis)}"
        verified_fd_by_pair.setdefault(pair_k, []).append(f_loc)
        ordered_candidates.append(d_copy)

    # 2. Prioridad estricta: 3) calendario manual validado, 4) calendario maestro únicamente como respaldo
    for f in raw_manual_source:
        d_man = dict(f)
        d_man.setdefault("origen_fuente", "calendario_manual_validado")
        ordered_candidates.append(d_man)
    for f in (master_source or []):
        d_copy = dict(f)
        d_copy.setdefault("origen_fuente", "calendario_maestro_respaldo")
        ordered_candidates.append(d_copy)

    calendar = []
    seen_canonical = set()
    seen_ids = set()
    seen_pair_comp_dates = {}
    for fix in ordered_candidates:
        loc = str(fix.get("local") or "").strip()
        vis = str(fix.get("visitante") or "").strip()
        if not loc or not vis:
            continue
        f_prog, f_loc, f_lima_iso = resolve_match_datetime_lima(fix)
        if not f_loc or not (start_date <= f_loc <= end_date):
            continue
        pair_k = f"{canonical_team_name(loc)}|{canonical_team_name(vis)}"
        src = str(fix.get("origen_fuente") or "calendario_maestro_embebido")
        # Rechazar partido estático si football-data.org ya verificó ese mismo duelo en otra fecha (±14 días)
        if src != "football-data.org" and pair_k in verified_fd_by_pair:
            verified_dates = verified_fd_by_pair[pair_k]
            if f_loc not in verified_dates and any(_dates_within_days(f_loc, vd, 14) for vd in verified_dates):
                logger.info(
                    "[CalendarAuthority] Rechazado partido obsoleto %s vs %s en %s (%s); fecha oficial verificada: %s",
                    loc, vis, f_loc, src, verified_dates
                )
                continue

        comp_norm = normalize_competition_code(fix.get("codigo_liga", ""), fix.get("liga", ""))
        fix["codigo_liga"] = comp_norm
        mid_k = str(fix.get("id_partido") or "").strip()
        if mid_k and mid_k in seen_ids:
            logger.debug("[CalendarPriority] Descartado respaldo con id_partido duplicado %s (%s vs %s en %s, fuente=%s)", mid_k, loc, vis, f_loc, src)
            continue
        pc_key = f"{comp_norm}|{pair_k}"
        prev_dates = seen_pair_comp_dates.get(pc_key, [])
        if prev_dates and f_loc not in prev_dates and any(_dates_within_days(f_loc, pd_d, 7) for pd_d in prev_dates):
            logger.info("[CalendarPriority] Discrepancia de fecha entre fuentes para %s vs %s (%s): se conserva %s y se descarta %s (%s)", loc, vis, comp_norm, prev_dates, f_loc, src)
            continue
        ckey = f"{f_loc}|{comp_norm}|{pair_k}"
        if ckey in seen_canonical:
            continue
        seen_canonical.add(ckey)
        if mid_k:
            seen_ids.add(mid_k)
        seen_pair_comp_dates.setdefault(pc_key, []).append(f_loc)
        fix["fecha"] = f_loc
        fix["fecha_local_partido"] = f_loc
        fix["fecha_programada"] = f_prog or fix.get("fecha_utc") or f_loc
        fix["fecha_hora_america_lima"] = f_lima_iso
        fix["liga"] = normalizar_nombre_liga(fix.get("liga", "Otras Ligas"))
        if not fix.get("id_partido"):
            cod_l = str(fix.get("codigo_liga") or "OFL").lower()
            fix["id_partido"] = f"{cod_l}-{f_loc}-{canonical_team_name(loc)[:3]}-{canonical_team_name(vis)[:3]}"
        calendar.append(fix)

    logger.info("Cargados %d partidos oficiales verificados (ventana %s a %s).",
                len(calendar), start_date, end_date)
    return calendar

def build_all_club_fixtures():
    return build_multimonth_calendar()

CLUB_INTEGRATED_FIXTURES = build_all_club_fixtures()
ALL_FIXTURES_POOL = CLUB_INTEGRATED_FIXTURES

def _log_pool_counts(etapa: str):
    """Registra el total de partidos y el conteo por competición en ALL_FIXTURES_POOL sin modificar el calendario."""
    pool = globals().get("ALL_FIXTURES_POOL") or []
    conteo = {}
    for f in pool:
        c = f.get("codigo_liga") or "OTRA"
        conteo[c] = conteo.get(c, 0) + 1
    logger.info("[CalendarPool:%s] total=%d por_competicion=%s", etapa, len(pool), dict(sorted(conteo.items())))
    return {"total": len(pool), "por_competicion": conteo}

_log_pool_counts("ARRANQUE_INICIAL")


class CalendarSyncService:
    SOURCE_PRIORITY = {
        1: "fuente_oficial_verificada",
        2: "fuente_secundaria_verificada",
        3: "calendario_manual_validado",
        4: "calendario_maestro_respaldo",
    }
    """
    Fase 2: Auditoría y sincronización segura del Calendario Maestro.
    - Respeta el calendario manual (ALL_FIXTURES_POOL) como fuente propia de fixtures:
      NUNCA sobrescribe ni borra partidos manuales automáticamente.
    - Detecta duplicados, partidos mal asignados, faltantes y desfases de fecha vs football-data.org.
    - Expone overlay O(1) en memoria para /obtener-pronostico sin llamadas HTTP en vivo.
    """
    _LOCK = threading.RLock()
    _STATUS_OVERLAY = {}
    _LAST_AUDIT = None
    VALID_COMPETITION_CODES = {"BL1", "BSA", "FL1", "PL", "PPL", "PD", "SA", "UCL", "UEL", "UNL"}

    @classmethod
    def canonical_fixture_key(cls, local: str, visitante: str, fecha: str, competition_code: str = "") -> str:
        """
        Clave única canónica por partido:
          fecha_local_lima | competicion_normalizada | local_normalizado | visitante_normalizado
        """
        h = canonical_team_name(local)
        a = canonical_team_name(visitante)
        _, f_loc = resolve_match_local_date({"fecha_utc": str(fecha or "")}) if "T" in str(fecha or "") else ("", str(fecha or "")[:10])
        comp = normalize_competition_code(competition_code) if competition_code else ""
        if comp:
            return f"{f_loc or str(fecha or '')[:10]}|{comp}|{h}|{a}"
        return f"{f_loc or str(fecha or '')[:10]}|{h}|{a}"

    @classmethod
    def canonical_fixture_key_for(cls, fix: dict) -> str:
        loc = str((fix or {}).get("local") or "").strip()
        vis = str((fix or {}).get("visitante") or "").strip()
        f_loc = CalendarDateService.to_lima_date(fix)
        comp = normalize_competition_code((fix or {}).get("codigo_liga", ""), (fix or {}).get("liga", ""))
        return cls.canonical_fixture_key(loc, vis, f_loc, competition_code=comp)

    @classmethod
    def _fixture_completeness_score(cls, fix: dict) -> tuple:
        src = str(fix.get("origen_fuente") or "calendario_maestro_embebido").lower()
        src_rank = 3 if "football-data" in src else (2 if "manual" in src else 1)
        has_utc = 1 if ("T" in str(fix.get("fecha_utc") or "") and str(fix.get("fecha_utc") or "").endswith("Z")) else 0
        st = str(fix.get("estado") or "").upper()
        st_rank = 2 if st in ("FINISHED", "IN_PLAY", "LIVE", "PAUSED", "POSTPONED", "TIMED") else (1 if st == "SCHEDULED" else 0)
        filled_fields = sum(1 for v in fix.values() if v not in (None, "", [], {}))
        return (src_rank, st_rank, has_utc, filled_fields)

    @classmethod
    def deduplicate_fixtures(cls, fixtures: list, level: str = "IMPORT") -> tuple:
        """
        Deduplicación canónica reutilizable en 3 niveles (IMPORT, CACHE, FRONTEND).
        Conserva siempre el registro más completo cuando hay distinta hora o estado
        y registra la discrepancia sin eliminar partidos legítimos.
        Retorna: (lista_deduplicada, duplicados_eliminados, discrepancias_hora_estado)
        """
        chosen_by_key = {}
        order_keys = []
        duplicados = []
        discrepancias = []

        for raw_f in (fixtures or []):
            if not isinstance(raw_f, dict):
                continue
            loc = str(raw_f.get("local") or "").strip()
            vis = str(raw_f.get("visitante") or "").strip()
            if not loc or not vis:
                logger.warning("fixture descartado: equipos incompletos")
                continue
            fix = dict(raw_f)
            f_prog, f_loc, f_lima_iso = CalendarDateService.to_lima_datetime(fix)
            if not f_loc:
                continue
            comp = normalize_competition_code(fix.get("codigo_liga", ""), fix.get("liga", ""))
            fix["codigo_liga"] = comp
            fix["fecha"] = f_loc
            fix["fecha_local_partido"] = f_loc
            fix["fecha_programada"] = f_prog or fix.get("fecha_utc") or f_loc
            fix["fecha_hora_america_lima"] = f_lima_iso
            fix["liga"] = normalizar_nombre_liga(fix.get("liga") or FootballDataOrgClient.COMPETITION_NAMES.get(comp, comp))

            ckey = cls.canonical_fixture_key(loc, vis, f_loc, competition_code=comp)
            if ckey not in chosen_by_key:
                chosen_by_key[ckey] = fix
                order_keys.append(ckey)
            else:
                prev = chosen_by_key[ckey]
                prev_h = str(prev.get("fecha_utc") or "")[11:16]
                curr_h = str(fix.get("fecha_utc") or "")[11:16]
                prev_st = str(prev.get("estado") or "").upper()
                curr_st = str(fix.get("estado") or "").upper()
                if (prev_h and curr_h and prev_h != curr_h) or (prev_st and curr_st and prev_st != curr_st):
                    discrepancias.append({
                        "nivel": level,
                        "clave_canonica": ckey,
                        "partido": f"{prev.get('local')} vs {prev.get('visitante')}",
                        "hora_a": prev_h,
                        "hora_b": curr_h,
                        "estado_a": prev_st,
                        "estado_b": curr_st,
                        "fuente_a": prev.get("origen_fuente"),
                        "fuente_b": fix.get("origen_fuente"),
                    })
                if cls._fixture_completeness_score(fix) > cls._fixture_completeness_score(prev):
                    # Conservar el registro más completo preservando id_partido estable si ya existía
                    if prev.get("id_partido") and not fix.get("id_partido"):
                        fix["id_partido"] = prev["id_partido"]
                    duplicados.append({
                        "nivel": level,
                        "clave_canonica": ckey,
                        "descartado_id": prev.get("id_partido"),
                        "conservado_id": fix.get("id_partido"),
                        "fuente_descartada": prev.get("origen_fuente"),
                        "fuente_conservada": fix.get("origen_fuente"),
                    })
                    chosen_by_key[ckey] = fix
                else:
                    duplicados.append({
                        "nivel": level,
                        "clave_canonica": ckey,
                        "descartado_id": fix.get("id_partido"),
                        "conservado_id": prev.get("id_partido"),
                        "fuente_descartada": fix.get("origen_fuente"),
                        "fuente_conservada": prev.get("origen_fuente"),
                    })

        dedup_list = CalendarDateService.sort_fixtures([chosen_by_key[k] for k in order_keys])
        return dedup_list, duplicados, discrepancias

    @classmethod
    def audit_manual_calendar(cls, fixtures: list = None) -> dict:
        pool = fixtures if fixtures is not None else globals().get("ALL_FIXTURES_POOL", [])
        start_date, end_date = get_active_calendar_window()
        seen_keys = {}
        seen_ids = set()
        duplicados = []
        mal_asignados = []
        fuera_de_ventana = []

        for fix in pool:
            fid = fix.get("id_partido")
            loc = (fix.get("local") or "").strip()
            vis = (fix.get("visitante") or "").strip()
            f_utc = str(fix.get("fecha_utc") or fix.get("fecha") or "")
            fecha = f_utc[:10]
            cod = (fix.get("codigo_liga") or "").strip().upper()

            if not loc or not vis or len(fecha) != 10 or cod not in cls.VALID_COMPETITION_CODES:
                mal_asignados.append({
                    "id_partido": fid,
                    "local": loc,
                    "visitante": vis,
                    "fecha": fecha,
                    "codigo_liga": cod,
                    "motivo": "campos_incompletos_o_liga_invalida",
                })

            if fecha and not (start_date <= fecha <= end_date):
                fuera_de_ventana.append({"id_partido": fid, "local": loc, "visitante": vis, "fecha": fecha})

            ckey = cls.canonical_fixture_key(loc, vis, fecha)
            if ckey in seen_keys or (fid and fid in seen_ids):
                duplicados.append({
                    "id_partido": fid,
                    "key": ckey,
                    "duplicado_de": seen_keys.get(ckey),
                })
            else:
                seen_keys[ckey] = fid
                if fid:
                    seen_ids.add(fid)

        return {
            "total_manual": len(pool),
            "ventana_activa": {"inicio": start_date, "fin": end_date},
            "duplicados": duplicados,
            "mal_asignados": mal_asignados,
            "fuera_de_ventana": fuera_de_ventana,
            "total_duplicados": len(duplicados),
            "total_mal_asignados": len(mal_asignados),
            "total_fuera_de_ventana": len(fuera_de_ventana),
        }

    @classmethod
    def sync_verify_with_football_data(cls, competition_codes: list = None, date_from: str = "", date_to: str = "", fixtures: list = None) -> dict:
        """
        Cruza los fixtures manuales contra football-data.org SIN modificar ni eliminar partidos manuales.
        Registra faltantes, desfases de fecha y estados actualizados en _STATUS_OVERLAY.
        """
        pool = fixtures if fixtures is not None else globals().get("ALL_FIXTURES_POOL", [])
        codes = competition_codes or sorted(cls.VALID_COMPETITION_CODES)

        # Indexar calendario manual por clave canónica y por par de equipos
        manual_by_key = {}
        manual_by_pair = {}
        nf = globals().get("_norm_equipo")
        for fix in pool:
            loc = fix.get("local", "")
            vis = fix.get("visitante", "")
            fecha = resolve_match_local_date(fix)[1]
            ckey = cls.canonical_fixture_key(loc, vis, fecha)
            manual_by_key[ckey] = fix
            h_n = nf(loc) if nf else loc.lower().strip()
            a_n = nf(vis) if nf else vis.lower().strip()
            manual_by_pair.setdefault(f"{h_n}|{a_n}", []).append(fix)

        faltantes_en_manual = []
        fechas_discrepantes = []
        verificados = 0
        errores_proveedor = []

        for cod in codes:
            fd_code = FootballDataOrgClient.COMPETITION_CODE_MAP.get(cod, cod)
            params = {}
            if date_from:
                params["dateFrom"] = date_from[:10]
            if date_to:
                params["dateTo"] = date_to[:10]
            res = FootballDataOrgClient.fetch_json(
                f"/competitions/{fd_code}/matches",
                competition_code=cod,
                params=params or None,
                ttl_seconds=900,
            )
            if not res.get("ok") or not res.get("data"):
                errores_proveedor.append({"competicion": cod, "error": res.get("error")})
                continue

            for m in (res["data"].get("matches") or []):
                h_fd = (m.get("homeTeam") or {}).get("name", "")
                a_fd = (m.get("awayTeam") or {}).get("name", "")
                utc_fd = str(m.get("utcDate") or "")
                f_fd = utc_fd[:10]
                st_fd = m.get("status", "SCHEDULED")
                if not h_fd or not a_fd or not f_fd:
                    continue

                # Calcular fecha local en America/Lima para validar fecha, hora y zona horaria
                _, f_fd_lima = resolve_match_local_date({"fecha_utc": utc_fd})
                ckey_fd = cls.canonical_fixture_key(h_fd, a_fd, f_fd_lima or f_fd)
                if ckey_fd in manual_by_key:
                    m_fix = manual_by_key[ckey_fd]
                    utc_man = str(m_fix.get("fecha_utc") or "")
                    hora_man = utc_man[11:16] if len(utc_man) >= 16 else ""
                    hora_fd = utc_fd[11:16] if len(utc_fd) >= 16 else ""
                    if hora_man and hora_fd and hora_man != hora_fd:
                        fechas_discrepantes.append({
                            "id_partido": m_fix.get("id_partido"),
                            "partido": f"{m_fix.get('local')} vs {m_fix.get('visitante')}",
                            "fecha_manual": f_fd_lima or f_fd,
                            "hora_manual_utc": hora_man,
                            "fecha_football_data": f_fd,
                            "hora_football_data_utc": hora_fd,
                            "zona_horaria": "America/Lima (UTC-5)",
                            "motivo": "desfase_hora_sin_mover_automaticamente",
                        })
                    verificados += 1
                    with cls._LOCK:
                        cls._STATUS_OVERLAY[ckey_fd] = {
                            "estado_verificado": st_fd,
                            "fecha_utc_fd": utc_fd,
                            "discrepancia_fecha": False,
                            "origen": "calendario_manual",
                            "fuente_verificacion": "football-data.org",
                            "actualizado_en": datetime.now(timezone.utc).isoformat(),
                        }
                else:
                    # Buscar si existe el mismo duelo en otra fecha (posible partido adelantado/aplazado/erróneo)
                    h_n = nf(h_fd) if nf else h_fd.lower().strip()
                    a_n = nf(a_fd) if nf else a_fd.lower().strip()
                    candidates = manual_by_pair.get(f"{h_n}|{a_n}", [])
                    if candidates:
                        man_fix = candidates[0]
                        man_fecha = resolve_match_local_date(man_fix)[1]
                        man_key = cls.canonical_fixture_key(man_fix.get("local", ""), man_fix.get("visitante", ""), man_fecha)
                        fechas_discrepantes.append({
                            "id_partido_manual": man_fix.get("id_partido"),
                            "local": man_fix.get("local"),
                            "visitante": man_fix.get("visitante"),
                            "fecha_manual": man_fecha,
                            "fecha_football_data": f_fd,
                            "estado_football_data": st_fd,
                            "accion": "REGISTRADO_SIN_SOBRESCRIBIR",
                        })
                        with cls._LOCK:
                            cls._STATUS_OVERLAY[man_key] = {
                                "estado_verificado": st_fd,
                                "fecha_utc_fd": utc_fd,
                                "discrepancia_fecha": True,
                                "fecha_manual": man_fecha,
                                "fecha_football_data": f_fd,
                                "origen": "calendario_manual",
                                "fuente_verificacion": "football-data.org",
                                "actualizado_en": datetime.now(timezone.utc).isoformat(),
                            }
                    else:
                        faltantes_en_manual.append({
                            "local": h_fd,
                            "visitante": a_fd,
                            "fecha": f_fd,
                            "codigo_liga": cod,
                            "estado": st_fd,
                        })

        report = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "auditoria_local": cls.audit_manual_calendar(pool),
            "verificados_con_fd": verificados,
            "fechas_discrepantes": fechas_discrepantes,
            "faltantes_en_manual": faltantes_en_manual,
            "errores_proveedor": errores_proveedor,
            "calendario_manual_intacto": True,
        }
        with cls._LOCK:
            cls._LAST_AUDIT = report
            if "db" in globals() and db is not None:
                try:
                    db.collection("calendar_sync_audit").document("latest").set(report, merge=True)
                except Exception as e:
                    logger.debug("Firestore calendar audit write fallback a memoria: %s", e)
        return report

    @classmethod
    def get_fixture_overlay(cls, fix: dict) -> dict:
        loc = fix.get("local", "")
        vis = fix.get("visitante", "")
        fecha = resolve_match_local_date(fix)[1]
        ckey = cls.canonical_fixture_key(loc, vis, fecha)
        with cls._LOCK:
            ov = cls._STATUS_OVERLAY.get(ckey)
        if ov:
            return dict(ov)
        return {
            "estado_verificado": fix.get("estado", "SCHEDULED"),
            "discrepancia_fecha": False,
            "origen": "calendario_manual",
            "fuente_verificacion": "calendario_manual",
        }

    @classmethod
    def convert_fd_match_to_fixture(cls, m: dict, competition_code: str = "BSA") -> dict:
        h_fd = ((m.get("homeTeam") or {}).get("name") or "").strip()
        a_fd = ((m.get("awayTeam") or {}).get("name") or "").strip()
        utc_fd = str(m.get("utcDate") or "").strip()
        _, f_lima = resolve_match_local_date({"fecha_utc": utc_fd})
        cod = str(competition_code or (m.get("competition") or {}).get("code") or "BSA").upper()
        if cod == "CL":
            cod = "UCL"
        elif cod == "EL":
            cod = "UEL"
        liga_name = FootballDataOrgClient.COMPETITION_NAMES.get(cod, normalizar_nombre_liga((m.get("competition") or {}).get("name") or cod))
        mid = m.get("id") or f"{cod.lower()}-{f_lima}-{canonical_team_name(h_fd)[:3]}-{canonical_team_name(a_fd)[:3]}"
        return {
            "id_partido": str(mid),
            "local": h_fd,
            "visitante": a_fd,
            "fecha_utc": utc_fd or f"{f_lima}T15:00:00Z",
            "fecha": f_lima,
            "fecha_programada": utc_fd or f"{f_lima}T15:00:00Z",
            "fecha_local_partido": f_lima,
            "hora": utc_fd[11:16] if len(utc_fd) >= 16 else "15:00",
            "jornada": f"Jornada {m.get('matchday')}" if m.get("matchday") else "Jornada Oficial",
            "liga": liga_name,
            "codigo_liga": cod,
            "estado": m.get("status", "SCHEDULED"),
            "temporada": "2026/2027",
            "origen_fuente": "football-data.org",
        }

    FD_CALENDAR_CACHE_FILE = "/tmp/predicxion_fd_calendar_cache.json"

    @classmethod
    def load_persisted_fd_calendar(cls) -> int:
        global _SYNCED_EXTERNAL_FD_FIXTURES
        try:
            if os.path.exists(cls.FD_CALENDAR_CACHE_FILE):
                with open(cls.FD_CALENDAR_CACHE_FILE, "r", encoding="utf-8") as f:
                    data = json.load(f)
                if isinstance(data, list) and data:
                    _SYNCED_EXTERNAL_FD_FIXTURES = data
                    return len(data)
        except Exception as exc:
            logger.debug("Aviso cargando caché persistente de calendario FD: %s", exc)
        return 0

    @classmethod
    def sync_live_calendar_from_football_data(cls, days_back: int = 7, days_ahead: int = 35, competition_codes: list = None) -> dict:
        """
        Sincroniza el calendario oficial en vivo desde football-data.org para todas las
        competiciones activas (excluyendo DISABLED_COMPETITIONS), reconcilia fechas UTC -> America/Lima
        y reemplaza fechas estáticas desactualizadas sin borrar las demás ligas.
        """
        if not FootballDataOrgClient._get_api_key():
            return {"ok": False, "reason": "FOOTBALL_API_KEY_NOT_SET", "total_fd_matches": 0}

        op_today = get_current_operational_date()
        try:
            dt_op = datetime.strptime(op_today, "%Y-%m-%d")
        except Exception:
            dt_op = datetime.now(timezone(timedelta(hours=-5)))
        date_from = (dt_op - timedelta(days=days_back)).strftime("%Y-%m-%d")
        date_to = (dt_op + timedelta(days=days_ahead)).strftime("%Y-%m-%d")

        codes = competition_codes or sorted([
            c for c in cls.VALID_COMPETITION_CODES
            if is_competition_enabled(c, FootballDataOrgClient.COMPETITION_NAMES.get(c, c))
        ])

        fetched_fixtures = []
        por_liga = {}
        errores = []
        for cod in codes:
            fd_code = FootballDataOrgClient.COMPETITION_CODE_MAP.get(cod, cod)
            res = FootballDataOrgClient.fetch_matches_paginated(
                f"/competitions/{fd_code}/matches",
                competition_code=cod,
                params={"dateFrom": date_from, "dateTo": date_to},
                ttl_seconds=1800,
                timeout_sec=10,
            )
            if not res.get("ok"):
                errores.append({"competicion": cod, "error": res.get("error")})
                continue
            matches = res.get("matches") or (res.get("data") or {}).get("matches") or []
            por_liga[cod] = len(matches)
            for m in matches:
                fetched_fixtures.append(cls.convert_fd_match_to_fixture(m, cod))

        if not fetched_fixtures:
            return {
                "ok": False,
                "reason": "NO_MATCHES_RETURNED",
                "total_fd_matches": 0,
                "errores": errores,
            }

        rec = cls.reconcile_official_calendar(fetched_fixtures)
        try:
            with open(cls.FD_CALENDAR_CACHE_FILE, "w", encoding="utf-8") as f:
                json.dump(_SYNCED_EXTERNAL_FD_FIXTURES, f, ensure_ascii=False)
        except Exception as exc:
            logger.debug("Aviso guardando caché persistente de calendario FD: %s", exc)

        logger.info(
            "[CalendarLiveSync] Sincronizados %d partidos oficiales desde football-data.org (%s a %s) por_liga=%s pool_total=%d",
            len(fetched_fixtures), date_from, date_to, por_liga, rec.get("total_all_fixtures_pool", 0)
        )
        return {
            "ok": True,
            "ventana": {"desde": date_from, "hasta": date_to},
            "total_fd_matches": len(fetched_fixtures),
            "por_competicion": por_liga,
            "errores": errores,
            **rec,
        }

    @classmethod
    def reconcile_official_calendar(cls, fd_matches: list, competition_code: str = "BSA") -> dict:
        """
        Fusiona los partidos oficiales verificados de football-data.org en _SYNCED_EXTERNAL_FD_FIXTURES,
        reconstruye ALL_FIXTURES_POOL rechazando fechas obsoletas del calendario embebido e invalida
        todas las cachés de calendario.
        """
        global _SYNCED_EXTERNAL_FD_FIXTURES
        converted = []
        for m in (fd_matches or []):
            if "homeTeam" in m or "utcDate" in m:
                converted.append(cls.convert_fd_match_to_fixture(m, m.get("codigo_liga") or (m.get("competition") or {}).get("code") or competition_code))
            else:
                d_m = dict(m)
                d_m["origen_fuente"] = "football-data.org"
                converted.append(d_m)

        # Conservar otros fixtures verificados previamente de otras competiciones/fechas sin duplicar
        merged_fd = []
        seen_fd = set()
        for item in converted + list(_SYNCED_EXTERNAL_FD_FIXTURES or []):
            _, f_loc, _ = resolve_match_datetime_lima(item)
            ck = cls.canonical_fixture_key(item.get("local", ""), item.get("visitante", ""), f_loc, competition_code=normalize_competition_code(item.get("codigo_liga", ""), item.get("liga", "")))
            if ck not in seen_fd:
                seen_fd.add(ck)
                merged_fd.append(item)

        _SYNCED_EXTERNAL_FD_FIXTURES = merged_fd
        total_pool = invalidate_calendar_caches(rebuild_pool=True, extra_fd_fixtures=merged_fd)
        return {
            "total_verificados_fd": len(merged_fd),
            "total_all_fixtures_pool": total_pool,
            "cache_invalidada": True,
        }

    @classmethod
    def audit_date_pipeline(
        cls,
        target_date: str,
        manual_fixtures: list = None,
        fd_matches: list = None,
        external_unauthorized_fixtures: list = None,
        frontend_delivered: list = None,
    ) -> dict:
        """
        Ejecuta y audita el flujo completo del calendario para una fecha objetivo (America/Lima),
        registrando los 10 puntos de diagnóstico obligatorio y el conteo exacto después de cada etapa:
          1. Fuentes de calendario utilizadas y prioridad en conflicto
          2. ID único, UTC, America/Lima, competición y fecha en ALL_FIXTURES_POOL por partido
          3. Partidos eliminados por conflicto de fecha verificada o deduplicación
          4. Partidos descartados por filtro de fecha o competición deshabilitada
          5. Estado de cachés de calendario
        """
        t_date = str(target_date or get_current_operational_date())[:10]
        pool_base = manual_fixtures if manual_fixtures is not None else (globals().get("ALL_FIXTURES_POOL") or [])

        if manual_fixtures is not None:
            man_list = [dict(x) for x in manual_fixtures]
        else:
            man_list = [
                dict(x) for x in pool_base
                if resolve_match_local_date(x)[1] == t_date
            ]

        fd_converted = []
        verified_fd_by_pair = {}
        for m in (fd_matches or []):
            if "homeTeam" in m or "utcDate" in m:
                conv = cls.convert_fd_match_to_fixture(m, m.get("codigo_liga") or (m.get("competition") or {}).get("code") or "BSA")
            else:
                conv = dict(m)
                conv.setdefault("origen_fuente", "football-data.org")
            f_p, f_l, f_pe_iso = resolve_match_datetime_lima(conv)
            conv["fecha_programada"] = f_p
            conv["fecha_local_partido"] = f_l
            conv["fecha"] = f_l
            conv["fecha_hora_america_lima"] = f_pe_iso
            pair_k = f"{canonical_team_name(conv.get('local', ''))}|{canonical_team_name(conv.get('visitante', ''))}"
            if f_l:
                verified_fd_by_pair.setdefault(pair_k, []).append(f_l)
            fd_converted.append(conv)

        descartados = []
        eliminados_combinacion_dedup = []
        descartados_filtro_fecha = []

        for ext_f in (external_unauthorized_fixtures or []):
            rec = {
                "id_partido": ext_f.get("id_partido"),
                "local": ext_f.get("local"),
                "visitante": ext_f.get("visitante"),
                "fecha": ext_f.get("fecha"),
                "codigo_liga": ext_f.get("codigo_liga"),
                "motivo": f"fuente_no_autorizada_para_calendario:{ext_f.get('proveedor', 'externo')}",
            }
            descartados.append(rec)
            eliminados_combinacion_dedup.append(rec)

        # Etapa 1: Combinar poniendo primero la fuente oficial verificada (football-data.org)
        combinados_raw = []
        for x in fd_converted:
            combinados_raw.append(dict(x))
        for x in man_list:
            x_c = dict(x)
            x_c.setdefault("origen_fuente", "calendario_manual")
            combinados_raw.append(x_c)

        # Etapa 2: Validar fecha contra fuente oficial y deduplicar por fecha_local|local_norm|visitante_norm
        deduplicados = []
        seen_keys = {}
        for fix in combinados_raw:
            loc = str(fix.get("local") or "").strip()
            vis = str(fix.get("visitante") or "").strip()
            if not loc or not vis:
                rec = {
                    "id_partido": fix.get("id_partido"),
                    "local": loc,
                    "visitante": vis,
                    "fecha": str(fix.get("fecha") or ""),
                    "codigo_liga": fix.get("codigo_liga"),
                    "motivo": "equipos_incompletos",
                }
                descartados.append(rec)
                eliminados_combinacion_dedup.append(rec)
                continue
            f_prog, f_loc, f_pe_iso = resolve_match_datetime_lima(fix)
            fix["fecha_programada"] = f_prog
            fix["fecha_local_partido"] = f_loc
            fix["fecha"] = f_loc
            fix["fecha_hora_america_lima"] = f_pe_iso

            pair_k = f"{canonical_team_name(loc)}|{canonical_team_name(vis)}"
            src = str(fix.get("origen_fuente") or "calendario_manual")
            # Rechazar partido del calendario estático/manual cuya fecha contradice la fuente oficial verificada
            if src != "football-data.org" and pair_k in verified_fd_by_pair:
                v_dates = verified_fd_by_pair[pair_k]
                if f_loc not in v_dates and any(_dates_within_days(f_loc, vd, 14) for vd in v_dates):
                    rec = {
                        "id_partido": fix.get("id_partido"),
                        "local": loc,
                        "visitante": vis,
                        "fecha": f_loc,
                        "fecha_oficial_verificada": v_dates[0],
                        "codigo_liga": fix.get("codigo_liga"),
                        "motivo": f"fecha_no_coincide_con_fuente_verificada:{f_loc}!={v_dates[0]}",
                    }
                    descartados.append(rec)
                    eliminados_combinacion_dedup.append(rec)
                    continue

            comp_f = normalize_competition_code(fix.get("codigo_liga", ""), fix.get("liga", ""))
            fix["codigo_liga"] = comp_f
            ckey = cls.canonical_fixture_key(loc, vis, f_loc, competition_code=comp_f)
            if ckey in seen_keys:
                rec = {
                    "id_partido": fix.get("id_partido"),
                    "local": loc,
                    "visitante": vis,
                    "fecha": f_loc,
                    "codigo_liga": fix.get("codigo_liga"),
                    "motivo": f"duplicado_exacto_con:{seen_keys[ckey]}",
                }
                descartados.append(rec)
                eliminados_combinacion_dedup.append(rec)
                continue
            seen_keys[ckey] = fix.get("id_partido") or ckey
            deduplicados.append(fix)

        # Etapa 3: Filtrar por fecha local America/Lima y competiciones activas
        filtrados = []
        for fix in deduplicados:
            cod = str(fix.get("codigo_liga") or "OFL").upper()
            liga_n = normalizar_nombre_liga(fix.get("liga") or cod)
            fix["liga"] = liga_n
            f_loc = fix.get("fecha_local_partido") or fix.get("fecha")
            if not is_competition_enabled(cod, liga_n):
                rec = {
                    "id_partido": fix.get("id_partido"),
                    "local": fix.get("local"),
                    "visitante": fix.get("visitante"),
                    "fecha": f_loc,
                    "codigo_liga": cod,
                    "motivo": "competicion_deshabilitada",
                }
                descartados.append(rec)
                descartados_filtro_fecha.append(rec)
                continue
            if f_loc != t_date:
                rec = {
                    "id_partido": fix.get("id_partido"),
                    "local": fix.get("local"),
                    "visitante": fix.get("visitante"),
                    "fecha": f_loc,
                    "codigo_liga": cod,
                    "motivo": f"fuera_de_fecha_objetivo:{f_loc}!={t_date}",
                }
                descartados.append(rec)
                descartados_filtro_fecha.append(rec)
                continue
            filtrados.append(fix)

        enviados_frontend = list(frontend_delivered) if frontend_delivered is not None else list(filtrados)
        partidos_oficiales_count = len(filtrados)

        # Indexar fechas almacenadas actualmente en ALL_FIXTURES_POOL para trazabilidad completa
        pool_now = globals().get("ALL_FIXTURES_POOL") or []
        pool_date_by_id = {f.get("id_partido"): resolve_match_local_date(f)[1] for f in pool_now if f.get("id_partido")}

        report = {
            "fecha": t_date,
            "zona_horaria": "America/Lima",
            "fuentes_utilizadas": list(CALENDAR_SOURCE_PRIORITY),
            "prioridad_en_conflicto": "football-data.org > calendario_manual_tuplas > calendario_maestro_embebido",
            "total_por_fuente": {
                "calendario_manual": len(man_list),
                "football_data_org": len(fd_converted),
                "fuentes_externas_rechazadas": len(external_unauthorized_fixtures or []),
            },
            "partidos_oficiales": partidos_oficiales_count,
            "partidos_combinados": len(combinados_raw),
            "partidos_deduplicados": len(deduplicados),
            "partidos_filtrados": len(filtrados),
            "partidos_enviados_al_frontend": len(enviados_frontend),
            "partidos_descartados": descartados,
            "partidos_eliminados_combinacion_dedup": eliminados_combinacion_dedup,
            "partidos_descartados_filtro_fecha": descartados_filtro_fecha,
            "estado_caches_calendario": {
                "cartelera_memo_entries": len(globals().get("_CARTELERA_MEMO_CACHE") or {}),
                "fixtures_by_date_keys": len(globals().get("_FIXTURES_BY_DATE_INDEX") or {}),
                "synced_fd_fixtures": len(globals().get("_SYNCED_EXTERNAL_FD_FIXTURES") or []),
                "all_fixtures_pool_total": len(pool_now),
            },
            "competiciones_partidos": [
                {
                    "id_partido": f.get("id_partido"),
                    "partido": f"{f.get('local')} vs {f.get('visitante')}",
                    "local": f.get("local"),
                    "visitante": f.get("visitante"),
                    "competicion": f.get("liga"),
                    "codigo_liga": f.get("codigo_liga"),
                    "fecha_hora_utc": f.get("fecha_utc") or f.get("fecha_programada"),
                    "fecha_hora_america_lima": f.get("fecha_hora_america_lima"),
                    "fecha_programada": f.get("fecha_programada"),
                    "fecha_local_partido": f.get("fecha_local_partido"),
                    "fecha_en_all_fixtures_pool": pool_date_by_id.get(f.get("id_partido"), f.get("fecha_local_partido")),
                    "origen_fuente": f.get("origen_fuente", "calendario_manual"),
                }
                for f in filtrados
            ],
        }
        logger.info(
            "[CalendarPipelineAudit:%s] oficiales=%d combinados=%d deduplicados=%d filtrados=%d frontend=%d descartados=%d",
            t_date,
            report["partidos_oficiales"],
            report["partidos_combinados"],
            report["partidos_deduplicados"],
            report["partidos_filtrados"],
            report["partidos_enviados_al_frontend"],
            len(descartados),
        )
        return report

    @classmethod
    def audit_consecutive_dates(cls, dates: list, expected_by_date: dict = None, fd_by_date: dict = None) -> dict:
        """
        Audita automáticamente fechas consecutivas y múltiples competiciones:
        compara total por fuente, total combinado, total mostrado, partidos faltantes,
        partidos extra y verifica cero desplazamientos de fecha.
        """
        results = {}
        expected_map = expected_by_date or {}
        fd_map = fd_by_date or {}
        for d in dates:
            d_str = str(d)[:10]
            aud = cls.audit_date_pipeline(d_str, fd_matches=fd_map.get(d_str))
            shown_pairs = {
                f"{canonical_team_name(p['local'])}|{canonical_team_name(p['visitante'])}"
                for p in aud["competiciones_partidos"]
            }
            desplazamientos = [
                p for p in aud["competiciones_partidos"]
                if p.get("fecha_local_partido") != d_str
            ]
            faltantes = []
            extras = []
            if d_str in expected_map:
                exp_pairs = {
                    f"{canonical_team_name(loc)}|{canonical_team_name(vis)}"
                    for (loc, vis) in expected_map[d_str]
                }
                faltantes = sorted(list(exp_pairs - shown_pairs))
                extras = sorted(list(shown_pairs - exp_pairs))
            results[d_str] = {
                "total_por_fuente": aud["total_por_fuente"],
                "total_combinado": aud["partidos_combinados"],
                "total_mostrado": aud["partidos_enviados_al_frontend"],
                "competiciones": sorted(list({p["codigo_liga"] for p in aud["competiciones_partidos"]})),
                "partidos_faltantes": faltantes,
                "partidos_extra": extras,
                "desplazamientos_fecha": desplazamientos,
                "ok": (len(faltantes) == 0 and len(extras) == 0 and len(desplazamientos) == 0),
            }
        return results




