_NORM_EQUIPO_CACHE = {}

def _norm_equipo(nombre):
    if not nombre:
        return ""
    key = str(nombre)
    cached = _NORM_EQUIPO_CACHE.get(key)
    if cached is not None:
        return cached
    res = canonical_team_name(key)
    _NORM_EQUIPO_CACHE[key] = res
    return res

