def _build_team_initials(team_name: str) -> str:
    clean = str(team_name or "Club").strip()
    if not clean:
        return "CL"
    # Eliminar conectores cortos para obtener iniciales limpias (ej. Atlético de Madrid -> AM)
    tokens = [
        t for t in re.split(r"[\s\-]+", clean)
        if t and not t.isdigit() and t.lower() not in ("de", "del", "la", "el", "los", "las", "fc", "cf", "sc", "ac", "as", "cd", "ud", "rc", "rcd")
    ]
    if not tokens:
        tokens = [t for t in re.split(r"[\s\-]+", clean) if t]
    if len(tokens) >= 2:
        return (tokens[0][0] + tokens[-1][0]).upper()
    word = re.sub(r"[^A-Za-z0-9]", "", tokens[0]) if tokens else "CL"
    return (word[:2] if len(word) >= 2 else (word + "X")[:2]).upper()


def _ensure_team_logos_loaded():
    global _TEAM_LOGOS_DISK_LOADED
    if _TEAM_LOGOS_DISK_LOADED:
        return
    with _TEAM_LOGOS_LOCK:
        if _TEAM_LOGOS_DISK_LOADED:
            return
        now_iso = datetime.now(timezone.utc).isoformat()
        # 1. Cargar semilla persistente local
        for t_key, url in _PERSISTENT_LOCAL_CREST_SEED.items():
            norm_k = _norm_equipo(t_key) or t_key
            if norm_k not in team_logos:
                team_logos[norm_k] = {
                    "team_name": t_key.title(),
                    "logo_url": url,
                    "source": "cache_local",
                    "updated_at": now_iso,
                }
        # 2. Cargar caché persistente en disco si existe
        try:
            if os.path.exists(TEAM_LOGOS_CACHE_FILE):
                with open(TEAM_LOGOS_CACHE_FILE, "r", encoding="utf-8") as f:
                    disk_data = json.load(f)
                if isinstance(disk_data, dict):
                    for k, rec in disk_data.items():
                        if not isinstance(rec, dict):
                            continue
                        existing = team_logos.get(k)
                        ex_prio = _LOGO_SOURCE_PRIORITY.get((existing or {}).get("source", ""), 0)
                        new_prio = _LOGO_SOURCE_PRIORITY.get(rec.get("source", ""), 0)
                        if not existing or new_prio >= ex_prio:
                            team_logos[k] = {
                                "team_name": str(rec.get("team_name") or k),
                                "logo_url": rec.get("logo_url"),
                                "source": str(rec.get("source") or "cache_local"),
                                "updated_at": str(rec.get("updated_at") or now_iso),
                            }
        except Exception as e:
            logger.debug("No se pudo leer cache local de logos: %s", e)
        _TEAM_LOGOS_DISK_LOADED = True


def _persist_team_logos_to_disk():
    try:
        with open(TEAM_LOGOS_CACHE_FILE, "w", encoding="utf-8") as f:
            json.dump(team_logos, f, ensure_ascii=False)
    except Exception as e:
        logger.debug("No se pudo guardar cache local de logos: %s", e)


def register_team_logo(team_name, logo_url, source="football-data.org", team_id=None, competition_code=None, persist=False):
    """
    Registra el escudo de un equipo respetando estrictamente la prioridad de fuentes:
    1) football-data.org
    2) highlightly
    3) cache_local
    4) fallback_initials
    """
    _ensure_team_logos_loaded()
    if not team_name or not str(team_name).strip():
        return None
    clean_url = str(logo_url or "").strip() or None
    if clean_url and not (clean_url.startswith("http://") or clean_url.startswith("https://")):
        clean_url = None
    team_key = _norm_equipo(team_name)
    if not team_key:
        return None
    src_norm = str(source or "cache_local").strip().lower()
    if src_norm not in _LOGO_SOURCE_PRIORITY:
        src_norm = "cache_local"
    if not clean_url:
        src_norm = "fallback_initials"

    now_iso = datetime.now(timezone.utc).isoformat()
    with _TEAM_LOGOS_LOCK:
        existing = team_logos.get(team_key)
        if existing:
            old_prio = _LOGO_SOURCE_PRIORITY.get(existing.get("source", ""), 0)
            new_prio = _LOGO_SOURCE_PRIORITY.get(src_norm, 0)
            # No sobrescribir una fuente de mayor prioridad con una menor o sin URL
            if existing.get("logo_url") and (not clean_url or new_prio < old_prio):
                return dict(existing)

        record = {
            "team_name": str(team_name).strip(),
            "logo_url": clean_url,
            "source": src_norm,
            "updated_at": now_iso,
        }
        team_logos[team_key] = record
        if persist and clean_url:
            _persist_team_logos_to_disk()
        return dict(record)


def get_team_logo(team_name, team_id=None, competition_code=None) -> dict:
    """
    Función única y canónica de resolución de escudos para todos los equipos y las 10 competiciones.
    No realiza ninguna petición HTTP externa por renderizado ni bloquea el análisis si falta un logo.
    Orden de fuentes:
      1. crest/logo recibido desde football-data.org
      2. logo recibido desde Highlightly
      3. caché local persistente por equipo
      4. fallback visual con iniciales si no existe
    """
    _ensure_team_logos_loaded()
    raw_name = str(team_name or "Equipo").strip() or "Equipo"
    team_key = _norm_equipo(raw_name) or raw_name.lower()
    initials = _build_team_initials(raw_name)

    with _TEAM_LOGOS_LOCK:
        cached = team_logos.get(team_key)
        if cached and cached.get("logo_url"):
            res = dict(cached)
            res["fallback_initials"] = initials
            res["team_key"] = team_key
            if competition_code:
                res["competition_code"] = competition_code
            return res

        # Verificar semilla local en caso de que team_logos haya sido limpiado en tests
        seed_url = _PERSISTENT_LOCAL_CREST_SEED.get(team_key)
        if seed_url:
            now_iso = datetime.now(timezone.utc).isoformat()
            rec = {
                "team_name": raw_name,
                "logo_url": seed_url,
                "source": "cache_local",
                "updated_at": now_iso,
            }
            team_logos[team_key] = rec
            out = dict(rec)
            out["fallback_initials"] = initials
            out["team_key"] = team_key
            if competition_code:
                out["competition_code"] = competition_code
            return out

        # Fallback visual con iniciales si no existe URL en ninguna fuente
        now_iso = datetime.now(timezone.utc).isoformat()
        fallback_rec = {
            "team_name": raw_name,
            "logo_url": None,
            "source": "fallback_initials",
            "updated_at": now_iso,
        }
        team_logos[team_key] = fallback_rec
        out = dict(fallback_rec)
        out["fallback_initials"] = initials
        out["team_key"] = team_key
        if competition_code:
            out["competition_code"] = competition_code
        return out


def preload_active_team_logos() -> int:
    """Precarga en team_logos todos los equipos de las competiciones activas sin llamadas HTTP externas."""
    _ensure_team_logos_loaded()
    pool = globals().get("ALL_FIXTURES_POOL") or []
    count = 0
    for fix in pool:
        if not is_competition_enabled(fix.get("codigo_liga", ""), fix.get("liga", "")):
            continue
        for t_field in ("local", "visitante"):
            t_name = str(fix.get(t_field) or "").strip()
            if t_name:
                get_team_logo(t_name, competition_code=fix.get("codigo_liga"))
                count += 1
    return count

def _attach_match_logos(item_dict: dict, local_name: str = None, away_name: str = None, competition_code: str = None) -> dict:
    """Añade logo_local, logo_visitante, fallback_logo_local y fallback_logo_visitante a cualquier respuesta de partido."""
    if not isinstance(item_dict, dict):
        return item_dict
    loc = (local_name if local_name is not None else item_dict.get("local")) or "Local"
    vis = (away_name if away_name is not None else item_dict.get("visitante")) or "Visitante"
    comp = competition_code or item_dict.get("codigo_liga")
    info_loc = get_team_logo(loc, competition_code=comp)
    info_vis = get_team_logo(vis, competition_code=comp)
    item_dict["logo_local"] = info_loc.get("logo_url")
    item_dict["logo_visitante"] = info_vis.get("logo_url")
    item_dict["fallback_logo_local"] = info_loc.get("fallback_initials") or _build_team_initials(loc)
    item_dict["fallback_logo_visitante"] = info_vis.get("fallback_initials") or _build_team_initials(vis)
    item_dict["logo_source_local"] = info_loc.get("source")
    item_dict["logo_source_visitante"] = info_vis.get("source")
    return item_dict

def _fecha_csv(texto):
    for fmt in ("%d/%m/%Y", "%d/%m/%y", "%Y-%m-%d"):
        try:
            return datetime.strptime(texto.strip(), fmt).date()
        except (ValueError, AttributeError):
            pass
    return None

def _elo_partido(rh, ra, gh, ga, k=20.0, ventaja=60.0):
    eh = 1.0 / (1.0 + 10.0 ** ((ra - (rh + ventaja)) / 400.0))
    ea = 1.0 - eh
    sh = 1.0 if gh > ga else (0.5 if gh == ga else 0.0)
    sa = 1.0 - sh
    return rh + k * (sh - eh), ra + k * (sa - ea)

def _descargar_csv(temporada, codigo):
    url = f"https://www.football-data.co.uk/mmz4281/{temporada}/{codigo}.csv"
    r = requests.get(url, timeout=12, headers={"User-Agent": "PredicXionIA/2.0"})
    if r.status_code != 200:
        raise RuntimeError(f"HTTP {r.status_code} desde {url}")
    return r.text

def actualizar_ratings_reales(descargar=None):
    """
    Sincroniza partidos oficiales finalizados desde football-data.org (única fuente externa),
    calculando ataque, defensa, Elo, muestra real y el índice cronológico VERIFIED_TEAM_HISTORY.
    Si un dato (córners/tarjetas/árbitro) no es provisto por football-data.org, queda en None.
    """
    partidos, ok, fallos = [], [], []
    partidos_descargados = 0
    partidos_descartados = 0
    errores_api = []
    actualizado_ts = datetime.now(timezone.utc).isoformat()

    for cod_interno, fd_code in FootballDataOrgClient.COMPETITION_CODE_MAP.items():
        liga_nombre = FootballDataOrgClient.COMPETITION_NAMES.get(cod_interno, cod_interno)
        if not is_competition_enabled(cod_interno, liga_nombre):
            continue
        antes = len(partidos)
        try:
            if descargar is not None:
                # Permite inyectar función en pruebas unitarias sin red
                matches_raw = descargar(cod_interno, fd_code)
                res_ok = isinstance(matches_raw, list)
                err_msg = None if res_ok else "Error en proveedor de prueba"
            else:
                res = FootballDataOrgClient.fetch_json(
                    f"/competitions/{fd_code}/matches",
                    competition_code=cod_interno,
                    params={"status": "FINISHED"},
                    ttl_seconds=900,
                    timeout_sec=12
                )
                res_ok = res.get("ok", False)
                err_msg = res.get("error")
                matches_raw = (res.get("data") or {}).get("matches", []) if res_ok else []

            if not res_ok:
                fallos.append(f"{liga_nombre}: {err_msg or 'sin respuesta'}")
                errores_api.append({"competicion": cod_interno, "error": err_msg or "sin respuesta"})
                continue

            partidos_descargados += len(matches_raw or [])
            for m in matches_raw:
                if str(m.get("status") or "").upper() != "FINISHED":
                    continue
                utc_dt = str(m.get("utcDate") or "")
                f_iso = utc_dt[:10]
                if not f_iso:
                    continue
                h_team_obj = m.get("homeTeam") or {}
                a_team_obj = m.get("awayTeam") or {}
                h_name = (h_team_obj.get("name") or "").strip()
                a_name = (a_team_obj.get("name") or "").strip()
                if not h_name or not a_name:
                    continue
                if h_team_obj.get("crest") or h_team_obj.get("logo"):
                    register_team_logo(h_name, h_team_obj.get("crest") or h_team_obj.get("logo"), source="football-data.org", team_id=h_team_obj.get("id"), competition_code=cod_interno)
                if a_team_obj.get("crest") or a_team_obj.get("logo"):
                    register_team_logo(a_name, a_team_obj.get("crest") or a_team_obj.get("logo"), source="football-data.org", team_id=a_team_obj.get("id"), competition_code=cod_interno)
                score_ft = ((m.get("score") or {}).get("fullTime") or {})
                gh, ga = score_ft.get("home"), score_ft.get("away")
                if gh is None or ga is None:
                    continue
                gh, ga = int(gh), int(ga)

                stage = str(m.get("stage") or "").upper()
                if "FRIENDLY" in stage:
                    continue

                ent_type = "seleccion" if cod_interno == "UNL" else "club"
                partidos.append({
                    "f": datetime.strptime(f_iso, "%Y-%m-%d").date(),
                    "f_iso": f_iso,
                    "h": h_name, "a": a_name,
                    "gh": gh, "ga": ga,
                    "liga": liga_nombre, "cod": cod_interno,
                    "tipo_entidad": ent_type,
                    "referees": m.get("referees") or [],
                })
                if "_VERIFIED_RESULTS_CACHE" in globals():
                    _VERIFIED_RESULTS_CACHE[(f_iso, _norm_equipo(h_name), _norm_equipo(a_name))] = {
                        "finished": True, "score_home": gh, "score_away": ga,
                        "corners_total": None, "cards_total": None,
                        "yellow_cards": None, "red_cards": None,
                        "competicion": liga_nombre, "codigo_liga": cod_interno,
                        "tipo_entidad": ent_type, "es_oficial": True, "simulado": False,
                        "source": "football-data.org"
                    }

            if len(partidos) > antes:
                ok.append(f"{liga_nombre} ({len(partidos) - antes})")
            else:
                ok.append(f"{liga_nombre} (0 finalizados)")
        except Exception as exc:
            fallos.append(f"{liga_nombre}: {type(exc).__name__}")

    with FootballDataOrgClient._LOCK:
        FootballDataOrgClient._STATUS["ultima_sincronizacion"] = actualizado_ts

    # Si football-data.org no devolvió partidos (ej. sin clave o límite 429), respaldar desde _VERIFIED_RESULTS_CACHE
    if not partidos and "_VERIFIED_RESULTS_CACHE" in globals() and _VERIFIED_RESULTS_CACHE:
        for (f_c, h_c, a_c), entry in list(_VERIFIED_RESULTS_CACHE.items()):
            if entry.get("simulado") or not entry.get("finished"):
                continue
            if entry.get("score_home") is None or entry.get("score_away") is None:
                continue
            try:
                f_iso_c = str(f_c)[:10]
                partidos.append({
                    "f": datetime.strptime(f_iso_c, "%Y-%m-%d").date(),
                    "f_iso": f_iso_c,
                    "h": h_c, "a": a_c,
                    "gh": int(entry["score_home"]), "ga": int(entry["score_away"]),
                    "liga": entry.get("competicion") or "Competición Oficial",
                    "cod": entry.get("codigo_liga") or "OFL",
                    "tipo_entidad": entry.get("tipo_entidad") or "club",
                    "referees": [],
                })
            except Exception:
                partidos_descartados += 1

    if not partidos:
        causa_vacio = "FOOTBALL_API_KEY_NO_CONFIGURADA" if not FootballDataOrgClient._get_api_key() else (
            errores_api[0]["error"] if errores_api else "SIN_PARTIDOS_FINALIZADOS_DISPONIBLES"
        )
        logger.warning(
            "[RatingsSync] 0 partidos aceptados. descargados=%d descartados=%d causa=%s errores=%s",
            partidos_descargados, partidos_descartados, causa_vacio, errores_api[:5]
        )
        with _RATINGS_LOCK:
            RATINGS_ESTADO.update({
                "actualizado": actualizado_ts,
                "ultima_sincronizacion": actualizado_ts,
                "partidos_descargados": partidos_descargados,
                "partidos_aceptados": 0,
                "partidos_descartados": partidos_descartados,
                "equipos_procesados": 0,
                "causa_vacio": causa_vacio,
                "errores_api": errores_api[:10],
                "ligas_ok": ok, "ligas_fallidas": fallos,
                "temporadas": ["football-data.org-v4"],
            })
            return dict(RATINGS_ESTADO)

    partidos.sort(key=lambda p: p["f"])
    elo, agg = {}, {}
    nuevo_hist = {}
    seen_hist = set()

    for p in partidos:
        h_n, a_n = _norm_equipo(p["h"]), _norm_equipo(p["a"])
        rh, ra = elo.get(h_n, 1500.0), elo.get(a_n, 1500.0)
        elo[h_n], elo[a_n] = _elo_partido(rh, ra, p["gh"], p["ga"])

        for eq, gf, gc in ((h_n, p["gh"], p["ga"]), (a_n, p["ga"], p["gh"])):
            d = agg.setdefault(eq, {"n": 0, "gf": 0, "gc": 0})
            d["n"] += 1
            d["gf"] += gf
            d["gc"] += gc

        dedup_k = (p["f_iso"], h_n, a_n)
        if dedup_k in seen_hist:
            continue
        seen_hist.add(dedup_k)

        marcador_str = f"{p['gh']} - {p['ga']}"
        res_h = "V" if p["gh"] > p["ga"] else ("E" if p["gh"] == p["ga"] else "D")
        res_a = "V" if p["ga"] > p["gh"] else ("E" if p["ga"] == p["gh"] else "D")

        nuevo_hist.setdefault(h_n, []).append({
            "fecha": p["f_iso"], "competicion": p["liga"], "codigo_liga": p["cod"],
            "rival": p["a"], "condicion": "L", "gf": p["gh"], "gc": p["ga"],
            "marcador": marcador_str, "resultado": res_h,
            "corners": None, "tarjetas": None, "tiros": None, "tiros_puerta": None,
            "tipo_entidad": p["tipo_entidad"], "es_oficial": True, "simulado": False,
            "fuente": "football-data.org"
        })
        nuevo_hist.setdefault(a_n, []).append({
            "fecha": p["f_iso"], "competicion": p["liga"], "codigo_liga": p["cod"],
            "rival": p["h"], "condicion": "V", "gf": p["ga"], "gc": p["gh"],
            "marcador": marcador_str, "resultado": res_a,
            "corners": None, "tarjetas": None, "tiros": None, "tiros_puerta": None,
            "tipo_entidad": p["tipo_entidad"], "es_oficial": True, "simulado": False,
            "fuente": "football-data.org"
        })

    prom_gf = sum(p["gh"] + p["ga"] for p in partidos) / (2.0 * len(partidos)) if partidos else 1.35
    nuevos = {}
    for eq, d in agg.items():
        if d["n"] < 1:
            continue
        nuevos[eq] = {
            "ataque": round((d["gf"] / d["n"]) / max(0.5, prom_gf), 3),
            "defensa": round((d["gc"] / d["n"]) / max(0.5, prom_gf), 3),
            "gf_promedio": round(d["gf"] / d["n"], 3),
            "gc_promedio": round(d["gc"] / d["n"], 3),
            "elo": round(elo.get(eq, 1500.0), 1),
            "partidos": d["n"],
            "corners_promedio": None,
            "corners_muestra": 0,
            "tarjetas_promedio": None,
            "tarjetas_muestra": 0,
            "fuente": "football-data.org",
            "actualizado_en": actualizado_ts,
        }

    with _RATINGS_LOCK:
        RATINGS_REALES.clear()
        RATINGS_REALES.update(nuevos)
        VERIFIED_TEAM_HISTORY.clear()
        VERIFIED_TEAM_HISTORY.update(nuevo_hist)
        RATINGS_ESTADO.update({
            "actualizado": actualizado_ts,
            "equipos_con_datos": len(nuevos),
            "equipos_procesados": len(nuevos),
            "partidos_usados": len(partidos),
            "partidos_descargados": max(partidos_descargados, len(partidos)),
            "partidos_aceptados": len(partidos),
            "partidos_descartados": partidos_descartados,
            "ultima_sincronizacion": actualizado_ts,
            "causa_vacio": None,
            "errores_api": errores_api[:10],
            "ligas_ok": ok,
            "ligas_fallidas": fallos,
            "temporadas": ["football-data.org-v4"],
        })
    logger.info("Ratings reales sincronizados desde football-data.org: %d equipos, %d partidos.", len(nuevos), len(partidos))
    return dict(RATINGS_ESTADO)

def _ratings_para(nombre):
    with _RATINGS_LOCK:
        return RATINGS_REALES.get(_norm_equipo(nombre))

_FIXTURES_BY_DATE_INDEX = {}
_FIXTURES_DATES_SORTED = []
_FIXTURES_INDEX_SIG = None

def invalidate_calendar_caches(rebuild_pool: bool = False, extra_fd_fixtures: list = None):
    """Invalida todas las cachés de calendario y reconstruye los índices precalculados."""
    global ALL_FIXTURES_POOL, CLUB_INTEGRATED_FIXTURES, _FIXTURES_INDEX_SIG
    if rebuild_pool:
        ALL_FIXTURES_POOL = build_multimonth_calendar(extra_fd_fixtures=extra_fd_fixtures)
        CLUB_INTEGRATED_FIXTURES = ALL_FIXTURES_POOL
    if "_CARTELERA_MEMO_CACHE" in globals() and isinstance(_CARTELERA_MEMO_CACHE, dict):
        _CARTELERA_MEMO_CACHE.clear()
    if "_CARTELERA_MEMO_TS" in globals() and isinstance(_CARTELERA_MEMO_TS, dict):
        _CARTELERA_MEMO_TS.clear()
    _FIXTURES_INDEX_SIG = None
    ensure_fixtures_date_index(force=True)
    if "DailyAutomationPipeline" in globals():
        DailyAutomationPipeline.bump_data_version("CALENDAR_CACHE_INVALIDATED")
    return len(ALL_FIXTURES_POOL)

def ensure_fixtures_date_index(force: bool = False):
    """Pre-normaliza nombres de equipos y agrupa ALL_FIXTURES_POOL por fecha local oficial (America/Lima) excluyendo competiciones deshabilitadas."""
    global _FIXTURES_BY_DATE_INDEX, _FIXTURES_DATES_SORTED, _FIXTURES_INDEX_SIG
    pool = globals().get("ALL_FIXTURES_POOL") or []
    disabled_sig = tuple(sorted(get_disabled_competitions()))
    pool_hash = hash(tuple((f.get("id_partido"), f.get("fecha"), f.get("fecha_utc")) for f in pool))
    sig = (len(pool), id(pool), disabled_sig, pool_hash)
    if not force and _FIXTURES_INDEX_SIG == sig:
        return
    by_date = {}
    seen_global = set()
    for fix in pool:
        if not is_competition_enabled(fix.get("codigo_liga", ""), fix.get("liga", "")):
            continue
        f_prog, fecha_dia = resolve_match_local_date(fix)
        if not fecha_dia:
            continue
        fix["fecha_programada"] = f_prog
        fix["fecha_local_partido"] = fecha_dia
        loc = (fix.get("local") or "").strip()
        vis = (fix.get("visitante") or "").strip()
        if "_local_norm" not in fix:
            fix["_local_norm"] = _norm_equipo(loc)
        if "_visitante_norm" not in fix:
            fix["_visitante_norm"] = _norm_equipo(vis)
        if "_liga_norm" not in fix:
            fix["_liga_norm"] = normalizar_nombre_liga(fix.get("liga", "Otras Ligas"))
        comp_n = normalize_competition_code(fix.get("codigo_liga", ""), fix.get("liga", ""))
        fix["codigo_liga"] = comp_n
        m_key = CalendarSyncService.canonical_fixture_key(loc, vis, fecha_dia, competition_code=comp_n)
        id_p = fix.get("id_partido")
        if m_key in seen_global or (id_p and id_p in seen_global):
            continue
        seen_global.add(m_key)
        if id_p:
            seen_global.add(id_p)
        by_date.setdefault(fecha_dia, []).append(fix)
    _FIXTURES_BY_DATE_INDEX = by_date
    _FIXTURES_DATES_SORTED = sorted(by_date.keys())
    _FIXTURES_INDEX_SIG = sig

try:
    ensure_fixtures_date_index(force=True)
    SportsAnalyticsEngine.rebuild_verified_history_index(force=True)
    preload_active_team_logos()
except Exception:
    pass

def _arranque_ratings():
    time.sleep(5)
    try:
        CalendarSyncService.load_persisted_fd_calendar()
        CalendarSyncService.sync_live_calendar_from_football_data(days_back=7, days_ahead=35)
        ensure_fixtures_date_index(force=True)
        actualizar_ratings_reales()
        SportsAnalyticsEngine.rebuild_verified_history_index(force=True)
        MatchEnrichmentCache.enrich_calendar_worker(target_date=get_current_operational_date(), limit=15)
        now_pe = Top3RotationManager.now_peru()
        if now_pe.hour >= 22:
            Top3RotationManager.check_and_run_rotation(now_pe=now_pe, motivo="RECUPERACION_ARRANQUE_POST_22PE")
    except Exception as exc:
        logger.warning("No se pudieron cargar ratings de football-data.co.uk al arrancar: %s", exc)

if os.getenv("DISABLE_BACKGROUND_WORKERS", "false").lower() != "true":
    threading.Thread(target=_arranque_ratings, daemon=True).start()


def _plan_de_peticion() -> str:
    """Devuelve 'elite', 'pro' o 'free' según el token Bearer. Nunca lanza excepciones."""
    try:
        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            return "free"
        token = auth_header.split("Bearer ", 1)[1].strip()
        ensure_firebase_initialized()
        decoded = None
        if auth and firebase_admin and firebase_admin._apps:
            try:
                decoded = auth.verify_id_token(token, clock_skew_seconds=60)
            except Exception:
                pass

        if not decoded and token:
            try:
                parts = token.split(".")
                if len(parts) >= 2:
                    padding = '=' * (4 - len(parts[1]) % 4)
                    payload_b64 = parts[1] + padding
                    decoded = json.loads(base64.urlsafe_b64decode(payload_b64.encode('utf-8')).decode('utf-8'))
            except Exception:
                pass

        if not decoded:
            return "free"

        email = (decoded.get("email") or "").strip().lower()
        if email and email in OWNER_EMAILS:
            return "elite"

        uid = decoded.get("uid") or decoded.get("user_id") or decoded.get("sub")
        if uid and db:
            try:
                data = db.collection("usuarios").document(uid).get().to_dict() or {}
                plan_db = (data.get("plan") or "free").lower().strip()
                exp = data.get("suscripcion_expira")
                no_expirada = not exp or _as_utc(exp) > datetime.now(timezone.utc)
                es_activa = bool(data.get("suscripcion_activa") or data.get("esVip") or data.get("es_vip"))
                if (es_activa or plan_db in ("pro", "elite", "anual", "vip")) and no_expirada:
                    return "elite" if plan_db in ("elite", "anual") else "pro"
            except Exception:
                pass
    except Exception:
        pass
    return "free"


def _recortar_item_gratis(it: dict) -> None:
    """Oculta en el servidor el contenido VIP de una tarjeta de cartelera."""
    it["props_jugadores"] = []
    st = it.get("organizacion_stakazos") or {}
    st.pop("micromercado_oro", None)
    it["organizacion_stakazos"] = st
    pil = it.get("pilares_cuantitativos") or {}
    for k in ("pilar_6_compatibilidad_tactica", "pilar_7_micromercados_friccion"):
        pil.pop(k, None)
    it["pilares_cuantitativos"] = pil
    pp = it.get("pronostico_principal") or {}
    pp["justificacion"] = "Justificación disponible con Membresía VIP"
    it["pronostico_principal"] = pp
    it["consenso_dual_ia"] = None


def _ocultar_contenido_vip(path: str, data: dict) -> dict:
    if path == "/api/v1/top3/daily":
        for key in ("top3", "top5"):
            for it in data.get(key) or []:
                if not it.get("es_gratis_telegram") and int(it.get("rank", 0)) <= 2:
                    it.update({
                        "mercado": "🔒 Pick exclusivo VIP",
                        "probabilidad": "🔒",
                        "cuota_justa": None,
                        "justificacion": "Disponible con Membresía VIP",
                        "xg_local": None,
                        "xg_visita": None,
                        "bloqueado": True,
                    })
    elif path == "/obtener-pronostico":
        for bloque in ("destacados", "pronosticos_destacados"):
            for it in data.get(bloque) or []:
                _recortar_item_gratis(it)
        for bloque in ("todos", "todos_los_partidos"):
            for lista in (data.get(bloque) or {}).values():
                for it in lista or []:
                    _recortar_item_gratis(it)
    return data


