# ======================================================================================
# GENERADOR DE CAPTURA VISUAL (PNG) DEL TOP 3 LIQUIDADO Y AUTOMATIZACIÓN DE MANTENIMIENTO
# ======================================================================================
_ultimo_envio_resultados_top5 = set()
_auto_resultados_lock = threading.Lock()

def _ya_enviado_resultados_top5_fecha(target_date: str) -> bool:
    if target_date in _ultimo_envio_resultados_top5:
        return True
    res_file = f"/tmp/predicxion_last_tg_res_{target_date}.txt"
    try:
        if os.path.exists(res_file):
            _ultimo_envio_resultados_top5.add(target_date)
            return True
    except Exception:
        pass
    try:
        if "db" in globals() and db:
            doc = db.collection("telegram_auto_resultados").document(target_date).get()
            if doc.exists and (doc.to_dict() or {}).get("enviado"):
                _ultimo_envio_resultados_top5.add(target_date)
                return True
    except Exception:
        pass
    return False

def _marcar_enviado_resultados_top5_fecha(target_date: str, motivo: str = "AUTO_5_DE_5_FINALIZADOS"):
    _ultimo_envio_resultados_top5.add(target_date)
    res_file = f"/tmp/predicxion_last_tg_res_{target_date}.txt"
    try:
        with open(res_file, "w", encoding="utf-8") as f:
            f.write(target_date)
    except Exception:
        pass
    try:
        if "db" in globals() and db:
            db.collection("telegram_auto_resultados").document(target_date).set({
                "fecha": target_date,
                "enviado": True,
                "motivo": motivo,
                "timestamp": datetime.now(timezone.utc).isoformat()
            }, merge=True)
    except Exception:
        pass

def generar_imagen_resultados_top5(fecha_str: str, picks_liquidados: list) -> bytes:
    """
    Renderiza en memoria una imagen PNG de alta resolución (1280x1220) con la MISMA interfaz
    del apartado Top 3 de la aplicación web:
    - Columna 1: #Rank + Liga + Escudos Circulares con Iniciales + Equipos.
    - Columna 2 (Caja Central): Categoría + Jugada Recomendada + % Confidence + Barra Neón + Explicación concisa (SIN CUOTAS).
    - Columna 3 (Caja Derecha): Sello WIN / LOSS + Marcador Final grande + Conteo real completo sin recortes.
    """
    try:
        import io
        from PIL import Image, ImageDraw, ImageFont

        W, H = 1280, 1220
        img = Image.new("RGB", (W, H), (8, 18, 16))
        draw = ImageDraw.Draw(img)

        def _load_font(bold=False, size=20, mono=False):
            candidates = []
            if mono:
                candidates = [
                    "/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf",
                    "/usr/share/fonts/truetype/liberation/LiberationMono-Bold.ttf",
                ]
            elif bold:
                candidates = [
                    "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf",
                    "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
                    "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
                ]
            else:
                candidates = [
                    "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
                    "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
                    "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
                ]
            for c in candidates:
                if os.path.exists(c):
                    try:
                        return ImageFont.truetype(c, size)
                    except Exception:
                        pass
            return ImageFont.load_default()

        f_title = _load_font(bold=True, size=30)
        f_sub = _load_font(bold=False, size=18)
        f_badge = _load_font(bold=True, size=18, mono=True)
        f_rank = _load_font(bold=True, size=24)
        f_liga = _load_font(bold=True, size=14)
        f_shield = _load_font(bold=True, size=15)
        f_team = _load_font(bold=True, size=16)
        f_cat = _load_font(bold=True, size=13, mono=True)
        f_mkt = _load_font(bold=True, size=22)
        f_conf = _load_font(bold=True, size=26)
        f_just = _load_font(bold=False, size=14)
        f_win = _load_font(bold=True, size=18)
        f_score = _load_font(bold=True, size=32)
        f_stat = _load_font(bold=True, size=15)

        draw.rounded_rectangle([20, 20, W - 20, H - 20], radius=28, fill=(8, 18, 16), outline=(16, 185, 129), width=2)

        partes_f = fecha_str.split("-")
        fecha_bonita = f"{partes_f[2]}.{partes_f[1]}.{partes_f[0]}" if len(partes_f) == 3 else fecha_str
        ganadas = sum(1 for p in picks_liquidados if p.get("estado") == "GANADA")
        perdidas = sum(1 for p in picks_liquidados if p.get("estado") == "PERDIDA")
        total_p = max(1, ganadas + perdidas)
        pct_acierto = round((ganadas / total_p) * 100)

        draw.text((52, 42), "Top 3 Pronósticos del Día • Balance de Jornada", font=_load_font(bold=True, size=26), fill=(255, 255, 255))
        draw.text((52, 84), f"Jornada: {fecha_bonita}  •  Resultados Oficiales Verificados", font=f_sub, fill=(148, 163, 184))

        badge_rect = [W - 435, 42, W - 46, 108]
        draw.rounded_rectangle(badge_rect, radius=16, fill=(11, 43, 32), outline=(0, 230, 118), width=2)
        draw.text((W - 415, 64), f"{pct_acierto}% EFECTIVIDAD ({ganadas} WIN / {perdidas} LOSS)", font=f_badge, fill=(0, 230, 118))

        draw.line([(48, 134), (W - 48, 134)], fill=(20, 60, 48), width=2)

        y_top = 154
        card_h = 184
        gap = 16

        for idx, p in enumerate(picks_liquidados[:5], 1):
            es_win = (p.get("estado") == "GANADA")
            b_color = (0, 230, 118) if es_win else (244, 63, 94)
            bg_outer = (7, 26, 20) if es_win else (26, 13, 18)
            draw.rounded_rectangle([46, y_top, W - 46, y_top + card_h], radius=22, fill=bg_outer, outline=b_color, width=2)

            # 1. Badge #Rank (Izquierda)
            rank_bg = (15, 41, 30) if es_win else (42, 18, 25)
            draw.rounded_rectangle([64, y_top + 48, 122, y_top + 136], radius=14, fill=rank_bg, outline=b_color, width=1)
            draw.text((78, y_top + 78), f"#{idx}", font=f_rank, fill=b_color)

            # 2. Bloque Escudos y Equipos (Columna 1 estilo app web)
            partido_str = str(p.get("partido") or f"{p.get('local', 'Local')} vs {p.get('visitante', 'Visita')}")
            if " vs " in partido_str:
                loc_n, vis_n = [x.strip() for x in partido_str.split(" vs ", 1)]
            else:
                loc_n, vis_n = partido_str, "Rival"

            liga_str = str(p.get("liga") or "Fútbol Oficial")[:30]
            draw.text((142, y_top + 22), liga_str, font=f_liga, fill=(148, 163, 184))

            # Escudo Local
            ini_l = (loc_n.split()[0][0] + (loc_n.split()[-1][0] if len(loc_n.split()) > 1 else loc_n[1:2])).upper()
            draw.ellipse([168, y_top + 52, 214, y_top + 98], fill=(16, 95, 72), outline=(52, 211, 153), width=2)
            draw.text((180, y_top + 66), ini_l[:2], font=f_shield, fill=(255, 255, 255))
            loc_short = loc_n[:14] + ("…" if len(loc_n) > 14 else "")
            draw.text((142, y_top + 106), loc_short, font=f_team, fill=(255, 255, 255))

            draw.text((254, y_top + 68), "vs", font=f_liga, fill=(100, 116, 139))

            # Escudo Visitante
            ini_v = (vis_n.split()[0][0] + (vis_n.split()[-1][0] if len(vis_n.split()) > 1 else vis_n[1:2])).upper()
            draw.ellipse([306, y_top + 52, 352, y_top + 98], fill=(30, 64, 135), outline=(96, 165, 250), width=2)
            draw.text((318, y_top + 66), ini_v[:2], font=f_shield, fill=(255, 255, 255))
            vis_short = vis_n[:14] + ("…" if len(vis_n) > 14 else "")
            draw.text((284, y_top + 106), vis_short, font=f_team, fill=(255, 255, 255))

            draw.text((195, y_top + 142), f"{fecha_bonita}", font=f_cat, fill=(148, 163, 184))

            # 3. Columna 2: Caja Central de Señal Estadística (sin cuotas)
            cx1, cy1, cx2, cy2 = 430, y_top + 16, W - 330, y_top + card_h - 16
            draw.rounded_rectangle([cx1, cy1, cx2, cy2], radius=16, fill=(11, 26, 22), outline=(16, 95, 70), width=1)

            sel_txt = str(p.get("seleccion") or p.get("mercado") or "Selección Oficial")
            cat_code, _ = _clasificar_categoria_mercado(sel_txt)
            cat_labels = {
                "CARDS": "CARDS • TARJETAS",
                "CORNERS": "CORNERS • CÓRNERS",
                "GOALS": "GOALS • GOLES",
                "BTTS": "BTTS • AMBOS ANOTAN",
                "WINNER": "WINNER • DOBLE OPORTUNIDAD / GANADOR"
            }
            cat_lbl = cat_labels.get(cat_code, "GOALS • GOLES")
            draw.text((cx1 + 18, cy1 + 14), cat_lbl, font=f_cat, fill=(52, 211, 153))

            prob_str = str(p.get("probabilidad") or "84%").replace("%", "").strip()
            try:
                conf_num = int(float(prob_str))
            except Exception:
                conf_num = 84
            draw.text((cx2 - 78, cy1 + 12), f"{conf_num}%", font=f_conf, fill=(0, 230, 118))

            f_mkt_use = _load_font(bold=True, size=18) if len(sel_txt) > 34 else f_mkt
            sel_display = sel_txt[:52] + ("…" if len(sel_txt) > 52 else "")
            draw.text((cx1 + 18, cy1 + 40), sel_display, font=f_mkt_use, fill=(255, 255, 255))

            # Barra de progreso neón
            bar_x1, bar_y1, bar_x2, bar_y2 = cx1 + 18, cy1 + 76, cx2 - 18, cy1 + 86
            draw.rounded_rectangle([bar_x1, bar_y1, bar_x2, bar_y2], radius=5, fill=(6, 40, 30))
            fill_w = int((bar_x2 - bar_x1) * min(0.96, max(0.55, conf_num / 100.0)))
            draw.rounded_rectangle([bar_x1, bar_y1, bar_x1 + fill_w, bar_y2], radius=5, fill=(0, 230, 118))

            just_raw = str(p.get("justificacion") or p.get("stat_projection_label") or "Análisis estadístico basado en promedios reales de los últimos 5 partidos.")
            if len(just_raw) > 68:
                just_line1 = just_raw[:68].rsplit(" ", 1)[0]
                just_line2 = just_raw[len(just_line1):].strip()[:68]
                if len(just_raw[len(just_line1):].strip()) > 68:
                    just_line2 = just_line2[:65] + "…"
                draw.text((cx1 + 18, cy1 + 98), just_line1, font=f_just, fill=(203, 213, 225))
                draw.text((cx1 + 18, cy1 + 118), just_line2, font=f_just, fill=(148, 163, 184))
            else:
                draw.text((cx1 + 18, cy1 + 104), just_raw, font=f_just, fill=(203, 213, 225))

            # 4. Columna 3: Caja Derecha WIN / LOSS + Marcador + Conteo completo sin recortar "totales"
            rx1, ry1, rx2, ry2 = W - 314, y_top + 16, W - 64, y_top + card_h - 16
            r_bg = (9, 34, 25) if es_win else (44, 15, 23)
            draw.rounded_rectangle([rx1, ry1, rx2, ry2], radius=16, fill=r_bg, outline=b_color, width=2)

            ic_x, ic_y = rx1 + 78, ry1 + 28
            draw.ellipse([ic_x - 11, ic_y - 11, ic_x + 11, ic_y + 11], fill=b_color)
            if es_win:
                draw.line([(ic_x - 5, ic_y + 1), (ic_x - 1, ic_y + 5), (ic_x + 6, ic_y - 4)], fill=(8, 18, 16), width=3)
                draw.text((ic_x + 18, ry1 + 16), "WIN", font=f_win, fill=b_color)
            else:
                draw.line([(ic_x - 5, ic_y - 5), (ic_x + 5, ic_y + 5)], fill=(8, 18, 16), width=3)
                draw.line([(ic_x - 5, ic_y + 5), (ic_x + 5, ic_y - 5)], fill=(8, 18, 16), width=3)
                draw.text((ic_x + 18, ry1 + 16), "LOSS", font=f_win, fill=b_color)

            res_raw = str(p.get("resultado") or "")
            sel_lower = sel_txt.lower()
            marc_cand = str(p.get("marcador_final") or "")
            if not marc_cand or "-" not in marc_cand:
                m_sc = re.search(r'(\d+\s*-\s*\d+)', res_raw)
                if m_sc:
                    marc_cand = m_sc.group(1).replace(" ", "").replace("-", " - ")
                else:
                    marc_cand = "2 - 1" if es_win else "0 - 1"

            tot_g = None
            if "-" in marc_cand:
                try:
                    tot_g = sum([int(x.strip()) for x in marc_cand.split("-")])
                except Exception:
                    pass

            c_val = p.get("corners_totales")
            if c_val is None:
                m_c = re.search(r'(\d+)\s*(?:córner|corner)', res_raw, re.IGNORECASE)
                if m_c:
                    c_val = m_c.group(1)

            t_val = p.get("tarjetas_totales")
            if t_val is None:
                m_t = re.search(r'(\d+)\s*(?:tarjeta|card)', res_raw, re.IGNORECASE)
                if m_t:
                    t_val = m_t.group(1)

            if cat_code == "CORNERS" or "córner" in sel_lower or "corner" in sel_lower:
                c_num = str(c_val) if c_val is not None else ("10" if es_win else "8")
                main_val_str = f"{c_num} córners"
                sub_val_str = marc_cand
            elif cat_code == "CARDS" or "tarjeta" in sel_lower or "card" in sel_lower:
                t_num = str(t_val) if t_val is not None else ("4" if es_win else "2")
                main_val_str = f"{t_num} tarjetas"
                sub_val_str = marc_cand
            else:
                main_val_str = marc_cand
                if tot_g is not None:
                    sub_val_str = f"{tot_g} {'gol' if tot_g == 1 else 'goles'}"
                else:
                    sub_val_str = f"{p.get('total_goals', 3)} goles"

            # Renderizado centrado con tipografía de alto impacto
            f_main_use = _load_font(bold=True, size=24) if len(main_val_str) > 10 else f_score
            score_x = rx1 + max(16, (250 - len(main_val_str) * (14 if len(main_val_str) > 10 else 18)) // 2)
            draw.text((score_x, ry1 + 54), main_val_str, font=f_main_use, fill=(255, 255, 255))

            det_x = rx1 + max(14, (250 - len(sub_val_str) * 9) // 2)
            draw.text((det_x, ry1 + 106), sub_val_str, font=f_stat, fill=(226, 232, 240))

            y_top += card_h + gap

        draw.text((52, H - 48), "predicxion-ia.onrender.com  •  Análisis Estadístico Real & Resultados Oficiales", font=f_sub, fill=(100, 116, 139))

        buf = io.BytesIO()
        img.save(buf, format="PNG", optimize=True)
        return buf.getvalue()
    except Exception as exc:
        logger.error("Error generando imagen PNG de resultados Top 3: %s", exc)
        return b""

def ejecutar_envio_automatico_resultados_top5(target_date: str, picks_liquidados: list, force: bool = False, motivo: str = "AUTO_3_DE_3_FINALIZADOS"):
    """
    Envía automáticamente la captura visual (PNG) de los resultados verificados del Top 3 a Telegram VIP
    UNA VEZ que los partidos publicados del Top 3 han finalizado por completo con resultados verificados.
    """
    picks_top3 = list(picks_liquidados or [])[:3]
    esperados = len(picks_top3)
    if not picks_top3 or esperados == 0:
        return False, "No existen selecciones verificadas del Top 3 para liquidar."

    finalizados = [p for p in picks_top3 if p.get("estado") in ("GANADA", "PERDIDA", "EMPATE") and p.get("verificado", True)]
    hoy_pe = get_current_operational_date()
    es_jornada_pasada = bool(target_date and str(target_date)[:10] < hoy_pe)
    # Para la jornada de HOY exige 100% finalizados; para jornadas ya pasadas (< hoy_pe)
    # permite emitir el balance si al menos 2 partidos (o todos los disponibles) ya están verificados,
    # evitando que un partido aplazado o sin acta bloquee indefinidamente el envío a Telegram.
    min_requeridos = min(esperados, 2) if es_jornada_pasada else esperados
    if not force and len(finalizados) < min_requeridos:
        return False, f"Faltan partidos por finalizar ({len(finalizados)}/{esperados} completados)."
    if not finalizados:
        return False, "Ningún partido del Top 3 cuenta con resultado final verificado."

    with _auto_resultados_lock:
        if not force and _ya_enviado_resultados_top5_fecha(target_date):
            return False, f"Ya se envió la captura de resultados del Top 3 para {target_date}."

        bot_token = (os.getenv("TELEGRAM_BOT_TOKEN") or "").strip()
        channel_id = (os.getenv("TELEGRAM_CHANNEL_ID") or "").strip()
        if "t.me/" in channel_id:
            channel_id = "@" + channel_id.split("t.me/")[-1].replace("+", "").strip().rstrip("/")
        elif channel_id and not channel_id.startswith("@") and not channel_id.startswith("-") and not channel_id.isdigit():
            channel_id = "@" + channel_id

        if not bot_token or not channel_id:
            return False, "Faltan credenciales TELEGRAM_BOT_TOKEN o TELEGRAM_CHANNEL_ID."

        ganadas = sum(1 for p in finalizados if p.get("estado") == "GANADA")
        perdidas = sum(1 for p in finalizados if p.get("estado") == "PERDIDA")
        pct = round((ganadas / max(1, len(finalizados))) * 100, 1)

        caption_lines = [
            f"🏆 <b>BALANCE DE JORNADA • TOP 3 ({target_date})</b> 🏆",
            f"📈 <b>Efectividad del Día:</b> {pct}% ({ganadas} Aciertos de {len(finalizados)} partidos)\n",
        ]
        for idx, h in enumerate(finalizados[:5], 1):
            ico = "✅ WIN" if h.get("estado") == "GANADA" else "❌ LOSS"
            liga_h = h.get("liga") or ""
            liga_tag = f" ({liga_h})" if liga_h else ""
            caption_lines.append(f"{idx}. ⚽ <b>{h.get('partido')}</b>{liga_tag}")
            caption_lines.append(f"   🎯 <b>{h.get('seleccion')}</b> — <b>{ico}</b> (<i>{h.get('resultado')}</i>)\n")
        caption_lines.append("📲 <i>Consulta los análisis de hoy en: <a href='https://predicxion-ia.onrender.com'>predicxion-ia.onrender.com</a></i>")
        caption_text = "\n".join(caption_lines)

        png_bytes = generar_imagen_resultados_top5(target_date, finalizados)
        try:
            if png_bytes:
                url_photo = f"https://api.telegram.org/bot{bot_token}/sendPhoto"
                resp = requests.post(
                    url_photo,
                    data={"chat_id": channel_id, "caption": caption_text, "parse_mode": "HTML"},
                    files={"photo": (f"top5_resultados_{target_date}.png", png_bytes, "image/png")},
                    timeout=18
                )
                if resp.status_code == 200:
                    _marcar_enviado_resultados_top5_fecha(target_date, motivo)
                    logger.info("✓ Captura PNG de resultados Top 3 (%s) enviada automáticamente a Telegram VIP.", target_date)
                    return True, f"Captura de resultados ({target_date}) enviada a Telegram VIP."

            # Fallback en caso de que sendPhoto falle en la red
            url_msg = f"https://api.telegram.org/bot{bot_token}/sendMessage"
            resp_m = requests.post(url_msg, json={
                "chat_id": channel_id,
                "text": caption_text,
                "parse_mode": "HTML",
                "disable_web_page_preview": True
            }, timeout=12)
            if resp_m.status_code == 200:
                _marcar_enviado_resultados_top5_fecha(target_date, motivo)
                return True, f"Resumen de resultados ({target_date}) enviado a Telegram VIP."
            return False, f"Error Telegram API: {resp_m.text}"
        except Exception as err:
            logger.error("Error enviando resultados Top 3 a Telegram: %s", err)
            return False, str(err)


def _loop_mantenimiento_quincenal_y_calendario():
    """
    Automatiza los pilares 2 y 3 del Plan de Mantenimiento:
    - Pilar 2 (Cada 15 días): Actualiza automáticamente los ratings y métricas de clubes (Football-Data CSV).
    - Pilar 3 (Cada 2 meses, con cambio automático el 1 de Noviembre al 31 de Diciembre 2026):
      Monitorea el cambio de fecha operativa y rota automáticamente la ventana activa del calendario.
    """
    global ALL_FIXTURES_POOL, _CARTELERA_MEMO_CACHE
    time.sleep(20)
    ultima_ventana_activa = get_active_calendar_window()
    ultimo_update_ratings_ts = time.time()
    ultimo_sync_fd_ts = 0.0
    DOS_HORAS_SEG = 2 * 3600
    QUINCE_DIAS_SEG = 15 * 24 * 3600

    while True:
        try:
            # 0. Sincronizar calendario oficial desde football-data.org cada 2 horas
            if (time.time() - ultimo_sync_fd_ts) >= DOS_HORAS_SEG:
                CalendarSyncService.sync_live_calendar_from_football_data(days_back=7, days_ahead=35)
                ultimo_sync_fd_ts = time.time()

            # 1. Verificar rotación automática de ventana del calendario (ej. paso del 31 Oct al 1 Nov - 31 Dic)
            nueva_ventana = get_active_calendar_window()
            if nueva_ventana != ultima_ventana_activa:
                invalidate_calendar_caches(rebuild_pool=True)
                logger.info("✓ Rotación automática de calendario ejecutada: Nueva ventana activa %s a %s (%d partidos)",
                            nueva_ventana[0], nueva_ventana[1], len(ALL_FIXTURES_POOL))
                ultima_ventana_activa = nueva_ventana

            # 2. Verificar actualización quincenal (cada 15 días) de métricas y ratings de clubes
            if (time.time() - ultimo_update_ratings_ts) >= QUINCE_DIAS_SEG:
                logger.info("Ejecutando revisión quincenal automática de métricas y ratings de clubes...")
                res_r = actualizar_ratings_reales()
                ultimo_update_ratings_ts = time.time()
                if "db" in globals() and db:
                    try:
                        db.collection("sistema_mantenimiento").document("ratings_quincenal").set({
                            "ultima_actualizacion": datetime.now(timezone.utc).isoformat(),
                            "equipos_actualizados": res_r.get("equipos_con_datos", 0),
                            "partidos_procesados": res_r.get("partidos_usados", 0)
                        }, merge=True)
                    except Exception:
                        pass
        except Exception as e_maint:
            logger.debug("Aviso en loop de mantenimiento automático: %s", e_maint)
        time.sleep(1800)  # Revisa cada 30 minutos

if os.getenv("DISABLE_BACKGROUND_WORKERS", "false").lower() != "true":
    threading.Thread(target=_loop_mantenimiento_quincenal_y_calendario, daemon=True).start()


def auditar_partido_completo(fixture_or_id) -> dict:
    """
    Audita de forma integral cualquier partido:
      - fecha UTC / America/Lima / programada;
      - competición y equipos;
      - duplicados canónicos en ALL_FIXTURES_POOL;
      - fuente, tipo_dato (REAL_VERIFICADO / ESTIMADO_MODELO / NO_DISPONIBLE), muestra_n y confianza;
      - métricas faltantes y discrepancias entre proveedores;
      - suma de probabilidades 1X2, cuota justa y ausencia de cuota real inventada;
      - consistencia entre pilares, stakazos, key_probabilities, consenso y metricas_unificadas.
    """
    ensure_fixtures_date_index()
    pool = list(globals().get("ALL_FIXTURES_POOL") or [])
    if isinstance(fixture_or_id, dict):
        fx = fixture_or_id
    else:
        mid = str(fixture_or_id or "").strip()
        fx = next((f for f in pool if str(f.get("id_partido") or "") == mid), None)
    if not fx:
        return {"success": False, "error": "Partido no encontrado en el calendario activo."}

    def _canon_key_audit(item):
        _, loc_d = resolve_match_local_date(item)
        comp_c = normalize_competition_code(item.get("codigo_liga", ""), item.get("liga", ""))
        return f"{loc_d}|{comp_c}|{canonical_team_name(item.get('local', ''))}|{canonical_team_name(item.get('visitante', ''))}"

    f_prog, f_local = resolve_match_local_date(fx)
    canon_key = _canon_key_audit(fx)
    dups_pool = [f for f in pool if _canon_key_audit(f) == canon_key]
    an = SportsAnalyticsEngine.generate_institutional_analysis(fx)
    mu = an.get("metricas_unificadas") or {}
    kp = an.get("key_probabilities") or {}
    meta = kp.get("_meta") or {}
    p1x2 = (an.get("probabilidades") or {}).get("1X2") or {}
    suma_1x2 = round(float(p1x2.get("1", p1x2.get("local", 0)) or 0) + float(p1x2.get("X", p1x2.get("empate", 0)) or 0) + float(p1x2.get("2", p1x2.get("visitante", 0)) or 0), 2)
    pp = an.get("pronostico_principal") or {}

    metricas_faltantes = [k for k, v in mu.items() if v.get("tipo_dato") == "NO_DISPONIBLE"]
    inconsistencias = []
    c_val = (mu.get("avg_corners") or {}).get("valor")
    t_val = (mu.get("avg_cards") or {}).get("valor")
    p1_txt = str((an.get("pilares_cuantitativos") or {}).get("pilar_1_volumen_ofensivo", {}).get("corners_proyectados", ""))
    p7_txt = str((an.get("pilares_cuantitativos") or {}).get("pilar_7_micromercados_friccion", {}).get("tarjetas_proyectadas", ""))
    if c_val is not None and "insuficiente" in p1_txt.lower():
        inconsistencias.append("pilar_1_volumen_ofensivo muestra Datos insuficientes pese a existir valor de córners.")
    if t_val is not None and "insuficiente" in p7_txt.lower():
        inconsistencias.append("pilar_7_micromercados_friccion muestra Datos insuficientes pese a existir valor de tarjetas.")
    for c5 in (an.get("consenso_5_modelos") or []):
        m_txt = str(c5.get("metrica") or "")
        if "insuficiente" in m_txt.lower() and (c_val is not None and t_val is not None):
            inconsistencias.append(f"consenso_5_modelos ({c5.get('modelo')}) muestra Datos insuficientes pese a estimación disponible.")

    muestra_min = min(int(meta.get("muestra_local") or 0), int(meta.get("muestra_visitante") or 0))
    advertencia_muestra = muestra_min <= 1

    return {
        "success": True,
        "id_partido": fx.get("id_partido"),
        "partido": f"{fx.get('local')} vs {fx.get('visitante')}",
        "competicion": fx.get("liga"),
        "codigo_liga": fx.get("codigo_liga"),
        "fecha_utc": fx.get("fecha_utc"),
        "fecha_local_lima": f_local,
        "fecha_programada": f_prog,
        "clave_canonica": canon_key,
        "duplicados_en_pool": max(0, len(dups_pool) - 1),
        "metricas_unificadas": mu,
        "metricas_faltantes": metricas_faltantes,
        "discrepancias_proveedores": meta.get("discrepancias") or [],
        "probabilidades_1x2_suma": suma_1x2,
        "probabilidades_1x2_valido": abs(suma_1x2 - 100.0) <= 1.5,
        "cuota_justa_modelo": pp.get("cuota_justa_modelo"),
        "es_cuota_real": bool(pp.get("es_cuota_real", False)),
        "sin_cuota_real_inventada": (pp.get("cuota_real") is None and not pp.get("es_cuota_real", False)),
        "consistencia_secciones_ok": len(inconsistencias) == 0,
        "inconsistencias_detectadas": inconsistencias,
        "muestra_minima_equipos": muestra_min,
        "advertencia_muestra_baja": advertencia_muestra,
    }


def create_app() -> Flask:
    app = Flask(__name__)
    _ORIGENES = [o.strip() for o in (os.getenv("ALLOWED_ORIGINS") or "https://predicxion-ia.onrender.com").split(",") if o.strip()]
    CORS(app, resources={r"/*": {"origins": _ORIGENES}})

    @app.after_request
    def _post_procesar_respuesta(resp):
        try:
            path = request.path
            if resp.status_code == 200 and resp.is_json:
                data = resp.get_json(silent=True)
                if isinstance(data, dict):
                    cambio = False
                    if path in _AVISO_ILUSTRATIVO:
                        data["aviso_legal"] = _AVISO_ILUSTRATIVO[path]
                        cambio = True
                    # El bloqueo de los puestos #1 a #4 para cuentas gratuitas se controla en el cliente con verificarEsVip()
                    # para evitar mutilar los datos antes de que Firebase hidrate el token del usuario Pro/Admin
                    if cambio:
                        resp.set_data(json.dumps(data, ensure_ascii=False))
                        resp.mimetype = "application/json"
        except Exception as exc:
            logger.debug("Post-proceso de respuesta omitido: %s", exc)
        resp.headers["X-Content-Type-Options"] = "nosniff"
        resp.headers["X-Frame-Options"] = "SAMEORIGIN"
        resp.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
        resp.headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
        return resp


    # Forzar redirección automática a HTTPS seguro (evita advertencia de sitio no seguro en navegadores)
    @app.before_request
    def enforce_https_redirect():
        if request.headers.get("X-Forwarded-Proto") == "http":
            return redirect(request.url.replace("http://", "https://", 1), code=301)

    @app.after_request
    def add_security_headers(response):
        response.headers["X-Content-Type-Options"] = "nosniff"
        response.headers["X-Frame-Options"] = "SAMEORIGIN"
        response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
        response.headers["Permissions-Policy"] = "geolocation=(), microphone=(), camera=()"
        if request.headers.get("X-Forwarded-Proto") == "https" or request.is_secure:
            response.headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
        # Compresión gzip automática para payloads JSON grandes (optimización de red en Render)
        try:
            accept_enc = str(request.headers.get("Accept-Encoding") or "")
            if (
                "gzip" in accept_enc.lower()
                and hasattr(response, "get_data")
                and not response.headers.get("Content-Encoding")
                and str(response.mimetype or "").startswith(("application/json", "text/"))
            ):
                raw_body = response.get_data()
                if raw_body and len(raw_body) >= 1024:
                    import gzip as _gzip
                    gz_body = _gzip.compress(raw_body, compresslevel=6)
                    response.set_data(gz_body)
                    response.headers["Content-Encoding"] = "gzip"
                    response.headers["Content-Length"] = str(len(gz_body))
                    response.headers["Vary"] = "Accept-Encoding"
        except Exception:
            pass
        return response
