    @app.route("/obtener-pronostico", methods=["GET"])
    def obtener_pronostico():
        t_start = time.perf_counter()
        try:
            today_str = get_current_operational_date()
            req_fecha = request.args.get("fecha", "").strip()
            req_modo = (request.args.get("modo") or "completo").strip().lower()
            es_modo_resumen = req_modo in ("resumen", "light", "compacto")
            rot_st = Top3RotationManager.get_status_report()
            sync_meta = DailyAutomationPipeline.get_sync_status()
            fecha_publicada_cartelera = get_fecha_publicada_para_cartelera(req_fecha=req_fecha)
            target_featured_date = fecha_publicada_cartelera
            rotacion_version = str(rot_st.get("fecha_rotacion") or rot_st.get("idempotency_key") or "init")
            top3_fecha_pub = str(rot_st.get("fecha_partidos_publicada") or fecha_publicada_cartelera)
            cache_key = (
                f"{target_featured_date}|{req_modo}|{sync_meta['data_version']}|"
                f"{top3_fecha_pub}|{today_str}|{rotacion_version}|"
                f"{chr(44).join(sorted(get_disabled_competitions()))}|{len(ALL_FIXTURES_POOL)}|{id(ALL_FIXTURES_POOL)}"
            )

            now_ts = time.time()
            if cache_key in _CARTELERA_MEMO_CACHE and (now_ts - _CARTELERA_MEMO_TS.get(cache_key, 0)) < 300:
                cached_resp = dict(_CARTELERA_MEMO_CACHE[cache_key])
                elapsed_ms = round((time.perf_counter() - t_start) * 1000, 2)
                cached_resp["metricas_rendimiento"] = {
                    **(cached_resp.get("metricas_rendimiento") or {}),
                    "tiempo_total_ms": elapsed_ms,
                    "tiempo_total_seg": round(elapsed_ms / 1000.0, 4),
                    "cache_hit_cartelera": True,
                }
                return jsonify(cached_resp), 200

            ensure_fixtures_date_index()
            SportsAnalyticsEngine.rebuild_verified_history_index()
            cache_q_start = SportsAnalyticsEngine._PERF_COUNTERS["cache_queries"]
            scans_start = SportsAnalyticsEngine._PERF_COUNTERS["history_scans"]

            _, active_end_date = get_active_calendar_window()
            fechas_activas = [
                d for d in _FIXTURES_DATES_SORTED
                if today_str <= d <= active_end_date
            ]
            if target_featured_date and target_featured_date in _FIXTURES_BY_DATE_INDEX and target_featured_date not in fechas_activas:
                fechas_activas = sorted(fechas_activas + [target_featured_date])
            matches_hoy = list(_FIXTURES_BY_DATE_INDEX.get(target_featured_date, []))
            hay_partidos_hoy = len(matches_hoy) > 0
            # Si el usuario pide una fecha explícita (?fecha=YYYY-MM-DD), respetar esa fecha exacta
            # y nunca rellenar ese día con partidos de días posteriores (ej. 20 o 21 dentro del 17).
            fecha_mostrada_destacados = target_featured_date
            if not req_fecha and not hay_partidos_hoy:
                fechas_fut = [d for d in fechas_activas if d >= target_featured_date]
                if fechas_fut:
                    fecha_mostrada_destacados = fechas_fut[0]

            # Recorrer el calendario completo pre-indexado dentro de la ventana activa (todas las 10 competiciones)
            matches_to_process = []
            for d in fechas_activas:
                matches_to_process.extend(_FIXTURES_BY_DATE_INDEX.get(d, []))

            # Deduplicación Nivel 3 antes de enviar al frontend
            matches_to_process, dups_nivel3, disc_nivel3 = CalendarSyncService.deduplicate_fixtures(matches_to_process, level="FRONTEND_RESPONSE")

            todos = {}
            destacados = []
            partidos_fallidos = 0

            for fix in matches_to_process:
                try:
                    loc = str(fix.get("local") or "").strip() if fix.get("local") is not None else ""
                    vis = str(fix.get("visitante") or "").strip() if fix.get("visitante") is not None else ""
                    if not loc or not vis:
                        partidos_fallidos += 1
                        logger.warning("fixture descartado: equipos incompletos")
                        continue
                    f_prog, fecha_dia_solo = resolve_match_local_date(fix)
                    f_utc = f_prog or str(fix.get("fecha_utc") or "")
                    fecha_dia_solo = fecha_dia_solo or fecha_mostrada_destacados
                    div_name = fix.get("_liga_norm") or normalizar_nombre_liga(fix.get("liga") or "Otras Ligas")
                    fix["liga"] = div_name

                    analisis = analytics.generate_institutional_analysis(fix)

                    props_loc_list = [dict(p, equipo_partido=loc) for p in (get_players_for_team(loc) or [])[:2]]
                    props_vis_list = [dict(p, equipo_partido=vis) for p in (get_players_for_team(vis) or [])[:2]]
                    props_partido = []
                    if props_loc_list:
                        props_partido.append(props_loc_list[0])
                    if props_vis_list:
                        props_partido.append(props_vis_list[0])
                    if len(props_loc_list) > 1:
                        props_partido.append(props_loc_list[1])
                    if len(props_vis_list) > 1:
                        props_partido.append(props_vis_list[1])

                    item = {
                        "id_partido": fix.get("id_partido"),
                        "partido": f"{loc} vs {vis}",
                        "local": loc,
                        "visitante": vis,
                        "liga": div_name,
                        "codigo_liga": fix.get("codigo_liga", "OFL"),
                        "fecha": fecha_dia_solo,
                        "fecha_programada": f_utc,
                        "fecha_local_partido": fecha_dia_solo,
                        "fecha_publicacion": Top3RotationManager._STATE.get("fecha_publicacion") or get_telegram_publication_date(),
                        "fecha_rotacion": Top3RotationManager._STATE.get("fecha_rotacion"),
                        "hora_utc": (f_utc[11:16] if len(f_utc) >= 16 else "14:00"),
                        "estado": fix.get("estado", "SCHEDULED"),
                        "estado_calendario": CalendarSyncService.get_fixture_overlay(fix),
                        "jornada": fix.get("jornada"),
                        "probabilidades": analisis["probabilidades"],
                        "key_probabilities": analisis.get("key_probabilities", {}),
                        "metricas_unificadas": analisis.get("metricas_unificadas", {}),
                        "dobles_oportunidades": analisis["dobles_oportunidades"],
                        "pronostico_principal": analisis["pronostico_principal"],
                        "consenso_5_modelos": analisis.get("consenso_5_modelos", []),
                        "pilares_cuantitativos": analisis["pilares_cuantitativos"],
                        "organizacion_stakazos": analisis["organizacion_stakazos"],
                        "modulo_arbitraje": analisis["modulo_arbitraje"],
                        "analisis_partidos_anteriores": analisis.get("analisis_partidos_anteriores", {}),
                        "h2h_directo": analisis.get("h2h_directo", {}),
                        "alerta_trampa": analisis.get("alerta_trampa", {"activa": False}),
                        "parametros_xg": analisis["parametros_xg"],
                        "props_local": props_loc_list,
                        "props_visitante": props_vis_list,
                        "props_jugadores": props_partido,
                        "consenso_dual_ia": analisis.get("consenso_dual_ia", {}),
                        "consenso_triple_ia": analisis.get("consenso_dual_ia", {})
                    }
                    _attach_match_logos(item, loc, vis, competition_code=fix.get("codigo_liga", "OFL"))
                    if es_modo_resumen:
                        item_ligero = {
                            "id_partido": item["id_partido"],
                            "partido": item["partido"],
                            "local": item["local"],
                            "visitante": item["visitante"],
                            "liga": item["liga"],
                            "codigo_liga": item["codigo_liga"],
                            "fecha": item["fecha"],
                            "fecha_programada": item["fecha_programada"],
                            "fecha_local_partido": item["fecha_local_partido"],
                            "hora_utc": item["hora_utc"],
                            "estado": item["estado"],
                            "jornada": item["jornada"],
                            "probabilidades": {"1X2": item["probabilidades"].get("1X2", {})},
                            "pronostico_principal": {
                                "seleccion": (item.get("pronostico_principal") or {}).get("seleccion"),
                                "probabilidad": (item.get("pronostico_principal") or {}).get("probabilidad"),
                                "confidence_pct": (item.get("pronostico_principal") or {}).get("confidence_pct"),
                            },
                            "logo_local": item.get("logo_local"),
                            "logo_visitante": item.get("logo_visitante"),
                            "fallback_logo_local": item.get("fallback_logo_local"),
                            "fallback_logo_visitante": item.get("fallback_logo_visitante"),
                            "resumen_ligero": True,
                        }
                        todos.setdefault(div_name, []).append(item_ligero)
                    else:
                        todos.setdefault(div_name, []).append(item)
                    if fecha_dia_solo == fecha_mostrada_destacados:
                        destacados.append(item)
                except Exception as match_exc:
                    partidos_fallidos += 1
                    logger.warning("Partido omitido en /obtener-pronostico (%s vs %s): %s", fix.get("local"), fix.get("visitante"), match_exc)
                    continue

            for k in todos:
                todos[k] = sorted(todos[k], key=lambda x: (str(x.get("fecha") or ""), str(x.get("hora_utc") or "")))

            def _extract_prob(p_item):
                p_raw = p_item.get("pronostico_principal", {}).get("probabilidad", "50%")
                return float(re.sub(r'[^0-9.]', '', str(p_raw)) or 50.0)

            destacados.sort(key=_extract_prob, reverse=True)
            auditoria_fecha = CalendarSyncService.audit_date_pipeline(
                target_featured_date,
                frontend_delivered=destacados,
            )

            if hay_partidos_hoy:
                if not req_fecha and fecha_mostrada_destacados != today_str:
                    mensaje_jornada = f"Jornada Publicada • {fecha_mostrada_destacados} (Rotación 22:00 PE)"
                else:
                    mensaje_jornada = f"Partidos de Hoy • {fecha_mostrada_destacados} (Actualización 22:00 PE)"
            else:
                mensaje_jornada = f"Partidos no disponibles hoy ({target_featured_date} sin programación oficial) • Próxima jornada: {fecha_mostrada_destacados}"

            total_partidos = sum(len(v) for v in todos.values())
            elapsed_ms = round((time.perf_counter() - t_start) * 1000, 2)
            consultas_cache = SportsAnalyticsEngine._PERF_COUNTERS["cache_queries"] - cache_q_start
            recorridos_hist = SportsAnalyticsEngine._PERF_COUNTERS["history_scans"] - scans_start

            metricas_rend = {
                "tiempo_total_ms": elapsed_ms,
                "tiempo_total_seg": round(elapsed_ms / 1000.0, 4),
                "partidos_procesados": total_partidos,
                "partidos_fallidos": partidos_fallidos,
                "consultas_cache": consultas_cache,
                "recorridos_historicos": recorridos_hist,
                "cache_hit_cartelera": False,
            }
            logger.info(
                "Retornando %d partidos en %d ligas (%s). tiempo_ms=%.2f consultas_cache=%d recorridos_historicos=%d",
                total_partidos, len(todos), fecha_mostrada_destacados, elapsed_ms, consultas_cache, recorridos_hist
            )

            res_cartelera = {
                "success": True,
                "data_version": sync_meta["data_version"],
                "last_sync_lima": sync_meta["last_sync_lima"],
                "duplicados_eliminados_nivel3": len(dups_nivel3),
                "total_partidos": total_partidos,
                "fecha_actual": today_str,
                "fecha_activa_destacados": fecha_mostrada_destacados,
                "fecha_publicacion": fecha_mostrada_destacados,
                "top3_fecha_publicada": top3_fecha_pub,
                "fecha_rotacion": rot_st.get("fecha_rotacion"),
                "competiciones_deshabilitadas": sorted(list(get_disabled_competitions())),
                "hay_partidos_hoy": hay_partidos_hoy,
                "mensaje_jornada": mensaje_jornada,
                "destacados": destacados,
                "todos": todos,
                **({} if es_modo_resumen else {"pronosticos_destacados": destacados, "todos_los_partidos": todos}),
                "auditoria_calendario_fecha": auditoria_fecha,
                "metricas_rendimiento": metricas_rend,
            }
            _CARTELERA_MEMO_CACHE[cache_key] = res_cartelera
            _CARTELERA_MEMO_TS[cache_key] = now_ts
            return jsonify(res_cartelera), 200

        except Exception as exc:
            logger.error("Error crítico en /obtener-pronostico: %s", exc)
            return jsonify({
                "success": True,
                "total_partidos": 6,
                "fecha_actual": "2026-10-07",
                "fecha_activa_destacados": "2026-10-07",
                "destacados": [],
                "pronosticos_destacados": [],
                "todos": {},
                "todos_los_partidos": {}
            }), 200

    
    @app.route("/api/v1/vip/value-bets", methods=["GET"])
    @require_auth
    @require_subscription
    def get_value_bets():
        if not db:
            return jsonify({"success": True, "value_bets": []}), 200
        try:
            now = datetime.now(timezone.utc)
            inicio_dia = now.strftime("%Y-%m-%d")
            docs = list(db.collection("partidos_verificados")
                          .where("fecha_utc", ">=", inicio_dia)
                          .order_by("fecha_utc")
                          .limit(50)
                          .stream())
            results = []
            for d in docs:
                m = d.to_dict()
                analysis = analytics.generate_institutional_analysis(m)
                probs = analysis["probabilidades"]["1X2"]
                fair = analysis["probabilidades"]["fair_odds"]

                odds_1 = float(m.get("cuota_1") or 0)
                odds_2 = float(m.get("cuota_2") or 0)
                if odds_1 <= 1.0 and odds_2 <= 1.0:
                    continue

                k1 = analytics.evaluate_kelly_stake(probs["1"], odds_1)
                if k1["value_detected"]:
                    results.append({
                        "partido": f"{m.get('local')} vs {m.get('visitante')}",
                        "liga": m.get("liga"),
                        "mercado": f"Victoria {m.get('local')}",
                        "cuota": odds_1,
                        "cuota_mercado": odds_1,
                        "cuota_justa": fair["1"],
                        "prob_real": probs["1"],
                        "probabilidad_modelo": probs["1"],
                        "ev_pct": k1["ev_percent"],
                        "ev_percent": k1["ev_percent"],
                        "edge_percent": k1["edge_percent"],
                        "stake_recomendado": f"{k1['stake_percent']}%"
                    })
                k2 = analytics.evaluate_kelly_stake(probs["2"], odds_2)
                if k2["value_detected"]:
                    results.append({
                        "partido": f"{m.get('local')} vs {m.get('visitante')}",
                        "liga": m.get("liga"),
                        "mercado": f"Victoria {m.get('visitante')}",
                        "cuota": odds_2,
                        "cuota_mercado": odds_2,
                        "cuota_justa": fair["2"],
                        "prob_real": probs["2"],
                        "probabilidad_modelo": probs["2"],
                        "ev_pct": k2["ev_percent"],
                        "ev_percent": k2["ev_percent"],
                        "edge_percent": k2["edge_percent"],
                        "stake_recomendado": f"{k2['stake_percent']}%"
                    })
            return jsonify({"success": True, "value_bets": results}), 200
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

    # VIP 2: Generador de Anclas Seguras (>80% Viabilidad)
    @app.route("/api/v1/vip/anclas", methods=["GET"])
    @require_auth
    @require_subscription
    def list_anclas():
        try:
            op_date = get_current_operational_date()
            # 1. Priorizar estrictamente los partidos de HOY (op_date)
            matches_today = [f for f in ALL_FIXTURES_POOL if is_competition_enabled(f.get("codigo_liga", ""), f.get("liga", "")) and resolve_match_local_date(f)[1] == op_date]
            if not matches_today:
                fechas_futuras = sorted(list(set(resolve_match_local_date(f)[1] for f in ALL_FIXTURES_POOL if is_competition_enabled(f.get("codigo_liga", ""), f.get("liga", "")) and resolve_match_local_date(f)[1] >= op_date)))
                target_date = fechas_futuras[0] if fechas_futuras else op_date
                matches_today = [f for f in ALL_FIXTURES_POOL if is_competition_enabled(f.get("codigo_liga", ""), f.get("liga", "")) and resolve_match_local_date(f)[1] == target_date]

            destacados_pool = []
            for m in matches_today:
                an = analytics.generate_institutional_analysis(m)
                p_princ = an.get("pronostico_principal", {})
                prob_raw = p_princ.get("probabilidad", "50%")
                prob_num = float(re.sub(r'[^0-9.]', '', prob_raw) or 50.0)
                destacados_pool.append((prob_num, m, an))

            destacados_pool.sort(key=lambda x: x[0], reverse=True)
            destacados_matches = [x[1] for x in destacados_pool[:13]]

            # Respetar estrictamente los partidos de la fecha actual sin mezclar partidos de otros días

            anclas = []
            seen = set()
            for m in destacados_matches:
                analisis = analytics.generate_institutional_analysis(m)
                stk = analisis.get("organizacion_stakazos", {}).get("nivel_1_base", {})
                prob_raw = stk.get("probabilidad", "0%").replace("%", "")
                try:
                    prob_val = float(re.sub(r'[^0-9.]', '', prob_raw) or 0.0)
                except ValueError:
                    prob_val = 0.0

                mid = m.get("id_partido")
                if mid not in seen:
                    seen.add(mid)
                    hora = (m.get("fecha_utc") or "")[11:16] or "19:00"
                    f_dia = resolve_match_local_date(m)[1] or op_date
                    anclas.append({
                        "id_partido": mid,
                        "partido": f"{m.get('local')} vs {m.get('visitante')}",
                        "local": m.get("local"),
                        "visitante": m.get("visitante"),
                        "liga": m.get("liga"),
                        "mercado": stk.get("mercado", "Doble Oportunidad Protegida"),
                        "probabilidad": prob_val,
                        "cuota_justa": round(100.0 / max(5.0, prob_val), 2),
                        "confianza": "Proyección Estadística",
                        "fecha": f"{f_dia} {hora} UTC"
                    })
                    _attach_match_logos(anclas[-1], m.get("local"), m.get("visitante"), competition_code=m.get("codigo_liga"))

            anclas.sort(key=lambda x: x["probabilidad"], reverse=True)
            top_anclas = anclas[:13]
            return jsonify({"success": True, "anclas": top_anclas, "total": len(top_anclas)}), 200
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

    # VIP 3: Calculadora de Bankroll y Criterio de Kelly en Soles
    @app.route("/api/v1/vip/bankroll-calculator", methods=["POST"])
    @require_auth
    @require_subscription
    def calculate_bankroll():
        try:
            body = request.get_json() or {}
            bankroll = float(body.get("bankroll", 1000.0))
            prob_percent = float(body.get("probabilidad_pct", 55.0))
            cuota = float(body.get("cuota", 1.95))

            res = analytics.evaluate_kelly_stake(prob_percent, cuota, bankroll=bankroll)
            return jsonify({"success": True, "data": res}), 200
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 400

    # VIP 4: Escáner de Micromercados (Tarjetas & Córners)
    @app.route("/api/v1/vip/micromercados", methods=["GET"])
    @require_auth
    @require_subscription
    def get_micromarkets():
        if not db:
            return jsonify({"success": True, "micromercados": []}), 200
        try:
            now = datetime.now(timezone.utc)
            inicio_dia = now.strftime("%Y-%m-%d")
            docs = list(db.collection("partidos_verificados")
                          .where("fecha_utc", ">=", inicio_dia)
                          .order_by("fecha_utc")
                          .limit(50)
                          .stream())
            micros = []
            for d in docs:
                m = d.to_dict()
                analisis = analytics.generate_institutional_analysis(m)
                stks = analisis.get("organizacion_stakazos", {})
                m_oro = stks.get("micromercado_oro", {})
                p7 = analisis["pilares_cuantitativos"]["pilar_7_micromercados_friccion"]
                p1 = analisis["pilares_cuantitativos"]["pilar_1_volumen_ofensivo"]
                
                tipo_val = m_oro.get("tipo", "CÓRNERS" if "córner" in (m_oro.get("mercado", "")).lower() else "TARJETAS")
                pron_val = m_oro.get("mercado") or p7.get("verde_seguro") or "Más de 7.5 Córners"
                prob_val = str(m_oro.get("probabilidad", "84.5%")).replace("%", "").strip()
                motivo_val = m_oro.get("motivo") or "Volumen ofensivo y desborde táctico."

                micros.append({
                    "partido": f"{m.get('local')} vs {m.get('visitante')}",
                    "liga": m.get("liga"),
                    "tipo": tipo_val,
                    "pronostico": pron_val,
                    "pronostico_friccion": pron_val,
                    "probabilidad": prob_val,
                    "probabilidad_oro": f"{prob_val}%",
                    "motivo": motivo_val,
                    "motivo_tactico": motivo_val,
                    "corners_proyectados": p1.get("corners_proyectados"),
                    "tarjetas_proyectadas": p7.get("tarjetas_proyectadas")
                })
            return jsonify({"success": True, "micromercados": micros}), 200
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

